INSERT INTO `quest_offer_reward_locale` (`ID`, `Locale`, `OfferRewardText`, `VerifiedBuild`) VALUES
(41267, 'frFR', 'Merci de nous avoir aidés, $gpêcheur:pêcheuse;. Nous avions grandement besoin de ce talang.', 0),
(41272, 'frFR', 'Salutations, $gpêcheur:pêcheuse;. Je peux vous débarrasser de ces perches. Votre don sera bien utilisé.', 0),
(41277, 'frFR', 'Salutations, $R $gpêcheur:pêcheuse;. Les Valarjar vous remercient d''avoir apporté ces raies-tempête.', 0),
(41282, 'frFR', 'Vous ne pouviez pas mieux tomber, pêcheur. Nos gens manquaient de provisions.', 0),
(41287, 'frFR', 'Merci de nous avoir aidés, herboriste. Nous avions grandement besoin de cet aethril.', 0),
(41288, 'frFR', 'Merci pour votre aide, |3-6($c). Nous avions vraiment besoin de cet aethril.', 0),
(41292, 'frFR', 'Salutations, herboriste. Je peux vous débarrasser de cette feuillerêve. Votre don sera bien utilisé.', 0),
(41297, 'frFR', 'Salutations, $R herboriste. Les Valarjar vous remercient d''avoir apporté ce fjarnskaggl.', 0),
(41298, 'frFR', 'Salutations, $R $C. Les Valarjar vous remercient d''avoir apporté ce fjarnskaggl.', 0),
(41302, 'frFR', 'Vous ne pouviez pas mieux tomber, herboriste. Nos gens manquaient de provisions.', 0),
(41303, 'frFR', 'Vous ne pouviez pas mieux tomber, $C. Nos gens manquaient de provisions.', 0),
(41309, 'frFR', 'Ça fait plaisir de voir un visage ami, je ne sais pas combien de temps j''aurais encore pu tenir seul !', 0),
(41311, 'frFR', 'Merci de nous avoir aidés, $gmineur:mineuse;. Nous avions grandement besoin de ce tellurium.', 0),
(41312, 'frFR', 'Salutations, mineur. Je peux vous débarrasser de cette pierre de ley. Votre don sera bien utilisé.', 0),
(41313, 'frFR', 'Salutations, $R $gmineur:mineuse;. Les Valarjar vous remercient d''avoir apporté ce tellurium.', 0),
(41314, 'frFR', 'Vous ne pouviez pas mieux tomber, mineur. Nos gens manquaient de provisions.', 0),
(41316, 'frFR', 'Salutations, $C. Je peux vous débarrasser de cette pierre de ley. Votre don sera bien utilisé.', 0),
(41317, 'frFR', 'Salutations, $R $C. Les Valarjar vous remercient d''avoir apporté ce tellurium.', 0),
(41318, 'frFR', 'Vous ne pouviez pas mieux tomber, $C. Nos gens manquaient de provisions.', 0),
(41326, 'frFR', 'Merci de nous avoir aidés, $gdépeceur:dépeceuse;. Nous avions grandement besoin de ces écailles de tempête.', 0),
(41327, 'frFR', 'Merci pour votre aide, |3-6($c). Nous avions vraiment besoin de cette écaille de tempête.', 0),
(41332, 'frFR', 'Félicitations, $ct $n.$b$bNous compterons sur vous dans les jours à venir.', 0),
(41335, 'frFR', 'Un choix judicieux. Ne perdons pas de temps, commençons les recherches tout de suite !', 0),
(41338, 'frFR', 'Salutations, $gdépeceur:dépeceuse;. Je peux vous débarrasser de ce cuir. Votre don sera bien utilisé.', 0),
(41339, 'frFR', 'Salutations, $C. Je peux vous débarrasser de ce cuir. Votre don sera bien utilisé.', 0),
(41344, 'frFR', 'Salutations, $R $gdépeceur:dépeceuse;. Les Valarjar vous remercient d''avoir apporté ces écailles de tempête.', 0),
(41345, 'frFR', 'Salutations, $R $C. Les Valarjar vous remercient d''avoir apporté ces écailles de tempête.', 0),
(41351, 'frFR', 'Vous ne pouviez pas mieux tomber, $C. Nos gens manquaient de provisions.', 0),
(41368, 'frFR', 'Ah, un billet à ordre. Le paiement de M. Front-de-Pierre.$B$BJuste à temps, semble-t-il.', 0),
(41409, 'frFR', 'Fjolrik est mort en l''honneur de Jandvik. Nous nous souviendrons de sa bravoure.', 0),
(41410, 'frFR', '<Fjolrik vous regarde d''un air faible.>$B$BVous êtes $grevenu:revenue; à temps...', 0),
(41413, 'frFR', '$ct accepter d''apprendre à Zen’Kiki ? $b$bZen’Kiki garder tout ça juste ici !', 0),
(41415, 'frFR', 'N''importe laquelle des trois armes dont vous avez entendu parler serait un atout considérable dans la guerre contre la Légion.$b$bMais votre croisade doit commencer par l''une d''elles, il vous faut donc choisir.', 0),
(41422, 'frFR', '< Le visage de Mylune s''illumine de joie >$B$BAlors il nous reste de l''espoir !', 0),
(41425, 'frFR', 'Les troupes de Saj''tar étaient bien plus fortes que nous le pensions.', 0),
(41426, 'frFR', 'Je dois exprimer ma gratitude pour les vrykuls que vous avez sauvés aujourd''hui.', 0),
(41436, 'frFR', 'S''enfoncer dans le Rêve alors que de telles ténèbres l''envahissent n''est pas une tâche simple, que peu de druides osent tenter, mais je crains que votre voyage soit loin d''être terminé.', 0),
(41449, 'frFR', 'Mes préparatifs sont terminés. Êtes-vous $gprêt:prête; à entrer dans le Rêve ?', 0),
(41452, 'frFR', 'Tout est à sa place. Nous sommes un peu plus près de nous installer.', 0),
(41453, 'frFR', 'Voilà un rebondissement intéressant.', 0),
(41462, 'frFR', 'Ahhhh... Bien joué, je suis sûr que nos amis à fourrure ici présents vous sont très reconnaissants de vos efforts.', 0),
(41463, 'frFR', 'Comme c''est gentil de la part de Mayruna d''envoyer de l''aide. J''avais presque perdu espoir.', 0),
(41464, 'frFR', 'Je suis soulagé, bien qu''il nous reste encore beaucoup à faire.', 0),
(41465, 'frFR', 'Ahh, voyez ! Je vous avais dit qu''elle ne ternirait pas. Maintenant plus rien ne me relie à cet imbécile...$b$bQu''est-ce que c''est ? Un complot pour affaiblir sa position ? Quoi qu''il en soit, le mal est fait. Mieux vaut prévenir que guérir.', 0),
(41467, 'frFR', 'Quelle histoire troublante !', 0),
(41469, 'frFR', 'Content de vous revoir. Je vois que nous sommes prêts à commencer.', 0),
(41473, 'frFR', 'Ce charmant monsieur me disait justement combien il aime sa forêt. Aidons-le !', 0),
(41474, 'frFR', 'Leur vue est bien plus dégagée maintenant !', 0),
(41475, 'frFR', 'Au final, ce sera bénéfique pour tout le monde : il y aura plus de sabres et les loups trouveront plus facilement à se nourrir.', 0),
(41480, 'frFR', 'Quelle créature gloutonne.', 0),
(41485, 'frFR', 'Me voilà bien soulagé, $n.', 0),
(41494, 'frFR', 'Votre aide a rendu tout cela possible. Merci.', 0),
(41499, 'frFR', 'Plus de nagas ne recevront aucun de mes frères !', 0),
(41510, 'frFR', 'Sage décision, $gdevin:devineresse;... J''ai ouvert dans mon dos un portail astral vers Dalaran : il nous sera facile à tous de circuler entre le QG et les Îles Brisées. Passez par là pour gagner Dalaran. Vous pouvez revenir ici à tout moment si vous avez besoin de renforcer un artefact ou de donner des ordres à vos partisans.$b$bQue les forces des éléments vous guident, $gdevin:devineresse;', 0),
(41540, 'frFR', 'Je ne connais pas tous les détails, mais un prisonnier démon nous a donné la première piste sérieuse sur l''endroit où se trouve Alleria Coursevent depuis très longtemps.$B$BLa générale-rôdeuse a rejoint des membres des Pérégrins sur le Rivage Brisé. Elle constitue une équipe, et votre présence est cruciale à son succès.', 0),
(41541, 'frFR', 'Vous voilà ! Je savais que vous seriez $gravi:ravie; de trouver la Puissance des Titans.$B$BNe faites pas attention au vieux Huey. Il n''y a pas de place pour les griffons magiciens en ville.', 0),
(41542, 'frFR', 'C''est un grand honneur pour mon frère Wuho et moi de venir avec vous, $n. La griffe prédatrice de notre peuple est considérée comme un artefact sacré, et je suis sûr que nous la retrouverons ensemble. Et avec de telles armes, la Légion sera aussi chassée de notre terre. Une fois pour toutes !', 0),
(41574, 'frFR', 'Vous vous sentirez peut-être un peu $gétourdi:étourdie; après être $gpassé:passée; par ce téléporteur. Les îles Brisées, ce n''est pas exactement la porte à côté, après tout.', 0),
(41575, 'frFR', '< La balise commence à briller lorsque vous la remplissez de mana ancien. >', 0),
(41606, 'frFR', 'Je ne sais pas qui vous êtes, mais vous n''êtes pas un géant des mers, et cela me suffit.', 0),
(41607, 'frFR', 'Ils sont vivants ? Voilà une bonne nouvelle. Leur connaissance des défenses sera inestimable.', 0),
(41618, 'frFR', 'Je regrette seulement de ne pas avoir eu l''occasion de l''avoir le premier.$B$BBah ! Son corps peut pourrir dans ces eaux, je m''en moque.', 0),
(41625, 'frFR', 'Vous cherchez donc Courroux-de-Lumière ? Une arme dangereuse, assurément.$B$BIl y a longtemps, le Kirin Tor en a confié la garde au Vol draconique bleu. Elle fut enfermée dans le seul endroit capable de contenir son pouvoir débridé : le Caveau du Nexus.$B$BCependant, je n''y suis pas allé depuis un moment. Après la dissolution du Vol draconique bleu, le Nexus a été abandonné. Impossible de savoir si le Caveau du Nexus est toujours intact, ni ce qui peut attendre dans le Nexus lui-même.', 0),
(41626, 'frFR', 'Cela semble être un dispositif de communication couramment utilisé par les éthériens.$B$BPeut-être est-ce la clé pour découvrir qui se cache derrière les événements du sanctuaire draconique.', 0),
(41627, 'frFR', 'Alors le Nexus est tombé aux mains de la Confrérie de l''Éthérium... et ce n''est même pas le pire. Mais s''ils comptent vraiment élargir la fenêtre vers le Cercle du Vide, c''est une grave menace pour tout Azeroth. Apparemment, le destin lui-même vous a $gguidé:guidée; jusqu''ici, $n. Non seulement vous trouverez votre artefact, mais vous bouleverserez aussi les plans de la Confrérie de l''Éthérium ! Malheureusement, je ne pourrai pas vous aider dans votre entreprise, mais mon conseil est que vous ne pourrez pas m''aider non plus...', 0),
(41630, 'frFR', 'Azuregos !$B$BApparemment, il est retourné au Nexus chercher les artefacts. C''est à lui que Maligos avait confié la garde des objets magiques de la famille des dragons.$B$BJe crains de devoir vous demander une dernière faveur, $n.', 0),
(41631, 'frFR', 'Je vous remercie d''avoir sauvé Azuregos, $n. Je peux me reposer tranquille en sachant que le Nexus est sous sa protection.$B$BQuant à vous, je vois que vous êtes plein de surprises. Jamais de mon temps je n''avais vu un $C capable de maîtriser les énergies chaotiques du Courroux-de-Lumière. $B$BVous êtes vraiment le héros dont nous avons besoin pour affronter la Légion.', 0),
(41632, 'frFR', 'Alors les dragons se sont montrés utiles ? C''est bien, nous aurons peut-être besoin de leur aide dans la guerre à venir.', 0),
(41633, 'frFR', 'Merci de nous avoir aidés, $gforgeron:forgeronne;. Nous avions grandement besoin de ces jambières.', 0),
(41634, 'frFR', 'Salutations, $gforgeron:forgeronne;. Je peux vous débarrasser de ces protège-bras. Votre don sera bien utilisé.', 0),
(41635, 'frFR', 'Merci beaucoup, forgeron. Ces bottes ne seront pas gaspillées.', 0),
(41636, 'frFR', 'Salutations, $R $gforgeron:forgeronne;. Les Valarjar vous remercient d''avoir apporté cette cuirasse.', 0),
(41637, 'frFR', 'Vous ne pouviez pas mieux tomber, forgeron. Nos gens manquaient de provisions.', 0),
(41638, 'frFR', 'Le Kirin Tor vous remercie.', 0),
(41639, 'frFR', 'Merci de nous avoir aidés, $gmaroquinier:maroquinière;. Nous avions grandement besoin de ces épaulières.', 0),
(41640, 'frFR', 'Salutations, $gtravailleur:travailleuse; du cuir. Je peux vous débarrasser de ce masque. Votre don sera bien utilisé.', 0),
(41641, 'frFR', 'Merci beaucoup, $gtanneur:tanneuse;. Ces bandages ne seront pas gaspillés.', 0),
(41642, 'frFR', 'Salutations, $R $gtravailleur du cuir:travailleuse du cuir;. Les Valarjar vous remercient d''avoir apporté ces bottes.', 0),
(41643, 'frFR', 'Vous ne pouviez pas mieux tomber, travailleur du cuir. Nos gens manquaient de provisions.', 0),
(41644, 'frFR', 'Le Kirin Tor vous remercie.', 0),
(41645, 'frFR', 'Merci de nous avoir aidés, $gtailleur:tailleuse;. Nous avions grandement besoin de ces épaulettes.', 0),
(41646, 'frFR', 'Salutations, $gtailleur:tailleuse;. Je peux vous débarrasser de ces gants. Votre don sera bien utilisé.', 0),
(41647, 'frFR', 'Merci beaucoup, $gcouturier:couturière;. Ces vêtements ne devraient pas être gaspillés.', 0),
(41648, 'frFR', 'Salutations, $R $gtailleur:tailleuse;. Les Valarjar vous remercient d''avoir apporté ces brassards.', 0),
(41649, 'frFR', 'Vous ne pouviez pas mieux tomber, tailleur. Nos gens manquaient de provisions.', 0),
