INSERT INTO `quest_request_items_locale` (`ID`, `Locale`, `CompletionText`, `VerifiedBuild`) VALUES
(8552, 'frFR', 'Bonjour. Avez-vous affaire avec moi ?', 0),
(8553, 'frFR', 'NULL', 0),
(8554, 'frFR', 'Avez-vous récupéré mon coutelas, $N ?', 0),
(8555, 'frFR', 'NULL', 0),
(8556, 'frFR', 'M''avez-vous apporté l''anneau et les matériaux, $N ?', 0),
(8557, 'frFR', 'Avez-vous apporté les matériaux pour le manteau, $N ?', 0),
(8558, 'frFR', 'M''avez-vous apporté les composants dont j''ai besoin, $N ?', 0),
(8559, 'frFR', 'Vous avez rapporté les objets que j''ai demandés, $N ?', 0),
(8560, 'frFR', 'Avez-vous apporté les composants dont j''ai besoin, $N ?', 0),
(8561, 'frFR', 'M''avez-vous apporté les composants que j''ai demandés, $N ?', 0),
(8562, 'frFR', 'Dans sa demeure d''Ahn’Qiraj, le terrible C''Thun attend, plongé dans le sommeil.', 0),
(8564, 'frFR', 'NULL', 0),
(8565, 'frFR', 'NULL', 0),
(8566, 'frFR', 'NULL', 0),
