(9966, 'frFR', 'NULL', 0),
(9967, 'frFR', 'Le combat est terminé quand vous ou votre adversaire êtes mort sur le sol.', 0),
(9968, 'frFR', 'Avez-vous mes échantillons ?', 0),
(9969, 'frFR', 'NULL', 0),
(9970, 'frFR', 'Le combat est terminé quand vous ou votre adversaire êtes mort sur le sol.', 0),
(9971, 'frFR', 'Avez-vous déjà découvert quelque chose ?', 0),
(9972, 'frFR', 'Le combat est terminé quand vous ou votre adversaire êtes mort sur le sol.', 0),
(9973, 'frFR', 'Le combat est terminé quand vous ou votre adversaire êtes mort sur le sol.', 0),
(9974, 'frFR', 'NULL', 0),
