(10688, 'frFR', 'Avez-vous accompli la tâche que je vous ai confiée ?', 0),
(10689, 'frFR', 'NULL', 0),
(10690, 'frFR', 'Que puis-je faire pour vous aujourd''hui ?', 0),
(10691, 'frFR', 'NULL', 0),
(10692, 'frFR', 'Avez-vous accompli ce que je vous ai demandé, $N ?', 0),
(10693, 'frFR', 'NULL', 0),
