(10739, 'frFR', 'NULL', 0),
(10740, 'frFR', 'NULL', 0),
(10741, 'frFR', 'NULL', 0),
(10742, 'frFR', 'Ce n''est que par la mort de Goc et de Gorgrom le Mange-dragon que nous libérerons les Mok''Nathal.', 0),
(10744, 'frFR', 'NULL', 0),
(10747, 'frFR', 'Avez-vous eu beaucoup de mal à attraper les dragonnets ? J''espère que vous ne vous êtes pas $groussi:roussie; !', 0),
(10748, 'frFR', 'Vous avez déjà réglé son compte à Maxnar le Cendregueule ?$B$BVous avez du mal à le trouver ? D''après ce que je sais, si vous prenez à droite en entrant dans leurs cavernes, le passage finit par tourner et vous mène à lui.', 0),
(10749, 'frFR', '$C, déjà de retour ? Avez-vous le poison ?', 0),
(10750, 'frFR', 'Qu''avez-vous à signaler, $gsoldat:soldate; ?', 0),
(10751, 'frFR', 'Qu''avez-vous à signaler, $gsoldat:soldate; ?', 0),
(10752, 'frFR', 'NULL', 0),
(10753, 'frFR', 'Avez-vous porté la main de la justice ?', 0),
(10754, 'frFR', 'Vous avez quelque chose à me montrer, $N ?', 0),
(10755, 'frFR', 'Vous avez quelque chose à me montrer, $N ?', 0),
(10756, 'frFR', 'Qu’est-ce que c’est ?', 0),
(10757, 'frFR', 'Avez-vous obtenu les matériaux que j''ai demandés ?', 0),
(10758, 'frFR', 'Avez-vous fait ce que je vous ai demandé, $C ?', 0),
