INSERT INTO `quest_request_items_locale` (`ID`, `Locale`, `CompletionText`, `VerifiedBuild`) VALUES
(11598, 'frFR', 'Ce n''est pas nous qui avons construit sur le réseau de tunnels nérubien, ce sont ces monstres qui ont creusé jusqu''à nous !', 0),
(11600, 'frFR', 'Vous avez parlé à William, $N ?', 0),
(11602, 'frFR', 'Vous devez détruire ces sacs d''œufs !', 0),
(11603, 'frFR', '<Le vieil homme lève les yeux vers vous, le regard vide.>', 0),
(11605, 'frFR', '<La voix lointaine revient.>$b$bAvez-vous retrouvé les noms des anciens errants ?', 0),
(11606, 'frFR', 'Le temps nous est compté, $c.', 0),
(11607, 'frFR', 'Comment se portent les esprits des innocents ?', 0),
(11608, 'frFR', 'Alors ?', 0),
(11609, 'frFR', 'Avez-vous récupéré un jeu complet d''objets rituels ?', 0),
(11610, 'frFR', 'Avez-vous accompli les cérémonies pour les ancêtres ?', 0),
(11612, 'frFR', 'Avez-vous commencé à débarrasser la carrière de nos ennemis ?', 0),
(11613, 'frFR', 'Avez-vous réussi, $r ? Les Kvaldirs sont des guerriers cruels. N''attendez aucune pitié de leur part.', 0),
(11615, 'frFR', 'Est-il mort ?', 0),
(11616, 'frFR', 'Que signifie cette interruption ? Ne m''accablez pas de sottises !', 0),
(11617, 'frFR', 'Avez-vous réussi à détruire les plateformes volantes des chasseurs de mages ?', 0),
(11619, 'frFR', 'Avez-vous vaincu Gamel, $r ?', 0),
(11623, 'frFR', 'Vous êtes-vous $gdébarrassé:débarrassée; du conservateur ?', 0),
(11625, 'frFR', 'Avez-vous le trident ?', 0),
(11628, 'frFR', 'Avez-vous apporté les peaux de mammouth ?', 0),
(11629, 'frFR', '$N, vous voilà de retour. Qu''avez-vous appris ?$B$BQuel est ce bruit ?', 0),
(11630, 'frFR', 'Avez-vous la terre dont le Sage Aeire a besoin pour terminer la cape ?', 0),
(11631, 'frFR', 'Quand vous estimerez en avoir assez vu, rapportez-moi le primordial.', 0),
(11632, 'frFR', 'Qu''avez-vous là ?', 0),
(11633, 'frFR', 'Avez-vous fini de repérer les temples dans la forteresse du Fléau ?', 0),
(11637, 'frFR', 'Vite, $c, utilisez le fétiche sur moi avant qu''il ne soit trop tard.', 0),
(11638, 'frFR', 'Vous revenez plus tôt que je ne l''aurais cru. Qu''avez-vous appris ?', 0),
(11639, 'frFR', 'Lok''tar, $c. Vous ne pouvez pas avoir tué tout ce qu''il y avait à Magmoth en si peu de temps !', 0),
(11640, 'frFR', 'Nous devons entrer dans cette nécropole si nous voulons percer les lignes du Fléau et ouvrir un passage pour les villageois.', 0),
(11641, 'frFR', 'Ne me dérangez pas, sauf si vous venez rendre compte d''une mission réussie.', 0),
(11643, 'frFR', 'Avez-vous trouvé le P.T.T. ?', 0),
(11644, 'frFR', 'N''oubliez pas, la brume, c''est mauvais !', 0),
(11645, 'frFR', 'Vous avez toutes mes fournitures, $c ? Je ne peux RIEN faire sans toutes mes affaires !', 0),
(11647, 'frFR', 'Avez-vous utilisé le totem sur tous les chaudrons de peste ?', 0),
(11648, 'frFR', 'Alors ? Savez-vous où dame Evanor est retenue ?', 0),
(11649, 'frFR', 'Quand vous aurez les atomes nécessaires, je combinerai une partie de mon essence avec les leurs. Le résultat vous donnera ce qu''il vous faut.', 0),
(11650, 'frFR', 'Pourquoi ai-je du mal à croire que vous avez tout rassemblé de ma liste ?', 0),
(11652, 'frFR', 'Alors ? Que s''est-il passé ?', 0),
(11653, 'frFR', 'Êtes-vous $gsûr:sûre; d''avoir testé le blaster sur assez de ces bêtes monstrueuses ?', 0),
(11654, 'frFR', 'Comment... comment m''avez-vous trouvé ?', 0),
(11655, 'frFR', 'Par le sang et l''honneur, vous devez servir... Rapportez les reliques rohartes.', 0),
(11656, 'frFR', 'C''est fait ? Les navires sont-ils en flammes ?', 0),
(11658, 'frFR', 'Il nous faudra beaucoup de leurs vêtements pour que ça marche. Je ne suis pas couturière... il faudra juste trouver quelque chose à votre taille !$B$BEnsuite, j''ajouterai une touche de mon génie d''ingénieur et pouf, vous aurez exactement l''allure du rôle que vous devez jouer.', 0),
(11660, 'frFR', 'Trouvez le cor du vieux marinier !', 0),
(11661, 'frFR', 'Orabus doit être détruit !', 0),
(11665, 'frFR', 'Vous avez déjà attrapé des crocodiles dans les égouts ?', 0),
(11666, 'frFR', 'Comment se passe la pêche aujourd''hui, $gmon gars:ma belle; ?', 0),
(11667, 'frFR', 'Dites-moi que vous l’avez attrapé. Dites-moi que vous avez attrapé ce fils de carpe.', 0),
(11668, 'frFR', 'Quelle est la prise du jour, $gmon gars:ma belle; ?', 0),
(11669, 'frFR', 'Le gangresang est une merveille de l''évolution. Il peut survivre dans n''importe quelle eau, et même dans la lave, et les pêcheurs sont son seul prédateur naturel.$b$bVous avez eu de la chance avec votre proie ?', 0),
(11670, 'frFR', 'Alors, c''est terminé ? Vous avez fait le sale boulot et fait accuser les orcs de l''avant-poste de Bor’gorok ?', 0),
(11671, 'frFR', 'Avez-vous récupéré la clé de Salrand ?', 0),
(11676, 'frFR', 'Sauvez ces prisonniers !', 0),
(11679, 'frFR', 'Vous osez m''approcher, $gmortel:mortelle; ?$b$bPar égard pour vos enfants à naître, priez pour que votre cause en vaille la peine.', 0),
(11683, 'frFR', 'Vous ne pouvez sûrement pas avoir éliminé autant de membres du Fléau en si peu de temps ?', 0),
(11684, 'frFR', 'Avez-vous marqué l''emplacement des gouffres ?', 0),
(11685, 'frFR', 'Grandpère Mahan me dit que vous avez accepté d''aider à faire s''effondrer les tunnels.', 0),
(11686, 'frFR', 'Avez-vous fouillé les fermes ?', 0),
(11687, 'frFR', '$N, vous revenez !', 0),
(11688, 'frFR', 'Il me faut plus de temps ! Tenez ces porcs loin de mes kodos !', 0),
(11690, 'frFR', 'Sortez-les de ces champs infestés par le Fléau !', 0),
(11695, 'frFR', 'Avez-vous pu trouver la corne ? La légende était-elle vraie ?', 0),
(11699, 'frFR', 'Vous avez tout ce qu''il faut ?', 0),
(11705, 'frFR', '<Hurlenfer hausse un sourcil à votre intention.>$B$BQu''est-ce que j''entends à propos d''un nécroseigneur du Fléau ?', 0),
(11706, 'frFR', 'Avez-vous libéré Alluvius et détruit l''assaut nérubien ?', 0),
(11708, 'frFR', 'Bien le bonjour.', 0),
(11710, 'frFR', 'Il faudra beaucoup de pièces détachées pour faire tourner ce truc.$B$BDites-moi que vous êtes $grevenu:revenue; avec tout ce dont nous avons besoin.', 0),
(11711, 'frFR', '<Tungok grogne.>$B$BAvez-vous réglé le sort du déserteur ?', 0),
(11712, 'frFR', 'Combien de mécagnomes avez-vous réussi à maudire de nouveau, $c ?', 0),
(11713, 'frFR', 'Avez-vous marqué l''emplacement des gouffres ?', 0),
(11714, 'frFR', 'Ce boulot pue...', 0),
(11715, 'frFR', 'Avez-vous ce carburant ?', 0),
(11716, 'frFR', 'Les tests doivent continuer !', 0),
(11717, 'frFR', 'Le pollen est la clé !', 0),
(11718, 'frFR', 'Apportez ces peaux aussi vite que possible ! Je ne pourrai pas terminer la machine sans elles !', 0),
(11721, 'frFR', 'La poudre peut servir à affaiblir tous les magnataures. C''est pourquoi les hommes-rats du secteur la gardent de si près.', 0),
(11722, 'frFR', 'Déjà de retour ?', 0),
(11723, 'frFR', 'Eh bien, avez-vous déjà déployé le Sismo-trembleur 5000 ?', 0),
(11724, 'frFR', 'Salutations !', 0),
(11726, 'frFR', 'Avez-vous ces sachets d''épices ?', 0),
(11728, 'frFR', 'Avez-vous récupéré le microfilm ?', 0),
(11729, 'frFR', 'Hé !', 0),
(11730, 'frFR', 'Combien de robots avez-vous réussi à reprogrammer ?', 0),
(11788, 'frFR', 'Les lieutenants du maître des rouages Mécazod sont-ils éliminés ?', 0),
(11789, 'frFR', 'L''antivenin... l''avez-vous ?', 0),
(11792, 'frFR', 'Vous voilà de retour, $N.', 0),
(11793, 'frFR', 'Le Messager Vurenn vous envoie ?', 0),
(11794, 'frFR', 'Avez-vous accompli la tâche que je vous ai demandée, $N ?', 0),
(11795, 'frFR', 'Avez-vous ces insignes ?', 0),
(11796, 'frFR', 'Avez-vous déjà sabordé l''épave ?', 0),
(11797, 'frFR', 'Vous êtes de retour. J''espère que vous avez réduit les effectifs de l''ennemi.', 0),
(11798, 'frFR', 'Jinky m''a dit de m''attendre à votre visite. C''est fait ?', 0),
(11807, 'frFR', 'Honorez la flamme des Tranchantes !', 0),
(11865, 'frFR', 'N''éprouvez aucune pitié pour eux, $r.', 0),
(11866, 'frFR', 'Des oreilles feront très bien l''affaire...', 0),
(11867, 'frFR', 'Qu''il s''agisse de chasseurs de trésors ou de chasseurs sanguinaires des étendues désolées, tout être qui soutient Nesingwary et ose s''en prendre à notre chère faune sera considéré comme un ennemi de la SdPA.$B$BSi vous tuez ces sales sympathisants de Nesingwary, rapportez-moi la preuve de leur trépas et vous serez récompensé$g:e; par une bénédiction des druides de la SdPA.', 0),
(11868, 'frFR', 'La nature exige justice !', 0),
(11869, 'frFR', 'Notre travail est macabre, $N.', 0),
(11871, 'frFR', 'Nous offrirons à ces animaux une sépulture digne de ce nom.', 0),
(11872, 'frFR', 'M''apportez-vous de bonnes nouvelles ?', 0),
(11875, 'frFR', 'Avez-vous des résidus pour moi ?', 0),
(11876, 'frFR', 'Ils doivent être libérés !', 0),
(11877, 'frFR', 'Êtes-vous $grevenu:revenue; avec les plans ?', 0),
(11879, 'frFR', 'Que s’est-il passé ?', 0),
(11880, 'frFR', 'Avez-vous ces relevés ? Ce gnome va encore me hurler dessus si je n''obtiens pas ses précieuses données.', 0),
(11881, 'frFR', 'N''échouez pas ! Je compte sur vous.', 0),
(11884, 'frFR', 'Les avez-vous abattus ?', 0),
(11885, 'frFR', 'Avez-vous accompli votre tâche, $n ?', 0),
(11886, 'frFR', 'Qu''avez-vous découvert ?', 0),
(11887, 'frFR', 'Qu''avez-vous là ?', 0),
(11889, 'frFR', 'Vous êtes de retour. De bonnes nouvelles, j''espère ?', 0),
(11890, 'frFR', 'Qu''avez-vous appris, $r ?', 0),
(11891, 'frFR', 'Avez-vous percé leurs secrets ?', 0),
(11892, 'frFR', 'Le Boucher boréen est-il mort ?', 0),
(11893, 'frFR', 'Avez-vous chargé le totem ?', 0),
(11894, 'frFR', 'Avez-vous récupéré cette peau de caribou tannée pour moi ?', 0),
(11895, 'frFR', 'Avez-vous déjà maîtrisé la tempête ?', 0),
(11896, 'frFR', 'Avez-vous déchaîné la puissance de la tempête sur ces créations contre nature ?', 0),
(11897, 'frFR', 'Avez-vous réussi, $N ? Il faut ralentir le Fléau, sinon le Donjon de la Bravoure sera submergé.', 0),
(11898, 'frFR', 'Avez-vous vaincu le prince Valanar ?', 0),
(11899, 'frFR', 'Comment avancent vos progrès ?', 0),
(11900, 'frFR', 'Avez-vous relevé tous mes instruments, $c ?', 0),
(11903, 'frFR', 'Vous donnez une bonne raclée à ces goules, j''espère ?', 0),
(11904, 'frFR', 'Le minerai, $N, il est en sécurité ?', 0),
(11905, 'frFR', 'Êtes-vous $gallé:allée; à la faille ?', 0),
(11906, 'frFR', 'Si nous ne prenons pas soin de la terre, elle ne nous supportera pas longtemps.', 0),
(11907, 'frFR', 'Les sous-chefs sont-ils éliminés ?', 0),
(11908, 'frFR', 'Avez-vous récupéré mon livre ?', 0),
(11909, 'frFR', 'C''est donc fini ? La menace du Maître des rouages Mécazod a-t-elle été éliminée ?', 0),
(11910, 'frFR', 'Avez-vous recueilli les échantillons que j''ai demandés ?', 0),
(11911, 'frFR', 'Les anciens cristallins... Existent-ils ?', 0),
(11912, 'frFR', 'Avez-vous pu trouver de la nourriture ?', 0),
(11913, 'frFR', 'Avez-vous fait ce que je vous ai demandé, $N ?', 0),
(11914, 'frFR', 'Avez-vous les essences de mana que j''ai demandées ?', 0),
(11917, 'frFR', 'Vous revenez $gvictorieux:victorieuse; ?', 0),
(11918, 'frFR', 'Vous êtes-vous $gfamiliarisé:familiarisée; avec notre ennemi, $c ?', 0),
(11919, 'frFR', 'Avez-vous réussi à capturer un des drakes du Nexus ?', 0),
(11921, 'frFR', 'Vite ! Il n''y a pas de temps à perdre !', 0),
(11922, 'frFR', 'Vite ! Il n''y a pas de temps à perdre !', 0),
(11923, 'frFR', 'Attraper des torches, c''est très amusant, vous ne trouvez pas ? Mais faites attention ! Vous ne voudriez pas vous roussir !', 0),
(11926, 'frFR', 'Vite ! Il n''y a pas de temps à perdre !', 0),
(11931, 'frFR', 'Vite, $gmortel:mortelle;.$b$bMalygos gagne en puissance à chaque instant qui passe.', 0),
(11933, 'frFR', 'Vous rayonnez presque, $r. Qu''avez-vous là ?', 0),
(11935, 'frFR', 'Vous rayonnez presque, $r. Qu''avez-vous là ?', 0),
(11936, 'frFR', 'Avez-vous détruit les œufs des bleus, $c ?', 0),
(11938, 'frFR', 'C''est fait ?', 0),
(11940, 'frFR', 'Avez-vous récupéré un dragonnet de drake pour mes études ?', 0),
(11941, 'frFR', 'Qu''avez-vous trouvé, $c ?', 0),
(11942, 'frFR', 'Vous prenez votre temps, hein ? Je ne sais pas combien de temps encore je pourrai retenir cette liche.', 0),
(11943, 'frFR', 'Avez-vous découvert d''autres pièces de la prison ?', 0),
(11944, 'frFR', 'Avez-vous progressé ? Nous sommes dans une mauvaise passe.', 0),
(11945, 'frFR', 'Avez-vous réussi, $N ?  Nos proches d''Unu’pe comptent sur vos efforts.', 0),
(11947, 'frFR', 'Vous revenez $gvictorieux:victorieuse; ?', 0),
(11948, 'frFR', 'Vous revenez $gvictorieux:victorieuse; ?', 0),
(11949, 'frFR', 'Nous nous battons bec et ongles, $N. Nous ne céderons pas un pouce de terrain à ces kvaldirs sans leur faire payer très cher.', 0),
(11951, 'frFR', 'Avez-vous rassemblé les éclats de mana dont j''ai besoin ?', 0),
(11952, 'frFR', 'Vous revenez $gvictorieux:victorieuse; ?', 0),
(11953, 'frFR', 'Vous revenez $gvictorieux:victorieuse; ?', 0),
(11954, 'frFR', 'Vous revenez $gvictorieux:victorieuse; ?', 0),
(11956, 'frFR', 'Vous voilà de retour, $N. Avez-vous le phylactère ?', 0),
(11957, 'frFR', 'Saragosa ne doit pas rester en vie !', 0),
(11958, 'frFR', 'L''équilibre naturel a été rompu encore et encore ces derniers temps.$B$BJ''espère que vous pourrez nous aider à survivre au bouleversement de notre mode de vie.', 0),
(11959, 'frFR', 'Est-ce le sang de Loguhn ou le vôtre, $r ?', 0),
(11960, 'frFR', 'Combien de petits avez-vous pu sauver en si peu de temps ?', 0),
(11961, 'frFR', 'Le totem, $r. Vous l''avez ?', 0),
(11962, 'frFR', 'Qu''avez-vous là ?', 0),
(11964, 'frFR', 'Un salut enflammé à vous, honorable $c.  Bienvenue sur cette terre sacrée de la fête du Feu du solstice d''été.', 0),
(11965, 'frFR', 'Avez-vous rallié les survivants, $N ?', 0),
(11966, 'frFR', 'Un salut enflammé à vous, honorable $c.  Bienvenue sur cette terre sacrée de la fête du Feu du solstice d''été.', 0),
(11967, 'frFR', 'Vous avez des nouvelles pour moi, $n ?', 0),
(11968, 'frFR', 'Avez-vous fait ce que je vous ai demandé, $N ?', 0),
(11969, 'frFR', 'Avez-vous rencontré Keristrasza ?', 0),
(11972, 'frFR', 'Salutations, $N. Vous avez l''air $ginquiet:inquiète;, mais vous devriez vous réjouir. Le seigneur du Givre est vaincu !', 0),
(11973, 'frFR', 'Avez-vous localisé Keristrasza ? Avez-vous pu la libérer de ses chaînes ?', 0),
(11978, 'frFR', 'Sans armure ni armes, nos nouvelles recrues seront sans défense pendant leur trajet jusqu''au Marteau d''Agmar.', 0),
(11980, 'frFR', 'Pas de pitié, $r. Massacrez les Anub''ars !', 0),
(11982, 'frFR', 'Qu''avez-vous à signaler ?', 0),
(11983, 'frFR', 'Ils renforceront la Horde, commandant.', 0),
(11984, 'frFR', 'Avez-vous réussi à mettre en cage un troll des glaces ?', 0),
(11985, 'frFR', 'Avez-vous pu tuer le commandant ?', 0),
(11986, 'frFR', 'Qu''avez-vous là ?', 0),
(11988, 'frFR', 'Avez-vous assez de fragments pour reconstituer la clé de voûte ?', 0),
(11989, 'frFR', 'Bon choix, mon ami. Vous ne vivrez pas assez pour le regretter...', 0),
(11990, 'frFR', 'Toi avoir les trucs, man ?', 0),
(11993, 'frFR', 'Qu''avez-vous découvert ?', 0),
(11998, 'frFR', 'Qu''avez-vous là ?', 0),
(11999, 'frFR', 'Vous êtes de retour. Qu''avez-vous découvert ?', 0),
(12000, 'frFR', 'Vous êtes de retour. Qu''avez-vous découvert ?', 0),
(12002, 'frFR', 'Comment vont les choses à Thor Modan ?', 0),
(12003, 'frFR', 'Je suppose que vous n''avez pas réussi à trouver les tunnels, n''est-ce pas ?', 0),
(12004, 'frFR', 'Avez-vous empêché l''accord entre le vol draconique bleu et l''Éthérium ?', 0),
(12005, 'frFR', 'Avez-vous empêché l''accord entre le vol draconique bleu et l''Éthérium ?', 0),
(12006, 'frFR', 'Quelque chose me dit que vous n''avez pas encore tout à fait tué assez de ces profanateurs !', 0),
(12007, 'frFR', 'Toi avoir l''Œil des prophètes, man ?', 0),
(12009, 'frFR', 'Combien de crabes avez-vous réussi à récupérer ?', 0),
(12012, 'frFR', 'Qu''est-ce qui te tracasse, mon enfant ?', 0),
(12013, 'frFR', 'Me prenez-vous pour un imbécile ? Arcanimus dévore toujours les âmes de mes frères et sœurs, $c !', 0),
(12014, 'frFR', 'Qu''avez-vous trouvé ?', 0),
(12016, 'frFR', 'Toi revenir avec chair succulente de Kili''ua ?', 0),
(12017, 'frFR', 'Il me semblait avoir aperçu des convulsions... Tu''u''gwar est-il mort ?', 0),
(12019, 'frFR', 'Salutations, $N.', 0),
(12022, 'frFR', 'Buvez-en une, puis lancez-en une. C.E.R.V.O.I.S.E peut encaisser les mauvais traitements, c''est pour ça que je l''ai construit.', 0),
(12026, 'frFR', 'Qu''avez-vous là ?', 0),
(12028, 'frFR', 'Qu’en pensez-vous ?', 0),
(12029, 'frFR', 'Alors, c''est fait, $N ?', 0),
(12031, 'frFR', '<L''ancien Mana''loa regarde à travers vous, sentant que vous n''avez pas encore terminé sa tâche.>', 0),
(12032, 'frFR', '$N, vous voilà de retour !', 0),
(12033, 'frFR', 'Nous écraserons le Fléau !', 0),
(12035, 'frFR', 'Vous avez fini, $N ?', 0),
(12038, 'frFR', 'Alors, c''est fait, $N ?', 0),
(12039, 'frFR', 'Qu''est-ce que la vie sans risques ?', 0),
(12040, 'frFR', 'L''empire d''Azjol se relèvera !', 0),
(12041, 'frFR', 'Qu''avez-vous là ?', 0),
(12043, 'frFR', 'Hein ? Qui êtes-vous ? Que voulez-vous ?', 0),
(12044, 'frFR', 'Avez-vous récupéré le minerai ? Mon transporteur sera bientôt de retour - il faut expédier cette cargaison pendant que le combat fait rage !', 0),
(12045, 'frFR', 'Avez-vous les éclats ? J''ai presque terminé l''unité de réfrigération principale.', 0),
(12046, 'frFR', 'Comment se passe la chasse ? Avez-vous mes peaux ?', 0),
(12047, 'frFR', 'Y avait-il des éclats à trouver ?', 0),
(12048, 'frFR', '<Borus jette ses outils.>$B$BCes trucs sont inutiles !', 0),
(12049, 'frFR', 'Vous avez tout récupéré ? Vous en sentez l''odeur à plein nez, en tout cas.', 0),
(12050, 'frFR', 'Où est ce porteur ? J''espère que les jormungars ne l''ont pas eu. Il transportait une bonne charge, cette fois.', 0),
(12052, 'frFR', 'Je me souviens de vous. Vous n''êtes pas mort$g:e;, alors ces misérables harpies feraient bien de l''être.', 0),
(12053, 'frFR', 'C''est un défi, $N !', 0),
(12054, 'frFR', 'Avez-vous apporté des quantités suffisantes de l''herbe ?', 0),
(12055, 'frFR', 'Qu''avez-vous là ?', 0),
(12056, 'frFR', 'C''est une tête d''orc coupée dans votre sac, ou êtes-vous simplement $gcontent:contente; de me voir ?', 0),
(12057, 'frFR', '<Gort hausse un sourcil.>', 0),
(12058, 'frFR', 'Avez-vous découvert les secrets de Thor Modan ?', 0),
(12059, 'frFR', 'Qu''avez-vous là ?', 0),
(12060, 'frFR', 'Déjà de retour ?', 0),
(12061, 'frFR', 'Déjà de retour ?', 0),
(12064, 'frFR', 'Apportez-moi ces fragments de clé !', 0),
(12065, 'frFR', 'Quelles nouvelles de la plage, $c ?', 0),
(12066, 'frFR', 'Quelles nouvelles de la plage, $c ?', 0),
(12067, 'frFR', 'Une lettre pour moi ?$B$B<Le commandant observe votre visage un instant.>$B$BJe suppose que non... ce doit être une mauvaise nouvelle.', 0),
(12068, 'frFR', 'Content de vous voir, $n.$b$bVous avez trouvé les tablettes ?', 0),
(12069, 'frFR', 'Qu''y a-t-il, $N ? Je suis extrêmement occupé.', 0),
(12070, 'frFR', 'Avez-vous transmis ma bénédiction aux géants ?', 0),
(12072, 'frFR', 'Notez que les chevaucheurs de guerre ne sont dressés que pour combattre à l''intérieur de Brume-glace. Essayez de les emmener ailleurs et ils vous désarçonneront.', 0),
(12073, 'frFR', 'Avez-vous attaqué les nains de fer comme je l''ai demandé ?', 0),
(12075, 'frFR', 'Vous revenez donc avec mon échantillon ? Je suis content que le froid ne vous ait pas emporté.', 0),
(12076, 'frFR', 'On dirait que vous avez encore un peu de crachat sur l''épaule, $r. Faites attention, ou ça va vous ronger l''armure.', 0),
(12077, 'frFR', 'L''avorton veut que nous nous battions pour lui, je suppose. Ceci est mon air surpris.', 0),
(12078, 'frFR', 'Vous êtes de retour ! Avez-vous les bêtes ? Il faut que je sorte d''ici... Je suis presque sûr que Ko’char a essayé de me marcher dessus il y a quelques minutes.', 0),
(12079, 'frFR', 'La bataille continue. Revenez avec de bonnes nouvelles ou laissez-moi, petit.', 0),
(12080, 'frFR', 'J''espère que vous m''apportez de bonnes nouvelles, $gpetit:petite;.', 0),
(12083, 'frFR', 'Qu''avez-vous trouvé là-haut dans les bois ?', 0),
(12084, 'frFR', 'Qu''avez-vous trouvé là-haut dans ces bois ?', 0),
(12085, 'frFR', 'Qu''est-ce que c''est ? Vous pensez envoyer une lettre ?$B$BTout le courrier passe d''abord par moi. Il y a des espions et des traîtres parmi nous !$B$B<Le suzerain vous toise et vous vous demandez s''il va vous faire tuer sur-le-champ.>$B$BTrès bien, mais faites vite. Et si ce que je lis ne me plaît pas, je vous donne en pâture à mes worgs.$B$B<Agmar sourit tandis que Gar''mak et Lak''tuk se tournent vers vous comme si vous étiez leur prochain repas.>', 0),
(12089, 'frFR', 'Vous venez toucher une prime ?', 0),
(12090, 'frFR', 'Vous venez toucher une prime ?', 0),
(12091, 'frFR', 'Vous venez toucher une prime ?', 0),
(12092, 'frFR', 'Un autre avantage de sauver les anciens pourrait être qu''ils envisagent d''aider l''Alliance dans ses difficultés. Quoi qu''il en soit, c''est la chose à faire.$B$BAlors, combien avez-vous réussi à en renforcer, $c ?', 0),
(12093, 'frFR', 'Avez-vous neutralisé les runes sur la côte ?', 0),
(12094, 'frFR', 'Avez-vous trouvé les pierres anciennes ?', 0),
(12096, 'frFR', 'Si nous pouvons sauver les anciens avant les dryades et les elfes de la nuit du Repos des étoiles, peut-être envisageront-elles de s''allier à la Horde.$B$BOu du moins, peut-être y réfléchiront-elles à deux fois avant de nous attaquer.$B$BAlors, combien en avez-vous réussi à sauver jusqu''ici ?', 0),
(12097, 'frFR', '<Gort hausse un sourcil.>$B$BDéjà de retour ?', 0),
(12099, 'frFR', 'Avez-vous pu libérer certains de mes frères ?', 0),
(12100, 'frFR', 'Tuez les bêtes pour empêcher la propagation et rapportez-moi un organe résistant à la putréfaction.', 0),
(12101, 'frFR', 'Qu’y a-t-il ?', 0),
(12102, 'frFR', 'Avez-vous le lilas rubis ?', 0),
(12104, 'frFR', 'Avez-vous le vaccin ?', 0),
(12105, 'frFR', 'Qu''est-ce que vous avez là ?', 0),
(12107, 'frFR', 'Qu''y a-t-il, $N ? Vous avez le teint rouge.$B$BPrenez un moment pour reprendre votre souffle.', 0),
(12110, 'frFR', 'Qu''y a-t-il, $N ? Vous avez le teint rouge.$B$BPrenez un moment pour reprendre votre souffle.', 0),
(12113, 'frFR', 'Mon ventre gargouille, $r. Vous avez réussi à ramasser de quoi manger ?', 0),
(12114, 'frFR', 'Comment se passe la chasse aux trolls ?', 0),
(12115, 'frFR', 'Qu''y a-t-il, $r ?', 0),
(12116, 'frFR', 'Qu''avez-vous trouvé dans la crypte pour Kraz, $c ?', 0),
(12119, 'frFR', 'Oui, que puis-je faire pour vous, $r ?', 0),
(12120, 'frFR', 'Vous avez trouvé le maillet, $n ?', 0),
(12122, 'frFR', 'Oui, que puis-je faire pour vous, $r ?', 0),
(12123, 'frFR', 'Il est bon de vous rencontrer enfin en personne, $N. Je vous connais depuis avant votre naissance.', 0),
(12124, 'frFR', 'Il est bon de vous rencontrer enfin en personne, $N. Je vous connais depuis avant votre naissance.', 0),
(12125, 'frFR', 'Apportez-moi le sang des faibles.', 0),
(12126, 'frFR', 'Emplissez la gemme du pouvoir de l''impie !', 0),
(12127, 'frFR', 'Nous sommes tous au service du givre ici, en Norfendre.', 0),
(12129, 'frFR', 'Avez-vous pu obtenir ces plans des forgerunes ?', 0),
(12130, 'frFR', 'Je vois que vous vous en êtes sorti$g:e; en un seul morceau. Avez-vous les pièces ?', 0),
(12131, 'frFR', 'Eh bien, avez-vous trouvé ces piles ?', 0),
(12134, 'frFR', 'Vous êtes-vous déjà $goccupé:occupée; des chasseurs du village, $N ?', 0),
(12135, 'frFR', '$N, vous aviez promis de sauver les enfants !', 0),
(12136, 'frFR', 'Il était temps ! Où étiez-vous $gpassé:passée; ?', 0),
(12137, 'frFR', 'Avez-vous accompli votre tâche dans la crypte, $c ?', 0),
(12140, 'frFR', 'Ne perdez pas de temps, $N. Angrathar attend !', 0),
(12142, 'frFR', 'Avez-vous achevé ces nuisibles ?', 0),
(12143, 'frFR', 'C''est fait ?', 0),
(12145, 'frFR', 'T’es pas un vrai mec tant que t’as pas tué un dragon… mec.', 0),
(12148, 'frFR', 'Avez-vous trouvé quelque chose ?', 0),
(12149, 'frFR', 'Avez-vous vaincu le magnataur ?', 0),
(12150, 'frFR', 'Avez-vous obtenu le nom ? Savez-vous qui est le seigneur de guerre magnataure ?', 0),
(12151, 'frFR', 'Avez-vous mis fin à cette menace pour de bon ?', 0),
(12152, 'frFR', 'Jin''arrak a-t-il été vaincu, $N ?', 0),
(12153, 'frFR', 'Avez-vous pu franchir les défenses du thane de fer ?', 0),
(12154, 'frFR', 'Avez-vous désactivé la source d''énergie de leurs forges runiques ?', 0),
(12159, 'frFR', 'Avez-vous déjà fait reposer mes amis, $N ?', 0),
(12164, 'frFR', 'Il est bon de vous voir, $n.', 0),
(12165, 'frFR', 'Est-ce que... vous avez ces plans que j''ai demandés ?', 0),
(12166, 'frFR', 'Il est dommage que nous ne puissions pas soigner les ours et les élans qui ont été victimes de la présence du Fléau.$B$BAu moins, nous pouvons empêcher la souillure de se propager davantage.', 0),
(12167, 'frFR', 'Les cultistes sont un fléau pour la création !', 0),
(12168, 'frFR', 'Je sens que quelque chose d''impur est proche.$B$BC''est sur vous ! Qu''est-ce que c''est, $N ?', 0),
(12169, 'frFR', 'Je sens que le haut-sectateur Zangus est toujours en vie.$B$BQuelque chose ne va pas, $N ? Peut-être avez-vous besoin de vous reposer d''abord ?', 0),
(12170, 'frFR', 'Avez-vous tué les chiens de l''Alliance ? La victoire doit être à nous !', 0),
(12172, 'frFR', 'Êtes-vous $gaccordé:accordée; ? Il ne faut pas mentir à ce sujet, $N.$B$BSi vous ne vous préparez pas correctement et que je vous enseigne le sort, la première fois que vous le lancerez sera la dernière fois que quiconque vous verra !', 0),
(12174, 'frFR', 'Qu''avez-vous là, $gsoldat:soldate; ?', 0),
(12175, 'frFR', 'Toi avoir ces peaux, man ?', 0),
(12176, 'frFR', 'Toi avoir ces peaux, man ?', 0),
(12177, 'frFR', 'Toi avoir les trucs, man ?', 0),
(12178, 'frFR', 'Avez-vous la moindre idée de qui vous parlez ?', 0),
(12180, 'frFR', 'Avez-vous retrouvé les prospecteurs disparus ?', 0),
(12181, 'frFR', 'Livraison de gaz toxique hautement mortel à Vexevenin ? Approchez, approchez !', 0),
(12182, 'frFR', 'C''est vous $gle livreur:la livreuse; ?', 0),
(12183, 'frFR', 'Avez-vous récupéré l''uniforme ?', 0),
(12184, 'frFR', 'Avez-vous ces clichés ?', 0),
(12185, 'frFR', 'Le déguisement a-t-il fonctionné ?', 0),
(12188, 'frFR', 'Le résidu servira d''agent réactif pour activer la brûlure !', 0),
(12190, 'frFR', 'Quoi qu’j’peux faire pour vous ?', 0),
(12191, 'frFR', 'Sifflez la chope, puis lancez-la sur S.T.O.U.T. Je pense qu''il peut encaisser les coups. Je ne l''aurais pas vol... euh... construit s''il n''en était pas capable !', 0),
(12193, 'frFR', 'Quoi de neuf, $gmon mignon:ma mignonne; ? Vous avez quelque chose pour moi ?', 0),
(12194, 'frFR', 'Quoi de neuf, $gmon mignon:ma mignonne; ? Vous avez quelque chose pour moi ?', 0),
(12195, 'frFR', 'Avez-vous apporté les cornes ?', 0),
(12196, 'frFR', 'A-avez-vous ap-ap-apporté ces pièces de golem ?', 0),
(12197, 'frFR', 'Avez-vous ces cellules d''énergie ?', 0),
(12199, 'frFR', 'Dites-moi que ça a marché...', 0),
(12200, 'frFR', 'Heureusement, un endroit tout proche détient un surplus de larmes de dragon d''émeraude. Sinon, j''aurais dû vous envoyer à Féralas.', 0),
(12201, 'frFR', 'Avez-vous récupéré l''uniforme ?', 0),
(12202, 'frFR', 'Avez-vous ces clichés ?', 0),
(12203, 'frFR', 'Qu''avez-vous appris sur Loken ?', 0),
(12204, 'frFR', 'Qu''avez-vous trouvé ?', 0),
(12205, 'frFR', 'Vous êtes $gvenu:venue; me faire perdre mon temps, $Ggarçon:fille;, ou avez-vous accompli ma vendetta contre l''Assaut écarlate ?', 0),
(12206, 'frFR', 'Vous l''avez fait ?$B$BHé, j''ai oublié de vous dire qu''il vaut mieux ne pas se laisser éclabousser par ces saletés ! C''est répugnant, les taches ne partent jamais, sans parler de la galère pour soigner les morceaux de chair qui ont fondu.', 0),
(12207, 'frFR', 'Avez-vous obtenu les échantillons, $N ?', 0),
(12209, 'frFR', 'Je prendrai les armures et les armes que vous pourrez me voler, bleusaille.$B$BMême si elles seront de moins bonne qualité que ce que je peux fabriquer ici, c''est mieux que rien.', 0),
(12211, 'frFR', 'Alors ? Un succès, je suppose ?$B$BNe me dites pas qu''ils ont une sorte de protection contre le fait d''être dévorés par les rats ?!', 0),
(12212, 'frFR', 'Comment se passe la chasse, $r ?', 0),
(12213, 'frFR', 'Avez-vous fait ce que je vous ai demandé, $N ?', 0),
(12214, 'frFR', 'Je suis bien content que vous soyez $gvenu:venue;. J''avais peur de devoir aller là-bas et les rassembler moi-même.', 0),
(12215, 'frFR', 'Quelques worgs de moins qui chassent dans ces forêts, j''espère ?', 0),
(12216, 'frFR', '$gLe puissant:La puissante; $c est de retour !', 0),
(12217, 'frFR', 'Avez-vous accompli votre tâche, $c ?', 0),
(12218, 'frFR', 'Cet essai sera la dernière expérience de la série, $N.', 0),
(12219, 'frFR', 'Avez-vous rassemblé les échantillons, $N ?', 0),
(12220, 'frFR', 'Avez-vous fait ce que je vous ai demandé, $N ?', 0),
(12221, 'frFR', 'Il était temps, bon sang !', 0),
(12222, 'frFR', 'Avez-vous récupéré ces talismans ?', 0),
(12223, 'frFR', 'Avez-vous accompli l''acte ?', 0),
(12226, 'frFR', 'Avez-vous trouvé la noirracine ?', 0),
(12227, 'frFR', 'Vous avez ces graines pour moi, $r ?', 0),
(12229, 'frFR', 'Avez-vous obtenu les échantillons de sang, $N ?', 0),
(12230, 'frFR', 'On pourrait croire qu''ils me laisseraient utiliser les épandeurs de peste... les charger de quelque chose de bien vicieux pour détruire les balistes.$B$BMais non, ils me disent qu''ils ne servent que pour les missions spéciales.$B$BPeu importe !', 0),
(12231, 'frFR', 'Avez-vous déjà parlé aux enfants d''Ursoc, $N ?', 0),
(12232, 'frFR', 'Un jour, je serai chef des nécrogardes !$B$BUn jour...', 0),
(12234, 'frFR', 'Si vous prenez trop de temps, leurs plans quotidiens changeront, et nous devrons peut-être tout recommencer.$B$BNe tardez pas trop !', 0),
(12236, 'frFR', 'Vous êtes de retour. Avez-vous réussi ?', 0),
(12237, 'frFR', 'Vite, $N ! Vous devez sauver les villageois sans défense !', 0),
(12239, 'frFR', '<L''agent vous toise de haut en bas, puis vous fait signe en silence de venir.>$B$BNe grillez pas ma couverture, $c !', 0),
(12240, 'frFR', 'Ma sœur me manque, $N. J''espère qu''elle va bien.', 0),
(12241, 'frFR', 'M''avez-vous apporté les cendres, $N ?', 0),
(12242, 'frFR', 'Avez-vous déjà obtenu les graines de Vordrassil, $N ?', 0),
(12243, 'frFR', 'Ne me dites SURTOUT PAS que leurs voiles étaient protégées contre mon eau brûlante, d''une manière ou d''une autre !$B$BJe détesterais devoir refaire un essai ici.', 0),
(12244, 'frFR', 'Pas de temps pour les bavardages. Ces déchiqueteurs pourraient faire pencher la balance pour l''Alliance !', 0),
(12245, 'frFR', 'C''est simple, en fait. On vous envoie tuer quatre imbéciles incompétents qui risquent de lâcher tous nos secrets d''un moment à l''autre, et vous y allez et vous le faites.$B$B<Le grand exécuteur affiche un sourire impie.>', 0),
(12246, 'frFR', 'Avez-vous obtenu les échantillons de sang, $N ?', 0),
(12247, 'frFR', 'Avez-vous déjà parlé à Orsonn et Kodian ?', 0),
(12248, 'frFR', 'M''avez-vous apporté les cendres, $N ?', 0),
(12249, 'frFR', 'Vous êtes de retour. Avez-vous réussi ?', 0),
(12250, 'frFR', 'Avez-vous les graines, $N ?', 0),
(12252, 'frFR', 'Quelles nouvelles apportez-vous ? Un succès, sans aucun doute ?', 0),
(12253, 'frFR', 'Avez-vous sauvé nos villageois piégés ?', 0),
(12254, 'frFR', 'Vous avez le livre de prières de l''évêque ? Avez-vous trouvé quelque chose d''inhabituel dedans ?', 0),
(12255, 'frFR', 'Avez-vous vaincu le thane ? Nous ne pouvons pas risquer de le laisser au pouvoir.', 0),
(12256, 'frFR', 'Avez-vous récupéré ces talismans ?', 0),
(12257, 'frFR', 'Avez-vous accompli l''acte ?', 0),
(12258, 'frFR', 'Abrégez leurs souffrances, $N.', 0),
(12259, 'frFR', 'Avez-vous vaincu le thane ?', 0),
(12260, 'frFR', 'Ne me dites pas que vous avez cassé le miroir ?!', 0),
(12261, 'frFR', 'Avez-vous placé la protection ?', 0),
(12262, 'frFR', 'Je vois du sang sur vos mains... c''est donc fait ?', 0),
(12263, 'frFR', 'Je suis las de cette pestilence.', 0),
(12264, 'frFR', 'Je ne peux m''empêcher de me demander s''ils sont assez naïfs pour croire que je vais supporter cela ou s''ils sont simplement suicidaires.', 0),
(12265, 'frFR', 'Du pouvoir gaspillé sur les faibles et les inutiles.$B$BMontrez-moi un être digne de la vie et de la magie qu''on lui a offertes, et peut-être pourrons-nous alors parler de gaspillage avant d''éteindre sa présence.$B$BNe vous en faites pas, j''attendrai.', 0),
(12267, 'frFR', 'Vous êtes un outil fort efficace, $c. Votre aide dans cette purge est appréciée.', 0),
(12268, 'frFR', 'Vous avez ces pièces pour moi, $c ?', 0),
(12269, 'frFR', 'Avez-vous récupéré leurs cartes ?', 0),
(12270, 'frFR', 'Vous m''avez rapporté ces déchiqueteurs, $c ?', 0),
(12271, 'frFR', 'Avez-vous pris cette tige à leur tortionnaire ?', 0),
(12272, 'frFR', 'Avez-vous récupéré des échantillons du minerai étrange ?
', 0),
(12273, 'frFR', 'Alors ?!', 0),
(12274, 'frFR', 'Qu''avez-vous appris ? Lui avez-vous seulement déjà parlé ?', 0),
(12277, 'frFR', '<Quarterflash hoche la tête.>$B$BC''était un bon gnome, l''un de nos meilleurs. Slinkin va nous manquer.', 0),
(12278, 'frFR', 'Avez-vous rempli vos formulaires d''adhésion ?', 0),
(12279, 'frFR', 'Si vous ne vous dépêchez pas, ce n''est pas seulement son estomac qui va gronder...', 0),
(12280, 'frFR', 'Vous m''avez rapporté ces pièces ?', 0),
(12281, 'frFR', 'J''ai entendu parler de votre bravoure dans la mine, $N.', 0),
(12282, 'frFR', 'Avez-vous récupéré mon orbe de divination ?', 0),
(12283, 'frFR', 'Il était temps, $N ! Qu''est-ce qui vous a $gretenu:retenue; ?', 0),
(12284, 'frFR', 'C''est du sang de l''Alliance sur votre arme, $r ?', 0),
(12285, 'frFR', 'Dois-je dire à mes forces de commencer à se diriger vers le Marteau d''Agmar ?$B$BOu avez-vous réussi à tuer le grand général ?', 0),
(12288, 'frFR', 'Avez-vous déjà soigné nos blessés, $N ?', 0),
(12289, 'frFR', 'Comment se passe le combat, $N ?', 0),
(12290, 'frFR', 'Avez-vous récupéré la tourbeline ?', 0),
(12291, 'frFR', 'J''ai assez de tourbeline pour fabriquer d''autres élixirs, $N.', 0),
(12292, 'frFR', 'Vous m''apportez cette boîte, $N ?', 0),
(12293, 'frFR', 'Vous nous avez apporté quelque chose ?', 0),
(12298, 'frFR', 'Qu''avez-vous là, $gsoldat:soldate; ?', 0),
(12299, 'frFR', 'Vous en avez fini avec ces crétins de la Horde ?', 0),
(12300, 'frFR', 'Les habitants de Ruissargent... ils ne sont pas ce qu''ils paraissent.', 0),
(12303, 'frFR', 'Quelle part de ce trésor de l''Alliance avez-vous réussi à vous procurer ?', 0),
(12306, 'frFR', 'Vous avez rempli vos formulaires d''adhésion ?', 0),
(12307, 'frFR', 'Oui, $c ?', 0),
(12308, 'frFR', 'Vous êtes $grevenu:revenue;. Je m''inquiétais pour vous, $N.', 0),
(12310, 'frFR', 'C''est fait, %N ?', 0),
(12311, 'frFR', 'Amarion est-il mort ?', 0),
(12312, 'frFR', 'Un tome du Fléau ?', 0),
(12314, 'frFR', 'Avez-vous tué le Capitaine Zorna ?', 0),
(12315, 'frFR', 'Avez-vous éliminé le capitaine ennemi ?', 0),
(12316, 'frFR', 'Qu''avez-vous à signaler ?', 0),
(12317, 'frFR', 'Avez-vous fait comme ordonné ?', 0),
(12319, 'frFR', 'Le nécroseigneur n''est plus ?', 0),
(12320, 'frFR', 'Vous venez du haut commandement, $gmon fils:ma fille; ?', 0),
(12323, 'frFR', 'Avez-vous déjà débusqué les derniers types de la KapitalRisk ?', 0),
(12324, 'frFR', 'Avez-vous déjà débusqué les derniers parasites de la KapitalRisk ?', 0),
(12326, 'frFR', 'Mon nom, c''est Cash. Ambo Cash. Et le plaisir est tout pour vous.', 0),
(12327, 'frFR', 'Oui, $n ?', 0),
(12328, 'frFR', 'Avez-vous obtenu la poussière, $N ?', 0),
(12330, 'frFR', 'Je suis content de vous voir $gentier:entière;.', 0),
(12372, 'frFR', 'Comment se passe le combat ? Les repoussons-nous ?', 0),
(12412, 'frFR', 'Avez-vous accompli votre tâche ? Sinon, que faites-vous ici ?', 0),
(12413, 'frFR', 'Avez-vous déjà accompli votre tâche, $N ?', 0),
(12414, 'frFR', 'Avez-vous tous les mustangs qu''il nous faudra ?', 0),
(12416, 'frFR', 'Je suis content que vous soyez toujours parmi nous, $r.', 0),
(12417, 'frFR', 'J''ai commencé à craindre que le Fléau, dans le sanctuaire, ait eu raison de vous. Heureusement que vous êtes toujours en vie.', 0),
(12418, 'frFR', 'Vous êtes de retour ! Avez-vous fait ce que je vous ai demandé ?', 0),
(12419, 'frFR', 'Bonjour, $r. Je sens la présence de ma broche de rubis. Donnez-la-moi.$B$BQu''est devenue Dahlia ?', 0),
(12420, 'frFR', 'Avez-vous rempli vos formulaires d''adhésion ?', 0),
(12421, 'frFR', 'Vous avez rempli vos formulaires d''adhésion ?', 0),
(12422, 'frFR', 'Vous venez me tuer ?', 0),
(12423, 'frFR', 'Qu''est-ce que vous avez là ?', 0),
(12424, 'frFR', 'Vous avez quelque chose à me montrer ?', 0),
(12427, 'frFR', 'Ce n''est pas fini tant que l''ours ou vous n''avez pas mordu la poussière, $gl''ami:l''amie; !', 0),
(12432, 'frFR', 'Ce bois de l''Alliance a-t-il déjà été brûlé, $c ?', 0),
(12433, 'frFR', 'Vous avez de cet élément 115, $n ?', 0),
(12436, 'frFR', 'Vous avez trouvé cette venaison, $N ?', 0),
(12437, 'frFR', 'Ce navire de bois de la Horde a-t-il déjà été brûlé, $N ?', 0),
(12438, 'frFR', 'Vous venez toucher une prime, $gallié:alliée; ?', 0),
(12441, 'frFR', 'Avez-vous affronté Sangrepatte ?', 0),
(12442, 'frFR', '<Leoric serre les dents.>$B$BCet imbécile prétentieux est-il mort ?', 0),
(12443, 'frFR', 'Vous avez de cet élément 115, $N ?', 0),
(12444, 'frFR', 'Comment se passe la chasse ?', 0),
(12450, 'frFR', 'Vous êtes de retour ! Avez-vous fait ce que je vous ai demandé ?', 0),
(12453, 'frFR', 'Avez-vous fait ce que je vous ai demandé, $N ?', 0),
(12454, 'frFR', 'Plus tôt nous nous serons débarrassés des serres-du-ciel émeraude, plus tôt le Sanctuaire draconique émeraude retrouvera son équilibre naturel.', 0),
(12455, 'frFR', 'Où sont mes munitions, $gmon gars:ma belle; ?', 0),
(12456, 'frFR', 'Avez-vous réussi à régler son compte à Alystros ? N''ayez pas peur de demander l''aide de vos amis.$B$BEn fait, puisque le gardien verdoyant est très puissant, je le recommande !', 0),
(12457, 'frFR', 'Avez-vous sauvé nos soldats blessés ?', 0),
(12458, 'frFR', 'Et justement, combien de graines avez-vous réussi à vous procurer jusqu''ici ?', 0),
(12459, 'frFR', 'Quels sont les résultats ? Sont-ils détruits ?$B$BJ''ai besoin de réponses !', 0),
(12462, 'frFR', 'Vous vous en êtes cassé un morceau ?', 0),
(12464, 'frFR', 'C''est donc fait ?', 0),
(12465, 'frFR', 'Je ne me sens vraiment pas gagnant...', 0),
(12467, 'frFR', 'Avez-vous récupéré le phylactère de Thel''zan ?', 0),
(12469, 'frFR', 'Bonjour !', 0),
(12470, 'frFR', 'Quelles nouvelles apportez-vous ? Que s''est-il passé au Sanctuaire draconique Bronze ?$B$BAvez-vous découvert qui est le chef du Vol draconique infini ?', 0),
(12472, 'frFR', '<Yorik laisse échapper un soupir de soulagement.>$B$BNous pensions que vous ne viendriez peut-être pas, $N.', 0),
(12475, 'frFR', 'Avez-vous récupéré la carte de l''Assaut ?', 0),
(12476, 'frFR', 'Nettoyez le Camp de base de l’Assaut, $N.', 0),
(12477, 'frFR', 'Avez-vous trouvé un exemplaire ?', 0),
(12478, 'frFR', 'Avez-vous fouillé la Caverne de Deuillegivre ?', 0),
(12481, 'frFR', 'Le travail d''assassin n''est pas aussi glamour qu''on le dit.', 0),
(12482, 'frFR', 'Salutations, $N.', 0),
(12483, 'frFR', 'Vous avez les ingrédients pour ce vieux Dasnob, $n ?', 0),
(12484, 'frFR', 'Qu''est-ce que t''as là, $r ?', 0),
(12491, 'frFR', '$n, votre visage est sombre. Apportez-vous de funestes nouvelles ?', 0),
(12492, 'frFR', 'Hé, $N, vous avez le visage tout barbouillé ! Seriez-vous allé$g:e; aux Profondeurs de Rochenoire ?', 0),
(12498, 'frFR', 'Détruisez le Fléau au Repos de Galakrond avant qu''il ne soit trop tard !', 0),
(12501, 'frFR', 'Quelles nouvelles de nos postes, $r ?', 0),
(12503, 'frFR', 'Vous pourriez peut-être en détruire quelques autres ?', 0),
(12504, 'frFR', 'Il m''en faudra plus que ça pour faire un rapport.', 0),
(12505, 'frFR', 'De quoi s''agit-il ?', 0),
(12506, 'frFR', 'Qu''avez-vous vu, $r ?', 0),
(12507, 'frFR', 'Qu''avez-vous là ?', 0),
(12508, 'frFR', 'Et si vous en tuiez encore quelques-uns ?', 0),
(12510, 'frFR', 'Avez-vous les précieux fluides ?', 0),
(12512, 'frFR', 'Avez-vous sauvé nos vétérans, $N ?', 0),
(12513, 'frFR', 'J''étais invincible, à l''époque... fier, et à juste titre. Aucun challenger n''a jamais gagné ce beau chapeau...$B', 0),
(12514, 'frFR', 'Avez-vous tous les champignons ?$B$BOh, et méfiez-vous des basilics qui rôdent par là-bas.', 0),
(12515, 'frFR', 'J''étais invincible, à l''époque... fier, et à juste titre. Aucun challenger n''a jamais gagné ce beau chapeau...', 0),
(12516, 'frFR', 'C''est fini ?$B$BLe mojo modifié a-t-il fonctionné ?$B$BAvez-vous vengé Sseratus en tuant son prophète ?', 0),
(12517, 'frFR', 'Je vois que vous avez réussi à rassembler un jeu de Voleurs ! Je suis impressionné.', 0),
(12518, 'frFR', 'Je vois que vous avez réussi à compléter un jeu de Mages ! Félicitations !', 0),
(12519, 'frFR', 'Vous avez ces médailles pour moi, $r ?', 0),
(12520, 'frFR', 'Avez-vous maîtrisé les rhinocéros, ou jetez-vous l''éponge ?', 0),
(12522, 'frFR', 'Eh bien, avez-vous pu récupérer le moteur ? Je sais pertinemment que l''archimage qui a financé l''expédition commence à s''impatienter.', 0),
(12523, 'frFR', 'Avez-vous ces pièces ?', 0),
(12525, 'frFR', 'Vous êtes-vous $goccupé:occupée; de Ricarnaque et de son garde du corps ?', 0),
(12527, 'frFR', 'Qu''est-ce que tout ça ?$B$BVous n''auriez pas vu, par hasard, mon bon à rien d''apprenti, Potpilon ?$B$BJe l''ai envoyé faire une course il y a un bon moment et il n''est toujours pas revenu !', 0),
(12529, 'frFR', 'Toi encore vivant ! Poings-durs pas encore manger toi ?$B$BPeut-être eux manger toi plus tard.', 0),
(12530, 'frFR', 'Qu''est-ce que tu veux, esclave ?', 0),
(12531, 'frFR', 'Moi pas demander toi, $r. Toi vouloir quoi ?', 0),
(12532, 'frFR', 'Toi attraper poulets ?', 0),
(12533, 'frFR', 'Vous apprendre la chasse ?', 0);
