INSERT INTO `quest_request_items_locale` (`ID`, `Locale`, `CompletionText`, `VerifiedBuild`) VALUES
(13277, 'frFR', 'Du succès contre les géants, $r ?', 0),
(13278, 'frFR', 'Avez-vous pu trouver le zombie, $c ?', 0),
(13279, 'frFR', 'Avez-vous pu neutraliser un lot de peste, $c ?', 0),
(13280, 'frFR', 'Une seconde... vous n''avez pas encore planté notre étendard de bataille !$B$BQu''est-ce qui vous retient ?', 0),
(13281, 'frFR', 'Salutations, $c.$B$BPuis-je annoncer que nous avons encore rendu un chaudron de peste inutilisable ?', 0),
(13284, 'frFR', 'Avez-vous fait monter certains de mes hommes en sécurité ?', 0),
(13287, 'frFR', 'Vous êtes de retour, $c...$B$BQuelque chose à signaler ?', 0),
(13288, 'frFR', 'Eh bien, $r ?$B$BVos amies les abominations se sont-elles montrées efficaces ?', 0),
(13289, 'frFR', 'Oui, $c ?', 0),
(13291, 'frFR', 'Eh bien, comment ça s''est passé, $r ?', 0),
(13292, 'frFR', 'Que puis-je faire pour coupain de moi ?', 0),
(13294, 'frFR', 'Du succès contre les géants, $r ?', 0),
(13295, 'frFR', 'Avez-vous pu neutraliser un lot de peste, $c ?', 0),
(13297, 'frFR', 'Salutations, $c.$B$BPuis-je annoncer que nous avons encore rendu un chaudron de peste inutilisable ?', 0),
(13298, 'frFR', 'Avez-vous pu trouver le zombie, $c ?', 0),
(13300, 'frFR', 'Je n''ai pas reçu beaucoup de rapports de nos hommes revenus à l''avant-garde d’Argent.$B$BÊtes-vous certain$g:e; d''être allé$g:e; à Ymirheim pour les libérer ?', 0),
(13301, 'frFR', 'Avez-vous fait monter certains de mes hommes en sécurité ?', 0),
(13302, 'frFR', 'Je n''ai pas reçu beaucoup de rapports de nos hommes revenus à l''avant-garde d’Argent.$B$BÊtes-vous certain$g:e; d''être allé$g:e; à Ymirheim pour les libérer ?', 0),
(13304, 'frFR', 'Le démolisseur a subi de gros dégâts.', 0),
(13305, 'frFR', 'Avez-vous fini de jouer avec vos machines de guerre ?', 0),
(13306, 'frFR', 'Avez-vous construit ces barricades ?', 0),
(13307, 'frFR', 'Avez-vous tué les porte-bannière et mis fin à leur tentative de retourner les morts contre nous ?', 0),
(13308, 'frFR', 'Vous serez richement $grécompensé:récompensée; pour le service que vous me rendez.$B$B<Le sombre orateur projette des sensations apaisantes dans votre esprit.>$B$BVous ne regretterez pas de m''avoir libéré.', 0),
(13309, 'frFR', 'Avez-vous fait entrer mes gars ?', 0),
(13310, 'frFR', 'Le travail est fait ?', 0),
(13311, 'frFR', 'Je vois que vous avez réussi à compléter un jeu de Démons ! Félicitations !', 0),
(13312, 'frFR', 'Avez-vous accompli votre mission ?', 0),
(13314, 'frFR', 'Avez-vous intercepté ces dépêches ?', 0),
(13315, 'frFR', 'Avez-vous exploré la porte de la désolation, $c ?', 0),
(13316, 'frFR', 'Avez-vous mis hors d''état de nuire les défenseurs de Corp''rethar ?', 0),
(13318, 'frFR', 'Oui, $r ?', 0),
(13319, 'frFR', 'Oui, $c ?', 0),
(13321, 'frFR', 'Eh bien, $c ?$B$BNous avons quelques cultistes de moins à craindre ?', 0),
(13322, 'frFR', 'Eh bien, $c ?$B$BNous avons quelques cultistes de moins à craindre ?', 0),
(13323, 'frFR', 'Oui, $r ?', 0),
(13324, 'frFR', 'Je vois que vous avez réussi à compléter un jeu de Prismes ! Félicitations !', 0),
(13325, 'frFR', 'Je vois que vous avez réussi à compléter un jeu du Chaos ! Félicitations !', 0),
(13326, 'frFR', 'Je vois que vous avez réussi à compléter un jeu de Nobles ! Félicitations !', 0),
(13327, 'frFR', 'Je vois que vous avez réussi à compléter un jeu de la Non-vie ! Félicitations !', 0),
(13328, 'frFR', 'Avez-vous brisé les nouvelles armes du roi-liche ?', 0),
(13330, 'frFR', 'Avez-vous fait ce que je vous ai demandé ?', 0),
(13332, 'frFR', 'Avez-vous construit ces barricades ?', 0),
(13333, 'frFR', 'Avez-vous intercepté ces dépêches ?', 0),
(13334, 'frFR', 'Vous avez éliminé les porte-étendards du Fléau et leurs sbires ? Bien. Nos préparatifs doivent continuer.', 0),
(13335, 'frFR', 'Avez-vous testé la solution sur les saccageurs ?', 0),
(13337, 'frFR', 'Avez-vous accompli votre mission ?', 0),
(13339, 'frFR', 'Avez-vous brisé les nouvelles armes du roi-liche ?', 0),
(13342, 'frFR', 'Oui, $c ?', 0),
(13343, 'frFR', '<Chromie vous regarde d''un drôle d''air.>$B$BEst-ce que je vous connais ? Je sens autour de vous une aura comme si votre existence même était en train de changer. Ou alors vous êtes $gcoincé:coincée; dans une boucle temporelle.$B$BQuelle qu''en soit la raison, vous feriez mieux de régler ça vite, sinon vous n''existerez plus très longtemps !', 0),
(13344, 'frFR', 'Oui, $c ?', 0),
(13345, 'frFR', 'Avez-vous découvert ce que leurs chercheurs manigancent, $r ?', 0),
(13346, 'frFR', 'Eh bien, $gmon ami:mon amie; ? Avez-vous triomphé d''Alumeth ?', 0),
(13347, 'frFR', '<Le roi Wrynn essuie une larme.>$b$b<Le roi Wrynn acquiesce.>$b$bC''est ma faute.', 0),
(13349, 'frFR', 'Salutations, $N.', 0),
(13350, 'frFR', 'Eh bien, $gmon ami:mon amie; ? Avez-vous triomphé d''Alumeth ?', 0),
(13351, 'frFR', 'Avez-vous exploré la porte de la désolation, $c ?', 0),
(13352, 'frFR', 'Oui, $r ?', 0),
(13353, 'frFR', 'Oui, $r ?', 0),
(13354, 'frFR', 'Oui, $r ?', 0),
(13357, 'frFR', 'Alors ? Comment ça s''est passé ?', 0),
(13358, 'frFR', 'Oui, $c ?', 0),
(13359, 'frFR', 'Avez-vous récupéré la poussière, $n ?', 0),
(13361, 'frFR', 'Vous avez vu, $N ? Vous avez vu ?', 0),
(13364, 'frFR', 'Que la Lumière soit avec vous, $N.', 0),
(13365, 'frFR', 'Oui, $c ?', 0),
(13366, 'frFR', 'Avez-vous découvert ce que leurs chercheurs manigancent, $c ?', 0),
(13367, 'frFR', 'Eh bien, $r ? Avez-vous pu arrêter Alumeth ?', 0),
(13368, 'frFR', 'Eh bien, $gmon ami:mon amie; ? Avez-vous triomphé d''Alumeth ?', 0),
(13372, 'frFR', '$N, vous êtes $gentré:entrée; en contact avec une clé de l''iris de focalisation ! L''avez-vous sur vous ?$B$B<La reine jette un regard plein d''inquiétude à son consort, Krasus.>$B$BComment en êtes-vous $gvenu:venue; à la posséder ? Oh, Saphiron avait toujours la sienne ?', 0),
(13373, 'frFR', 'Vous n''avez pas atteint votre quota, $N. Les bombardiers sont-ils trop difficiles à gérer ?', 0),
(13375, 'frFR', '$N, vous êtes $gentré:entrée; en contact avec une clé de l''iris ! L''avez-vous sur vous ?$B$B<La reine jette un regard plein d''inquiétude à son consort, Krasus.>$B$BComment en êtes-vous $gvenu:venue; à la posséder ? Oh, Saphiron avait toujours la sienne ?', 0),
(13376, 'frFR', 'Qu''est-ce que vous attendez ? Nous avons le matériel et les munitions… il ne nous manque que de courageux artilleurs comme vous pour s''en servir.', 0),
(13380, 'frFR', '$N, les bombardiers sont difficiles à utiliser, mais vous devez les maîtriser si nous voulons remporter nos combats contre le Fléau.', 0),
(13382, 'frFR', 'Continuez, $N. La bataille aérienne ne va pas se gagner toute seule !', 0),
(13384, 'frFR', 'Seul Malygos porte le Cœur de la magie. C''est son bien le plus précieux.', 0),
(13385, 'frFR', 'Seul Malygos porte le Cœur de la magie. C''est son bien le plus précieux.', 0),
(13387, 'frFR', 'Pour l’Alliance !', 0),
(13391, 'frFR', 'Avez-vous obtenu le sang ?', 0),
(13393, 'frFR', 'Le démolisseur a subi de gros dégâts.', 0),
(13394, 'frFR', 'Avez-vous fini de jouer avec vos machines de guerre ?', 0),
(13395, 'frFR', 'Vous avez vu, $N ?', 0),
(13397, 'frFR', '$N, vous êtes de retour !', 0),
(13398, 'frFR', 'Avez-vous récupéré la poussière, $n ?', 0),
(13400, 'frFR', 'Vous avez vu, $N ? Vous avez vu ?', 0),
(13403, 'frFR', 'Que la Lumière soit avec vous, $N.', 0),
(13404, 'frFR', 'Continuez, $N. La bataille aérienne ne va pas se gagner toute seule !', 0),
(13405, 'frFR', 'Quelles nouvelles du front, $N ?', 0),
(13406, 'frFR', 'Vous n''avez pas atteint votre quota, $N. Allez donc faire tout sauter !', 0),
(13407, 'frFR', 'Vous voilà de retour ! Avez-vous été $gvictorieux:victorieuse;, $n ?', 0),
(13408, 'frFR', '$N, revenez me voir quand vous aurez aidé à la capture de chacun des forts !', 0),
(13409, 'frFR', 'Revenez me voir après avoir aidé à prendre chaque fort !', 0),
(13410, 'frFR', '$N, revenez me voir quand vous aurez aidé à la capture de chacun des forts !', 0),
(13413, 'frFR', 'Eh bien, $gmortel:mortelle;, que pensez-vous de mes animaux de compagnie ?', 0),
(13414, 'frFR', 'Oui, $r ?', 0),
(13415, 'frFR', 'La console semble avoir une ouverture pour le disque de l''inventeur.', 0),
(13416, 'frFR', 'La console semble avoir une ouverture pour le disque de l''inventeur.', 0),
(13417, 'frFR', 'Le roi Cœur-de-tempête vous adresse ses plus sincères remerciements pour l''avoir réuni avec ses frères. On dirait qu''il est parti régler un compte maintenant - peut-être le retrouverez-vous aux portes d''Arthas.', 0),
(13421, 'frFR', 'Avez-vous découvert d''autre permagivre, petit $r ?', 0),
(13422, 'frFR', 'Salut, $gfrère:sœur;.', 0),
(13425, 'frFR', 'Avez-vous détruit les œufs flétris ?', 0),
(13427, 'frFR', 'Dites-moi, $N. Quelles nouvelles apportez-vous du front ?', 0),
(13428, 'frFR', 'Vous voilà de retour ! Apportez-vous des nouvelles de la victoire ?', 0),
(13431, 'frFR', 'Maintenant que le gourdin est reforgé, je vais me libérer de mes chaînes et retourner au sanctuaire du Serpent pour me venger de Vashj et de ses sbires !', 0),
(13432, 'frFR', 'Je vous ai demandé l''impossible, et pourtant j''attends de vous que vous réussissiez. Beaucoup en dépend.', 0),
(13476, 'frFR', 'Arathi est encore humide du sang de grands guerriers et le fracas de l''acier résonne toujours dans tout Alterac. Ne me faites pas perdre mon temps, sauf si vous apportez des nouvelles du front !', 0),
(13478, 'frFR', 'Comment se passent vos voyages, $gmon gars:ma belle; ?', 0),
(13479, 'frFR', 'Avez-vous les fragments ?', 0),
(13480, 'frFR', 'Avez-vous les fragments ?', 0),
(13502, 'frFR', 'Avez-vous les dix chocolats du Jardin des nobles ?', 0),
(13503, 'frFR', 'Avez-vous les dix chocolats du Jardin des nobles ?', 0),
(13505, 'frFR', 'Avez-vous pu récupérer des artefacts ?', 0),
(13506, 'frFR', 'Oui, $c ?', 0),
(13513, 'frFR', 'Avez-vous retrouvé les amulettes ?', 0),
(13518, 'frFR', 'Leur fierté les a retenus à Auberdine jusqu''à présent, mais personne ne mérite un sort aussi cruel.', 0),
(13520, 'frFR', 'Avez-vous apporté les muscles des palourdes ? Je crains que le temps ne nous soit bientôt compté.', 0),
(13521, 'frFR', '<La Bigobox 413 bourdonne dans votre direction d''un air expectatif.>', 0),
(13526, 'frFR', 'Avez-vous rassemblé la patte d''ours ?', 0),
(13527, 'frFR', 'Content de vous revoir ! Avez-vous trouvé cet échantillon d''ours que je cherchais ?', 0),
(13528, 'frFR', '<La Bigobox 723 bourdonne dans votre direction d''un air expectatif.>', 0),
(13537, 'frFR', '<Le ventre de Johnathan gargouille lorsque vous approchez.>$B$BJe n''aurais pas pu mieux le dire avec des mots.', 0),
(13538, 'frFR', 'Apportez-vous un message du sud ?', 0),
(13539, 'frFR', 'Mon dégoût pour les démonistes n''est surpassé que par ma haine des morts-vivants. Cependant, ils peuvent tous deux se révéler utiles à l''occasion.', 0),
(13544, 'frFR', 'Avez-vous visité la vieille statue d''ours ?', 0),
(13549, 'frFR', 'Non, cela ne convient pas du tout. Revenez quand vous aurez les léopards et les ours femelles dont j''aurai besoin pour le pénible voyage de retour.', 0),
(13554, 'frFR', 'Avez-vous mis la main sur la substance ? Plus tôt je me mettrai à travailler sur un remède, plus nous pourrons sauver d''animaux !', 0),
(13556, 'frFR', 'Qui aurait cru que le grand Dubra''Jin voudrait autant d''œufs ? Qu''est-ce qu''il va en faire, d''abord ?', 0),
(13558, 'frFR', 'Vous êtes de retour. Quelles nouvelles apportez-vous ?', 0),
(13559, 'frFR', 'Aucun tribut ordinaire n''était assez bon pour le grand Hodir lorsqu''il marchait parmi les géants du givre.$B$BIl n''est peut-être plus avec nous, mais nous avons gardé la tradition de rendre hommage à sa force et à sa sagesse. Participer à cette tradition ferait beaucoup pour votre renommée, $gpetit:petite; $c.', 0),
(13563, 'frFR', 'Je ne sais comment, j''ai échappé à la toxine qui afflige à présent les autres survivants. Je ne peux m''empêcher de les envier un peu, pourtant... vivre une éternité seul ne vaut pas la peine d''être vécu.$B$BTu me manques tant, Anaya.', 0),
(13566, 'frFR', 'Avez-vous récupéré les matériaux que j''ai demandés ? Et dites-moi, je vous en prie, que vous n''avez fait de mal à aucun animal en chemin...', 0),
(13578, 'frFR', 'Vous apporter plumes des autres ?', 0),
(13582, 'frFR', 'Vous avoir torche ?', 0),
(13587, 'frFR', 'Vous l''avez trouvé, $N ?', 0),
(13590, 'frFR', 'Salutations, $c. Avez-vous apporté la flèche ?', 0),
(13591, 'frFR', 'Vous voilà de retour ! Il paraît que la bataille s''est bien passée.', 0),
(13592, 'frFR', 'Vous êtes-vous $gmesuré:mesurée; au Fléau au combat ?', 0),
(13596, 'frFR', 'Avez-vous déjà obtenu les plans, $n ?', 0),
(13598, 'frFR', 'Griffe-sinistre est un combattant redoutable. Je plains un peu ces braconniers, malgré leurs intentions.', 0),
(13600, 'frFR', 'Les récits du barde itinérant étaient-ils vrais ? Avez-vous apporté une lame ?', 0),
(13603, 'frFR', 'Avez-vous pu récupérer la lame ?', 0),
(13604, 'frFR', 'La console ronronne d''énergie tandis que le réceptacle rond s''ouvre.', 0),
(13606, 'frFR', 'Le sceau de Freya, $N ? Vous l''avez ?', 0),
(13609, 'frFR', 'Vous avez obtenu le sceau, $N ?', 0),
(13610, 'frFR', 'Eh ben, $N ? Vous l''avez ?', 0),
(13611, 'frFR', 'Avez-vous pu obtenir le sceau, $N ?', 0),
(13614, 'frFR', 'Les lumières vives de la console balaient la surface de verre à répétition, comme si elles attendaient une commande.', 0),
(13615, 'frFR', 'Avez-vous récupéré les flèches dont nous avons besoin, $c ?', 0),
(13616, 'frFR', 'Avez-vous remporté la lame que je cherche ?', 0),
(13619, 'frFR', 'Avez-vous trouvé Gorat, $c ?!', 0),
(13620, 'frFR', 'Qu''avez-vous là, $r ?', 0),
(13622, 'frFR', 'En attente d''instructions.', 0),
(13623, 'frFR', 'Il faut du courage pour venir ici dans ces circonstances.$B$BQuelle affaire vous amène, $gétranger:étrangère; ?', 0),
(13625, 'frFR', 'Comment se passe l''entraînement au combat monté ?', 0),
(13626, 'frFR', 'Nos pertes ici ont été stupéfiantes.', 0),
(13627, 'frFR', 'Avez-vous mis la main sur la « marchandise » dont nous avons parlé ?', 0),
(13629, 'frFR', 'En attente d''instructions.', 0),
(13631, 'frFR', 'Vous êtes $gprêt:prête;, $N ?', 0),
(13633, 'frFR', 'Avez-vous trouvé quelque chose en rapport avec l''histoire du Chevalier noir ?', 0),
(13634, 'frFR', 'Avez-vous trouvé quelque chose en rapport avec l''histoire du Chevalier noir ?', 0),
(13635, 'frFR', 'Qu''est-ce qui vous amène jusqu''ici ?', 0),
(13640, 'frFR', 'Avez-vous obtenu le bois qu''il vous faut ?', 0),
(13641, 'frFR', 'Avez-vous localisé un cristal de voyant ?', 0),
(13642, 'frFR', 'Avez-vous eu des difficultés à atteindre la Lumière d’Élune au lac Falathim ?', 0),
(13643, 'frFR', 'Avez-vous visité les tombes des combattants tués ?', 0),
(13645, 'frFR', 'Je suis Raene Mèneloup. Et vous, qui êtes-vous ?', 0),
(13651, 'frFR', 'Avez-vous pu récupérer l''huile dont nous avons besoin, $C ?', 0),
(13654, 'frFR', 'Le comportement de l''écuyer nous a-t-il livré des indices ?', 0),
(13662, 'frFR', 'Vous avez gravi les échelons de la hiérarchie d''entreprise de la Confrérie, $r. Nous commençons à vous regarder d''un bon œil. Quel exploit !$B$BSi vous voulez plus de travail et gagner plus de respect parmi nous, écoutez bien.$B$BNous pouvons affiner notre flux ardent en ajoutant un simple résidu de Sombrefer au mélange. Ce résidu de Sombrefer se trouve dans les Profondeurs de Rochenoire.$B$BApportez-moi tout le résidu de Sombrefer que vous trouverez !', 0),
(13663, 'frFR', 'Qu''avez-vous découvert ?', 0),
(13665, 'frFR', 'Avez-vous terminé votre entraînement pour la grande mêlée ?', 0),
(13666, 'frFR', 'Avez-vous pu récupérer la lame ?', 0),
(13669, 'frFR', 'Les récits du barde itinérant étaient-ils vrais ? Avez-vous apporté une lame ?', 0),
(13670, 'frFR', 'Avez-vous remporté la lame ?', 0),
(13671, 'frFR', 'Vous êtes-vous $gmesuré:mesurée; au Fléau au combat ?', 0),
(13672, 'frFR', 'Souhaitez-vous relever le défi de l''aspirant ?', 0),
