INSERT INTO `quest_request_items_locale` (`ID`, `Locale`, `CompletionText`, `VerifiedBuild`) VALUES
(27305, 'frFR', 'Le tableau, $N. Avez-vous le tableau ?', 0),
(27316, 'frFR', 'C''est le légendaire hochet en os, $n !', 0),
(27317, 'frFR', 'Le légendaire hochet en os, $n !', 0),
(27320, 'frFR', 'Il nous faudra le véritable édit, et pas n''importe quel parchemin tauren accroché au mur.', 0),
(27321, 'frFR', 'Il nous faudra le véritable édit, et pas n''importe quel parchemin accroché au mur.', 0),
(27322, 'frFR', 'Korok est mort ?', 0),
(27325, 'frFR', 'Les taurens adorent leurs tambours. J''imagine que les Tambours de guerre seront d''une certaine manière différents des autres.', 0),
(27326, 'frFR', 'La guerre n''est pas une activité pour ceux qui sont fidèles aux enseignements de la Terre-Mère.', 0),
(27336, 'frFR', 'Avez-vous eu de la chance en testant le totem ?', 0),
(27337, 'frFR', 'Avez-vous apporté les matériaux dont j''aurai besoin pour votre arme ?', 0),
(27339, 'frFR', 'Avez-vous récupéré ce venin ? Morlann va s''apercevoir qu''il a disparu d''un instant à l''autre...', 0),
(27342, 'frFR', 'Avez-vous cueilli l''aconit ?', 0),
(27343, 'frFR', 'Avez-vous les matériaux pour votre arme ?', 0),
(27344, 'frFR', 'Avez-vous apporté les matériaux dont j''aurai besoin pour votre arme ?', 0),
(27345, 'frFR', 'Récupérez le F.C.D.', 0),
(27347, 'frFR', 'Avez-vous progressé contre ces vases ?', 0),
(27348, 'frFR', '<Moxie semble folle d''inquiétude.>$B$BLa cargaison a-t-elle survécu ? En avez-vous retrouvé quelque chose ?', 0),
(27351, 'frFR', 'Avez-vous apporté les matériaux dont j''aurai besoin pour votre arme ?', 0),
(27352, 'frFR', 'C''est la fiole d''eau bénite de Stratholme ?$B$BAttendez, c''est de l''eau ordinaire ? Ne jouez pas avec le vieux Navrepierre !', 0),
(27353, 'frFR', 'Avez-vous apporté les matériaux dont j''aurai besoin pour votre arme ?', 0),
(27354, 'frFR', 'Avez-vous apporté les matériaux dont j''aurai besoin pour votre arme ?', 0),
(27355, 'frFR', 'Avez-vous apporté les matériaux dont j''aurai besoin pour votre arme ?', 0),
(27356, 'frFR', 'Avez-vous apporté les matériaux dont j''aurai besoin pour votre bâton ?', 0),
(27359, 'frFR', 'Avez-vous pu obtenir les essences ? Soyez prudent, ce sont de redoutables lanceurs de sorts.', 0),
(27361, 'frFR', 'Avez-vous apporté les matériaux dont j''aurai besoin pour votre arme ?', 0),
(27362, 'frFR', 'Avez-vous apporté les matériaux dont j''aurai besoin pour votre arme ?', 0),
(27363, 'frFR', 'Avez-vous apporté les matériaux dont j''aurai besoin pour votre arme ?', 0),
(27364, 'frFR', 'Rapport ?', 0),
(27365, 'frFR', 'Avez-vous apporté les matériaux dont j''aurai besoin pour votre arme ?', 0),
(27368, 'frFR', 'Oh là là… Fiona va être plus furieuse qu''une harpie mouillée. Vous feriez mieux de vous dépêcher.', 0),
(27369, 'frFR', 'Giddy vous a $gmêlé:mêlée; à tout ça maintenant ?', 0),
(27372, 'frFR', 'J''aurais dû m''en douter.  Tarenar vous a fait m''apporter un cadeau ? Ce crétin sans cervelle !$b$bEuh... c''était quoi, comme cadeau, au fait ?', 0),
(27384, 'frFR', 'Avez-vous retrouvé ma poupée ?', 0),
(27385, 'frFR', 'Des nouvelles de ma Pammy ?', 0),
(27386, 'frFR', 'Votre visite tombe à point nommé. Vous ne venez pas du futur, n''est-ce pas ?', 0),
(27387, 'frFR', 'Avez-vous trouvé le crâne et l''épée, $N ?', 0),
(27388, 'frFR', 'Avez-vous les reliques, $N ?', 0),
(27389, 'frFR', 'Avez-vous les crânes ? Ils sont essentiels à mon sort, qui nous donnera une chance de sauver Comté-de-Darrow. Peut-être.', 0),
(27391, 'frFR', 'Ce coffre est vieux et couvert de crasse.', 0),
(27392, 'frFR', 'Papa adorait son épée en forme d''animal. Il avait l''air triste quand il ne l''a plus eue.', 0),
