INSERT INTO `quest_request_items_locale` (`ID`, `Locale`, `CompletionText`, `VerifiedBuild`) VALUES
(32163, 'frFR', 'Ça a l''air d''être un bon endroit pour attraper un crabe.', 0),
(32164, 'frFR', 'C''est ici, près du temple de la Grue.', 0),
(32165, 'frFR', 'Ça a l''air d''être un endroit idéal pour un piège à tigre.', 0),
(32166, 'frFR', 'Ça a l''air d''être un bon endroit pour attraper un crabe.', 0),
(32181, 'frFR', 'Content de vous revoir, $n.', 0),
(32182, 'frFR', 'Content de vous revoir, $n.', 0),
(32183, 'frFR', 'Content de vous revoir, $n.', 0),
(32184, 'frFR', 'Content de vous revoir, $n.', 0),
(32185, 'frFR', 'Content de vous revoir, $n.', 0),
(32186, 'frFR', 'Content de vous revoir, $n.', 0),
(32194, 'frFR', 'Que cherchent ces elfes de sang ?', 0),
(32197, 'frFR', 'Qu''est-ce que vous m''apportez cette fois ?', 0),
(32199, 'frFR', 'La patronne veut une marmite à vapeur, c''est ça ? Eh bien, elle ferait mieux de descendre la fabriquer elle-même !', 0),
(32233, 'frFR', 'Alors ? Qu''avez-vous trouvé ?', 0),
(32234, 'frFR', 'Avez-vous trouvé les artefacts ?', 0),
(32243, 'frFR', 'Vous avez trouvé quelque chose là-haut ?', 0),
(32244, 'frFR', 'Qu''avez-vous découvert ?', 0),
(32257, 'frFR', 'Nous sommes tout à fait capables de mener cette fouille. Je comprends que le chef de guerre vous ait envoyé$g:e;, mais il obtiendra des résultats plus rapides s''il nous laisse travailler.', 0),
(32264, 'frFR', 'Vous l''avez ? Vous avez le livre ?!', 0),
(32292, 'frFR', 'Alors ?', 0),
(32318, 'frFR', 'Mes herbes sont tout ce qui empêche Vol''jin de mourir. Je n''ose pas le quitter.', 0),
(32319, 'frFR', 'Vous avez fait un long chemin pour me voir, $R. Parlez.', 0),
(32332, 'frFR', 'Ah, le semi-sage revient. Avez-vous mon ambre ?', 0),
(32333, 'frFR', 'Vous avez la bière métallique ?', 0),
(32336, 'frFR', 'Ingoo était un grand hozen. Bon chef, belles fêtes et bon alcool.', 0),
(32337, 'frFR', 'Toi avoir tête ?', 0),
(32338, 'frFR', 'Comment les mogus ont trouvé l''onguent est un mystère.$B$BMais bien des choses se sont passées depuis que le monde s''est déchiré.', 0),
(32342, 'frFR', 'Avez-vous apporté les pièges ?', 0),
(32343, 'frFR', 'L''essence ne va pas se fabriquer toute seule, $R.', 0),
(32377, 'frFR', 'Alors que vous regardez le déguisement de Kor''kron assemblé, l''oreillette de votre radio grésille.', 0),
(32379, 'frFR', 'Avez-vous trouvé quelque chose sur les mogus ?', 0),
(32397, 'frFR', 'Qu''avez-vous trouvé ?', 0),
(32446, 'frFR', 'Alors, à quoi servait cette télécommande ?', 0),
(32448, 'frFR', 'On ne sait jamais ce qu''on va trouver dans un livre. Surtout un ancien livre pandaren.$B$BJ''ai hâte de voir comment fonctionne ce vin de souvenance.', 0),
(32468, 'frFR', 'Cette matriarche aux épines de cristal a les gemmes qu''il nous faut pour améliorer votre lentille. Avez-vous eu de la chance de ce côté-là ?', 0),
(32469, 'frFR', 'Hé, sortez de mon champ de tir ! Oh, c''est vous ! Avez-vous déjà abattu ce basilic ?', 0),
(32470, 'frFR', 'Regardez ce tir ! Je pourrais tirer ici toute la journée ! Avez-vous déjà ces pièces ?', 0),
(32471, 'frFR', 'Vous avez ces pièces pour moi, oui ou non ? Je suis occupé, là !', 0),
(32494, 'frFR', 'Avez-vous les masques ?', 0),
(32505, 'frFR', 'J''exige TOUTES mes pièces. S''il en manque ne serait-ce qu''un caillou, j''envisagerai de rompre notre accord.', 0),
(32506, 'frFR', 'Une grande tristesse plane sur cette île...', 0),
(32556, 'frFR', 'Que m''avez-vous apporté, $C ?', 0),
(32557, 'frFR', 'Qu''avez-vous trouvé là-bas ? Quelque chose qui puisse servir ?', 0),
(32558, 'frFR', 'Où sont les masques ?', 0),
(32571, 'frFR', 'Une grande tristesse plane sur cette île...', 0),
(32587, 'frFR', 'Alors ?', 0),
(32589, 'frFR', 'Avez-vous réussi dans notre entreprise ?', 0),
(32591, 'frFR', 'Qu''avez-vous découvert dans le Trône du tonnerre ? La réputation de férocité du roi-tonnerre est-elle justifiée ?', 0),
(32594, 'frFR', 'Et le seigneur des tempêtes Nalak ? Et la lance ? Des détails !', 0),
(32596, 'frFR', 'Qu''avez-vous découvert jusqu''ici ?$B$BNous devons rassembler toutes les informations possibles !', 0),
(32597, 'frFR', 'Le roi-tonnerre ! Qu''est-il devenu ?', 0),
(32599, 'frFR', 'Nous serons inarrêtables une fois que le pouvoir de Lei Shen aura fusionné avec mon bâton.', 0),
(32607, 'frFR', 'Chaque heure qui passe nous rapproche de la défaite du roi-tonnerre.', 0),
(32608, 'frFR', 'La force du roi-tonnerre est légendaire. Il nous faut le moindre avantage si nous voulons le vaincre.', 0),
(32613, 'frFR', '<Ku''ma hausse les épaules.>', 0),
(32617, 'frFR', '<Ku''ma ouvre la bouche de surprise à la vue de tant d''ossements.>', 0),
(32633, 'frFR', 'Avez-vous trouvé le grimoire ?', 0),
(32643, 'frFR', 'La caisse reste vide, dans l''attente de vos récoltes.', 0),
(32646, 'frFR', 'La caisse reste vide, dans l''attente de vos récoltes.', 0),
(32648, 'frFR', 'La caisse reste vide, dans l''attente de vos récoltes.', 0),
(32650, 'frFR', 'La caisse reste vide, dans l''attente de vos récoltes.', 0),
(32657, 'frFR', 'La caisse reste vide, dans l''attente de vos récoltes.', 0),
(32659, 'frFR', 'La caisse reste vide, dans l''attente de vos récoltes.', 0),
(32676, 'frFR', 'Lei Shen tombera sous notre assaut, et mon peuple trouvera la gloire dans sa ruine.', 0),
(32677, 'frFR', 'J''espère que vous avez de bonnes nouvelles.', 0),
(32683, 'frFR', 'Comment avancent vos études ?', 0),
(32685, 'frFR', 'Attrapez 5 carpes dorées. Essayez sans canne à pêche !', 0),
(32686, 'frFR', 'Débarrassez le fouillis et exposez l''artefact.', 0),
(32687, 'frFR', 'Débarrassez le fouillis et exposez l''artefact.', 0),
(32688, 'frFR', 'Débarrassez le fouillis et exposez l''artefact.', 0),
(32689, 'frFR', 'Débarrassez le fouillis et exposez l''artefact.', 0),
(32690, 'frFR', 'Débarrassez le fouillis et exposez l''artefact.', 0),
(32691, 'frFR', 'Débarrassez le fouillis et exposez l''artefact.', 0),
(32692, 'frFR', 'Débarrassez le fouillis et exposez l''artefact.', 0),
(32693, 'frFR', 'Débarrassez le fouillis et exposez l''artefact.', 0),
(32707, 'frFR', 'Avez-vous trouvé les pierres dont j''ai parlé ?', 0),
(32718, 'frFR', 'Que ces breloques vous portent chance, $n.', 0),
(32719, 'frFR', 'Que ces breloques vous portent chance, $n.', 0),
(32722, 'frFR', 'Alors ?', 0),
(32724, 'frFR', 'Alors ?', 0),
(32726, 'frFR', 'Comment avancent vos études ?', 0),
(32804, 'frFR', 'Avez-vous trouvé exactement ce qu''il faut ?', 0),
(32809, 'frFR', 'Avez-vous trouvé quelque chose d''utile pour nous ?', 0),
(32811, 'frFR', 'Il me faut ces provisions des Kor''kron pour alimenter la rébellion Sombrelance.', 0),
(32819, 'frFR', 'La Horde se disloque sous la direction de Hurlenfer.', 0),
(32836, 'frFR', 'Qu''avez-vous là, $C ?', 0),
(32838, 'frFR', 'Tiens, tiens. Qu''est-ce que vous m''apportez là ?', 0),
(32840, 'frFR', 'Quel est ce parfum que je sens ?', 0),
(32842, 'frFR', 'Vous avez quelque chose pour moi, je le vois dans vos yeux. De quoi s''agit-il, $C ?', 0),
(32844, 'frFR', 'Salutations, $c.', 0),
(32846, 'frFR', 'En quoi puis-je vous aider ?', 0),
(32848, 'frFR', 'Vous avez l''air d''un messager. Qu''avez-vous pour moi, $R ?', 0),
(32850, 'frFR', 'Qu''avez-vous là, $C ?', 0),
(32852, 'frFR', 'Que transportez-vous, $C ? Quelque chose qui m''appartient ?', 0),
(32854, 'frFR', 'Vous portez quelque chose qui m''appartient, je crois.', 0),
(32856, 'frFR', 'Bonjour, $R. M''avez-vous apporté quelque chose ?', 0),
(32858, 'frFR', 'Qu''avez-vous là, $C ?', 0),
(32862, 'frFR', 'Comment vont les Tarides, $C ?', 0),
(32872, 'frFR', 'Comment vont les Tarides, $R ?', 0),
(32943, 'frFR', 'La caisse reste vide, dans l''attente de vos récoltes.', 0),
(32945, 'frFR', 'La caisse reste vide, dans l''attente de vos récoltes.', 0),
(32981, 'frFR', 'Strag a toujours été une lâche. Elle se cachait derrière sa magie et sa position de porte-parole des morts.', 0),
(33024, 'frFR', 'Je suis content que ce soit vous et pas moi. Je ne suis pas très buveur.', 0),
(33026, 'frFR', 'J''en ai déjà le goût de la soupe en bouche !', 0),
(33066, 'frFR', 'Avez-vous les éclats, $n ?', 0),
(33077, 'frFR', 'Maintenant, tout est en descente, $gmon petit:ma petite;.', 0),
(33084, 'frFR', 'Vous avez vu la taille de ces bêtes ?', 0),
(33098, 'frFR', '<Irion joint le bout de ses doigts en forme de tente.>$B$BMes pièces... ?', 0),
(33111, 'frFR', 'Avez-vous lu la prime que j''ai affichée concernant les anciens tordus des Bois maudits ?', 0),
(33113, 'frFR', 'Grâce à ce morceau de roche tombée, je vais pouvoir achever la consécration du puits de lune.', 0),
(33114, 'frFR', 'Grâce aux fragments d''âme réunis, nous allons piéger Gul''dan et mettre fin au Conseil des ombres sur Draenor.', 0),
(33133, 'frFR', 'Que ces breloques vous portent chance, $n.', 0),
(33134, 'frFR', 'Que ces breloques vous portent chance, $n.', 0),
(33168, 'frFR', 'Grâce à la puissance combinée des fragments, nous devrions pouvoir piéger Gul''dan.', 0),
(33228, 'frFR', 'Déjà de retour ? J''ai l''impression que nous avons parlé il y a quelques instants à peine.', 0),
(33238, 'frFR', 'Je crois que vous avez quelque chose pour moi !', 0),
(33332, 'frFR', 'Ah, vous êtes de retour. Avez-vous le journal ?', 0),
(33336, 'frFR', 'Avez-vous trouvé quelque chose ?', 0),
(33338, 'frFR', 'Les pierres d''époque sont de l''essence temporelle cristallisée, une denrée rare.', 0),
(33354, 'frFR', 'C''est ce que je crois que c''est ?', 0),
(33444, 'frFR', 'Avez-vous eu de la chance pour récupérer ces particules ?', 0),
(33450, 'frFR', 'Vous respirez encore, hmm ?$B$BAvez-vous réglé leur compte aux sous-fifres du seigneur de guerre ?', 0),
(33461, 'frFR', 'Avez-vous trouvé tous les ingrédients dont j''ai besoin ?', 0),
(33462, 'frFR', 'Cette enclume cabossée et de piètre qualité sert surtout à forger des chaînes et le peu d''autres travaux de métallurgie dont les Sire-tonnerre ont besoin.', 0),
(33483, 'frFR', 'Ces ogres vont bientôt découvrir l''autre côté de mes haches.', 0),
(33548, 'frFR', 'Nous sommes les Crâne-Ricanant ! Nous ne tremblons pas devant la mort. Nous en rions.', 0),
(33563, 'frFR', 'Vous l''avez fait hurler ? A-t-il imploré votre pitié ? L''avez-vous tué avant de lui prendre son œil ? Racontez-moi tout.', 0),
(33581, 'frFR', 'Quel genre d''individu malade brûle un livre rempli d''arts obscurs parfaitement valables ?!', 0),
(33633, 'frFR', 'Cette viande avariée a l''air dégoûtante. Trouvez quelque chose de sain à manger pour le fouineur.', 0),
(33660, 'frFR', 'Il me faut davantage de réactifs avant de retourner auprès de mes frères et sœurs.', 0),
(33695, 'frFR', 'Avez-vous quelque chose pour moi, petite bête ?', 0),
(33724, 'frFR', 'Je ne comprends pas pourquoi ces imbéciles ne rassemblent pas toutes les pages au même endroit.', 0),
(33734, 'frFR', 'Ce sont bien plus que de simples objets. Ils sont notre gagne-pain, notre passé et notre avenir, notre réconfort.$B$BIls sont une part de nous-mêmes.', 0),
(33735, 'frFR', 'Avez-vous déjà les explosifs de la Horde de Fer ?', 0),
(33761, 'frFR', 'Hm, c''est quoi, ce livre que vous avez là ?', 0),
(33787, 'frFR', 'Avez-vous obtenu les ingrédients ?', 0),
(33795, 'frFR', 'Votre aide est appréciée, $c.', 0),
(33808, 'frFR', 'Je voulais juste cueillir quelques herbes et me détendre avec mes garçons... J''aurais dû rester en Azeroth.', 0),
(33833, 'frFR', 'Vous venez pour la prime sur Kuu’rat ?', 0),
(33834, 'frFR', 'On raconte en ville que vous chassez Kliaa. Vous avez eu de la chance ?', 0),
(33836, 'frFR', 'Mon frère, Anduur, cueille des baies sauvages sur les collines au-dessus de notre village.$B$BC''est lors d''une de ses excursions qu''il a croisé Maa''run.$B$BJ''exige réparation pour ses blessures.', 0),
(33838, 'frFR', 'La puissance d''une arme vient à la fois de l''épreuve de son métal et du talent des mains qui la brandissent.', 0),
(33872, 'frFR', 'Avez-vous assez de poussière ?', 0),
(33873, 'frFR', 'Avez-vous récolté assez de baies d''Aruunem ?', 0),
(33920, 'frFR', 'J''espère que vous avez Karab''uun. On ne me connaît pas pour ma patience quand d''innombrables âmes à l''intérieur d''Auchindoun sont en danger.', 0),
(33944, 'frFR', 'Où avez-vous trouvé Ricky ?!', 0),
(33958, 'frFR', 'Le démon avait-il Sha''tari, comme nous le pensions ?', 0),
(33967, 'frFR', 'Avez-vous les crocs ? Nous n''avons pas beaucoup de temps !', 0),
(33970, 'frFR', 'Ce démon immonde avait-il Sha''tari, comme nous le pensions ?', 0),
(33971, 'frFR', 'Avez-vous les crocs ? Nous n''avons pas beaucoup de temps !', 0),
(33973, 'frFR', 'Le Maître-lame doit payer…', 0),
(33976, 'frFR', 'Il nous faut le dernier morceau du Cœur !', 0),
(33988, 'frFR', 'Restalaan serait heureux de savoir que quelqu''un a exaucé ses souhaits.', 0),
(34012, 'frFR', '<Rôdeur Sasha vous fixe de ses yeux froids et impitoyables.>', 0),
(34013, 'frFR', 'Certaines choses valent la peine qu''on se batte pour elles, $r. Celles-ci en font partie.', 0),
(34032, 'frFR', 'Ce livre contient mes notes de travail des cinq dernières années. C''est trop dangereux de le laisser derrière !', 0),
(34034, 'frFR', 'Salut ! Vous avez le fric ?', 0),
(34067, 'frFR', 'Je commence à en avoir assez d''attendre : avez-vous quelque chose pour aider notre assaut, oui ou non ?', 0),
(34069, 'frFR', 'Qu''y a-t-il, $C ? Vous avez quelque chose pour moi ?', 0),
(34072, 'frFR', 'Il nous faut ce goudron rapidement, $n ! Au travail !', 0),
(34089, 'frFR', 'Avez-vous déjà les explosifs de la Horde de Fer ?', 0),
(34092, 'frFR', 'Avez-vous pu obtenir l''aide des Ango''rosh ?', 0),
(34093, 'frFR', 'Qu''y a-t-il, $n ? Vous avez quelque chose pour moi ?', 0),
(34094, 'frFR', 'Où sont les pages ? Ces manuels ne sont que de la rigolade…', 0),
(34103, 'frFR', 'Vous avez réussi à retrouver la trace de cet oiseau, commandant ?', 0),
(34104, 'frFR', 'Avez-vous eu le temps de tuer Hilaani ?', 0),
(34107, 'frFR', 'C’est un plaisir de vous voir, commandant.', 0),
(34108, 'frFR', 'Si vous décidez de tuer cette créature, je donnerai votre nom à mon premier-né.', 0),
(34230, 'frFR', 'L''Anneau omnivoyant. Vous l''avez ?', 0),
(34264, 'frFR', 'Je commence à en avoir assez d''attendre : avez-vous quelque chose pour aider notre assaut, oui ou non ?', 0),
(34271, 'frFR', 'Quelles nouvelles de Gordawg ? Le grand esprit de la terre a-t-il trouvé la paix ?', 0),
(34281, 'frFR', 'Faites pas attention à moi. Je vais rester là à soigner mes blessures.', 0),
(34285, 'frFR', 'J''ai juste besoin d''un petit remontant, se faire tabasser par des ogres, ça courbature un peu. Qui l''aurait cru ?', 0),
(34288, 'frFR', 'Avez-vous ces totems que j''ai demandés ? Il les a laissés autour des bâtiments voisins.', 0),
(34291, 'frFR', 'Avez-vous la clé démoniaque ?', 0),
(34314, 'frFR', 'T''en fais pas pour moi, mon. Moi j''vais nulle part.', 0),
(34315, 'frFR', 'Ah, vous entendez ça ? J''crois qu''une autre côte vient de se remettre en place.', 0),
(34318, 'frFR', 'Avez-vous ces totems que j''ai demandés ? Il les a laissés autour des bâtiments voisins.', 0),
(34321, 'frFR', 'M''apportez-vous les restes de nos défunts ?', 0),
(34336, 'frFR', 'Ces orcs travaillaient sur les ordres de quelqu''un d''autre.', 0),
(34338, 'frFR', '<Thisalee vous regarde froidement.>', 0),
(34344, 'frFR', 'Ces rôdeurs vous ont fait fuir ?', 0),
(34345, 'frFR', 'Je cueillerais bien les fleurs moi-même, mais j''ai des allergies. Ha ha !', 0),
(34346, 'frFR', 'Un chasseur des ombres en sait long sur les esprits. On parle. On échange. Mais ces furies de glace, elles sont méchantes, patron.', 0),
(34351, 'frFR', 'Avez-vous un pylône de caronite et des cristaux ?', 0),
(34397, 'frFR', 'La Horde de Fer n''a aucune notion de l''honneur.', 0),
(34401, 'frFR', 'Avez-vous récupéré l''essence arcanique pour moi ?', 0),
(34403, 'frFR', 'Avez-vous déjà récolté assez d''essence arcanique ?', 0),
(34404, 'frFR', 'Avez-vous récolté les cristaux de puissance bruts dont j''ai besoin pour mes recherches ?', 0),
(34407, 'frFR', 'Tout Auchindoun, et les innombrables âmes qui s''y trouvent, dépend de notre réussite.', 0),
(34414, 'frFR', 'Avez-vous le cœur de géant de cristal ?', 0),
(34415, 'frFR', 'Avez-vous le cœur de géant de cristal ?', 0),
(34463, 'frFR', 'La magie temporelle est un domaine de recherche récent.', 0),
(34464, 'frFR', 'Je me demandais « quand » je vous reverrais. Ah... ? Ah... ? Vous voyez ?$B$BÉcoutez, aussi longtemps que quelqu''un a parlé, les dragons de bronze ont accaparé toutes les bonnes blagues sur le temps.$B$BEh bien maintenant, les gardiens du temps font une pause et il ne reste plus personne pour m''arrêter !', 0),
(34465, 'frFR', 'C''est si agréable de pouvoir enfin mener mes recherches sur ma passion sans que ces dragons de bronze importuns n''apparaissent.', 0),
(34466, 'frFR', 'J''ai fait mon temps avec le feu et les autres arts des arcanes. C''était bien. Rien ne vaut le fait de lancer une boule de feu géante.$B$BMais la sorcellerie temporelle ? Quel plaisir !$B$BVraiment difficile à maîtriser, mais on a toujours tout le temps devant soi.', 0),
(34512, 'frFR', 'Avez-vous les griffes de saberon que j''ai demandées ?', 0),
(34514, 'frFR', 'Greexlex vous a dit que les sabrons avaient volé notre marchandise ?$B$BEh bien, qu''est-ce que vous attendez ? Allez donc à Sabregueule et récupérez-la !$B$BLe temps, c''est de l''argent !', 0),
(34571, 'frFR', 'Il faut qu''on récupère ce minerai avant que ces goren ne le mangent en entier.', 0),
(34573, 'frFR', 'Il me faudra beaucoup de poussière d''iridium pour purifier le métal à un niveau proche des normes de mon maître.', 0),
(34576, 'frFR', 'Mais pour nettoyer le métal selon mes critères, il me faut beaucoup de poussière d''iridium.', 0),
(34577, 'frFR', 'Il faut qu''on récupère ce minerai avant que ces satanés goren ne le mangent en entier.', 0),
(34593, 'frFR', 'Ces ordres seraient vraiment utiles pour reconstituer toute cette affaire.', 0),
(34609, 'frFR', 'Les géants sont plus difficiles à remplir, mais ils ont plus d''ulcères !', 0),
(34634, 'frFR', 'Les géants ont bien plus de pustules que les sporoptères, mais ils sont bien plus coriaces.', 0),
(34656, 'frFR', 'Des lames d''aile forgées au nom d''un dieu soleil pour apporter liberté et gloire à ses enfants.$B$BUn masque porté par un grand roi qui se mêlait à son peuple sous un déguisement pour connaître sa véritable nature.', 0),
(34658, 'frFR', '<Reshad accroche un autre parchemin à Percy, qui pépie en signe de protestation.>$B$BNe fais pas l''andouille.', 0),
(34678, 'frFR', '$n, je ne peux pas vous dire à quel point je suis heureux de vous voir.', 0),
(34698, 'frFR', 'Avez-vous les pendentifs ?', 0),
(34703, 'frFR', 'Kor''gall règne sans partage depuis beaucoup trop longtemps.', 0),
(34719, 'frFR', 'J''ai du mal à voir. Je n''en ai peut-être plus pour longtemps.', 0),
(34751, 'frFR', 'Vous avez la marchandise, mon pote ?', 0),
(34761, 'frFR', 'Avez-vous les glandes d''anguille ?', 0),
(34766, 'frFR', 'Commandant ! Avez-vous eu le temps de retrouver nos provisions et nos registres ?', 0),
(34773, 'frFR', 'Commandant ! Avez-vous eu un moment pour vous occuper des sabrons ?', 0),
(34784, 'frFR', 'N''oubliez pas : à moins d''être $gcouvert:couverte; de poussière de champiluisant, les spores exploseront dès que vous vous approcherez.', 0),
(34786, 'frFR', 'Comment se passe votre carrière ?', 0),
(34790, 'frFR', 'La plupart du temps, les draeneis évitent Tenetopi, mais nous, les gens du rang, sommes attirés par les endroits les plus inhospitaliers et dangereux, car c''est seulement là que l''on peut pleinement comprendre l''ordre du monde.', 0),
(34801, 'frFR', 'Tuliaa n''est pas seulement ma sœur. C''est ma meilleure amie.', 0),
(34802, 'frFR', 'Je ne sais pas ce que je ferais sans Tuliaa... ce n''est pas seulement ma sœur. C''est ma meilleure amie.', 0),
(34809, 'frFR', '<Le Gold-O-Matic 9000 bourdonne et ronronne dans un vacarme de lourde machinerie.>', 0),
(34811, 'frFR', 'Avez-vous les antiquités de Nagrand ?', 0),
(34819, 'frFR', 'J''ai entendu la pire des rumeurs sur la manière dont on obtient ces choses.$B$BIl paraît que les talbuks les mangent d''abord, puis les « traitent », et ensuite... enfin, je préfère ne pas en parler.', 0),
(34822, 'frFR', 'Comment avance l''opération de récupération ?', 0),
(34828, 'frFR', 'Avez-vous trouvé la lunette ?', 0),
(34836, 'frFR', 'Que puis-je faire pour vous aider, $c ?', 0),
(34850, 'frFR', 'Avez-vous ma bannière ?', 0),
(34858, 'frFR', 'Avez-vous pu récupérer toutes mes lames ?', 0),
(34868, 'frFR', 'Avez-vous les plans de la garnison, commandant ?', 0),
(34869, 'frFR', 'Des venterocs ? Ouais, Nagrand en est infesté.$B$BIls semblent aimer les hauteurs et les pitons rocheux.$B$BJe ne sais pas. Je ressemble à quoi, moi - à un chuchoteur de venterocs ? Le $C, c''est vous.', 0),
(34870, 'frFR', 'Avez-vous ma masse ?', 0),
(34881, 'frFR', 'Apportez-moi les essences vivantes des éléments, afin que je puisse planter les graines de la renaissance.', 0),
(34883, 'frFR', 'Vous savez, ces élixirs que vous avalez si avidement ?$B$BIls sont faits de cette substance.', 0),
(34886, 'frFR', '<Ikki vous regarde, le bec dans les pattes, et pousse un couinement étranglé.>', 0),
(34887, 'frFR', 'La plupart des mages sous-estiment l''usage de la poussière arcanique de nos jours, mais ils se trompent.', 0),
(34890, 'frFR', 'Des ogres. C''est toujours des ogres.', 0),
(34894, 'frFR', 'Avez-vous la Fleur de braise ?', 0),
(34909, 'frFR', 'Ah, de la poudre des arcanes. Ça me rappelle mes jours d''apprenti.', 0),
(34912, 'frFR', 'Tout se joue en cet instant.', 0),
(34922, 'frFR', 'Il nous faut tous les textes sacrés ! Nous ne pouvons pas nous permettre d''en laisser un seul de côté !', 0),
(34924, 'frFR', 'Avez-vous pu retrouver les œufs de corbeau volés ?', 0),
(34925, 'frFR', 'Il faudra arracher cette clé de sa main froide et hideuse.', 0),
(34939, 'frFR', 'Le parchemin d''instruction dit que l''Ancêtre-Corbeau est impatient. Et moi aussi, soit dit en passant.$B$BAvez-vous $Gapporté:apporté; les pattes de la crinière sanglante ?', 0),
(34954, 'frFR', 'Un maître des lames sans lame n''est pas un maître des lames du tout.', 0),
(34955, 'frFR', 'Avez-vous ma bannière ?', 0),
(34958, 'frFR', 'Qu’est-ce que ça donne ?', 0),
(34960, 'frFR', 'Regardez-vous, tout ingénieux.', 0),
(34978, 'frFR', 'Avez-vous pu trouver des armes ?', 0),
(34987, 'frFR', 'N''allez pas faire n''importe quoi avec cette poudre à canon, hein.', 0),
(34991, 'frFR', 'La disparition de Tillik a profondément attristé la meute.', 0),
(34994, 'frFR', 'Avez-vous trouvé de la Jeune-racine ?', 0),
(34998, 'frFR', 'Reshad a envoyé un étranger ici ? Vous devez être très important... ou très dangereux.', 0),
(34999, 'frFR', 'Mes tentatives pour mettre en bouteille le sang accumulé ont échoué. Il se décompose et se dissipe dès qu''on l''éloigne des os de Sethe.$B$BMais je fonde de grands espoirs sur cette forme coagulée !', 0),
(35002, 'frFR', '<Un grand bol attend une offrande pour le dieu corbeau.>', 0),
(35005, 'frFR', 'Ces prisonniers ne sont pas moins courageux que vous ou moi, $n. Donnez-leur une arme et une once d''espoir, et ils se battront comme la tempête.', 0),
(35011, 'frFR', 'Avez-vous réduit au silence le faux roi ?', 0),
(35013, 'frFR', 'Qui… êtes-vous ? Pourquoi m''avez-vous tiré de mon sommeil ?', 0),
(35016, 'frFR', 'Peur de vous salir les mains ? Ce ne sont plus que des corps maintenant, inutile d''avoir peur.', 0),
(35019, 'frFR', 'Ces prisonniers ne sont pas moins courageux que vous ou moi, $n. Donnez-leur une arme et une once d''espoir, et ils se battront comme la tempête.', 0),
(35026, 'frFR', '<Nisha relève la tête.>', 0),
(35029, 'frFR', 'Où sont mes champignons ?!', 0),
(35030, 'frFR', 'Il me faut plus de ces cosses ! Beaucoup plus !', 0),
(35041, 'frFR', 'Que vous a fait cet orc ?!', 0),
(35066, 'frFR', 'Ça mord ?', 0),
(35069, 'frFR', 'Commandant. Comment puis-je vous aider ?', 0),
(35071, 'frFR', 'Ça mord ?', 0),
(35072, 'frFR', 'Ça mord ?', 0),
(35073, 'frFR', 'Ça mord ?', 0),
(35074, 'frFR', 'Ça mord ?', 0),
(35075, 'frFR', 'Ça mord ?', 0),
(35089, 'frFR', 'Vous avez déjà mon huile ?', 0),
(35090, 'frFR', 'Vous avez des pièces pour moi ?', 0),
(35101, 'frFR', 'Commandant. Comment puis-je vous aider ?', 0),
(35106, 'frFR', 'Le meurtrier paiera.', 0),
(35129, 'frFR', 'Et une fois de plus, vous me réjouissez.', 0),
(35136, 'frFR', 'L''artefact est à vous. Vous le méritez.', 0),
(35157, 'frFR', 'N''oubliez pas ! Récupérez les ordres et portez-les à Dalgorsh, plus loin à l''intérieur.', 0),
(35166, 'frFR', 'Les provisions sont vraiment au plus bas, commandant.', 0),
(35168, 'frFR', 'Oui ?', 0),
(35176, 'frFR', 'Pouvons-nous parler un peu plus tard, $GMonsieur:Madame; ? Je n''ai pas vraiment le temps de discuter pour le moment.', 0),
(35187, 'frFR', 'Oui, $ginitié:initiée; ?', 0),
(35188, 'frFR', 'Ces sales créatures ne méritent pas de vivre.', 0),
(35195, 'frFR', 'Ne vous inquiétez pas pour moi.', 0),
(35204, 'frFR', 'Avez-vous le pollen ?', 0),
(35209, 'frFR', 'Maintenant je comprends pourquoi certains deviennent Rangari. C''est exaltant.', 0),
(35216, 'frFR', 'Qu''est-ce que vous avez trouvé ?', 0),
(35233, 'frFR', 'Avez-vous des munitions ?', 0),
(35234, 'frFR', 'J''aime pas cet endroit. Si les plantes n''essaient pas de vous tuer, c''est le sol qui essaie de vous avaler.', 0),
(35235, 'frFR', 'Comment avancent les recherches ?', 0),
(35245, 'frFR', 'Hm ? Qu''est-ce que vous avez là ?', 0),
(35254, 'frFR', 'Les sbires démoniaques de Theron sont déjà en route vers le Cercle du Vide ?', 0),
(35258, 'frFR', 'Les Apogides avaient tous les avantages, et pourtant ils ont disparu. Que s''est-il passé ?', 0),
(35260, 'frFR', 'Impressionnantes, n''est-ce pas ? Ma propre création.$B$BUne simple effigie de bois portant juste une pincée d''enchantement.', 0),
(35261, 'frFR', '<Il y a une encoche dans l''accoudoir de ce confortable fauteuil.>', 0),
(35271, 'frFR', 'Qu’avez-vous à me proposer ?', 0),
(35322, 'frFR', 'Je reconnaîtrais l''un de mes schémas n''importe où.', 0),
(35329, 'frFR', 'Je reconnaîtrais l''un de mes schémas n''importe où.', 0),
(35337, 'frFR', 'C''est incroyable à quel point ces rangari peuvent être arrogants.', 0),
(35338, 'frFR', 'Cette étrangère croit vraiment qu''elle peut venir ici et me vaincre sur mes propres terres ?$B$BOh... pardon, commandant. Présente exceptée, bien sûr.', 0),
(35339, 'frFR', 'Tout est dans le brouillard... Que s''est-il passé ? Qui êtes-vous ?', 0),
(35345, 'frFR', 'Merci infiniment d''avoir retrouvé mon père.', 0),
(35350, 'frFR', 'La corne de Banthar. Hemet serait vert de jalousie à l''idée d''avoir une nouvelle chance d''affronter une bête aussi puissante.', 0),
(35353, 'frFR', 'La créature est-elle morte ?', 0),
(35357, 'frFR', 'Comment se passe la traque de Talbukus ?', 0),
(35374, 'frFR', 'C''est incroyable à quel point ces loups-de-givre peuvent être arrogants.', 0),
(35375, 'frFR', 'La corne de Banthar. Hemet serait vert de jalousie à l''idée d''avoir une nouvelle chance d''affronter une bête aussi puissante.', 0),
(35376, 'frFR', 'Cet étranger croit vraiment qu''il peut venir ici et me vaincre sur mes propres terres ?$B$BOh... pardon, commandant. Présent excepté, bien sûr.', 0),
(35378, 'frFR', 'Comment se passe la traque de Talbukus ?', 0),
(35386, 'frFR', 'Qu’avez-vous à me proposer ?', 0),
(35395, 'frFR', 'Et Gordawg ? La grande fureur a-t-elle été apaisée ?', 0),
(35406, 'frFR', 'Qu''avez-vous trouvé ?', 0),
(35408, 'frFR', 'J''espère que vous apportez un canon et des boulets, soldat.', 0),
(35429, 'frFR', 'Peu osent défier les botani dans l''art de faire pousser les plantes.', 0),
(35434, 'frFR', 'Pendant des années, les Crâne-Ricanant n''ont pas voulu toucher aux eaux sacrées. Nous craignions la colère des botani. Nous aurions dû les faire brûler il y a longtemps.', 0),
(35486, 'frFR', 'Avez-vous pu accéder à des plans de bataille ?', 0),
(35494, 'frFR', 'Avez-vous trouvé quelque chose ?', 0),
(35501, 'frFR', 'Dans ce dispositif de chargement, vous pouvez charger plusieurs obus fatals à la fois.', 0),
(35509, 'frFR', 'Kaz veut que je me cache pendant ce combat.', 0),
(35633, 'frFR', 'Les familles de mon escouade ont besoin de tourner la page, et nous avons besoin d''en savoir plus sur leur mort.', 0),
(35634, 'frFR', 'Avez-vous apporté le dispositif ?', 0),
(35636, 'frFR', 'Tenez, je vais garder les deux en lieu sûr.', 0),
(35645, 'frFR', 'Où sont mes champignons ?!', 0),
(35647, 'frFR', 'Ces cosses sont essentielles, $p, il me les faut !', 0),
(35652, 'frFR', 'Glisa sait manier les outils.', 0),
(35663, 'frFR', 'Avez-vous récupéré les mystérieux artefacts ? Tout est une question de travail d''équipe !', 0),
(35668, 'frFR', 'Ce trésor... Étonnamment, cette Griffe solaire a-t-elle seulement deviné sa signification ?', 0),
(35669, 'frFR', 'Lok’tar, commandant.', 0),
(35670, 'frFR', 'C''est un honneur de vous avoir dans ma boutique, commandant.', 0),
(35674, 'frFR', 'Un plaisir de vous voir, $Gmonsieur:madame;.', 0),
(35675, 'frFR', 'Oh, $gcommandant:commandante; ! Quel honneur !$B$BEn quoi puis-je vous aider ?', 0),
(35676, 'frFR', 'Faites-la taire... ek !', 0),
(35683, 'frFR', 'Ce que je demande n''est pas une tâche facile, car ses rejetons sont redoutables. Comment se passe l''offensive ?', 0),
(35684, 'frFR', 'Ce que je demande n''est pas une tâche facile, car ses disciples sont redoutables. Comment se passe l''offensive ?', 0),
(35702, 'frFR', 'Nous avons l''artefact, et grâce à lui, nous ferons payer la Horde de Fer.', 0),
(35706, 'frFR', 'Avez-vous les piles ?', 0),
(35716, 'frFR', 'Qu’est-ce que ça donne ?', 0),
(35730, 'frFR', 'Nisha doit s''en sortir.', 0),
(35738, 'frFR', 'Si vous avez la marchandise, discutons.', 0),
(35739, 'frFR', 'Fichue technologie gobeline reconditionnée, elle est toujours en panne.', 0),
(35750, 'frFR', 'Avez-vous pu accéder à des plans de bataille ?', 0),
(35761, 'frFR', 'Avez-vous trouvé quelque chose ?', 0),
(35797, 'frFR', 'J''aurais probablement dû vous préciser que le laser est assez... puissant.', 0),
(35835, 'frFR', 'Au fait, ce laser est très dangereux. Faites attention !', 0),
(35840, 'frFR', 'Avez-vous quelque chose pour moi ?', 0),
(35846, 'frFR', 'Vous avez quelque chose pour moi ?', 0),
(35870, 'frFR', '<Nisha renifle profondément.>', 0),
(35925, 'frFR', 'Utiliser les gronns comme armes ? S''ils réussissent...', 0),
(35926, 'frFR', 'Vous avez trouvé quelque chose ?', 0),
(35928, 'frFR', 'J''ai plein de viande. Vous devriez en acheter.$B$BCe dont j''ai vraiment besoin, ce sont des os. Les animaux de Nagrand sont les plus robustes de tout Draenor. Ils ont des os de première qualité.$B$BJe prépare la soupe la plus savoureuse que vous ayez jamais goûtée. Je vais montrer à ce Crevéfils qui est vraiment le meilleur cuisinier.', 0),
(35933, 'frFR', 'Ce message porte la marque du clan Chanteguerre.', 0),
(35935, 'frFR', 'Nous devons tenir la ligne !', 0),
(35970, 'frFR', 'Qu''avez-vous trouvé ? Quelque chose qui vaille la peine d''être vendu ? Euh… conservé.', 0),
(35973, 'frFR', 'Vous êtes-vous $goccupé:occupée; de Brokyo ?', 0),
(35990, 'frFR', 'Êtes-vous déjà $gallé:allée; aux Mines de Scories ?$B$BFranchement, qui extrait des scories, d''ailleurs ? Qu''est-ce qu''on en fait ?', 0),
(35991, 'frFR', 'Vous avez le cœur du moteur ?$B$BEn temps normal, je ne vous demanderais pas d''assaillir un train fortifié en mouvement... ah, non, c''est faux. C''est exactement le genre de chose dont j''aurai besoin de vous. Tout le temps.', 0),
(35992, 'frFR', 'Comment va l''avant-poste ? Plus important encore... où est mon cœur de vie ?', 0),
(35993, 'frFR', 'Quelles nouvelles d''Auchindoun ? Les esprits des draeneï sont-ils en sécurité ?$B$BAvais-je raison au sujet de Teron’gor ?', 0),
(35997, 'frFR', 'Qu''avez-vous trouvé à Cognefort ?', 0),
(35998, 'frFR', 'Avez-vous les pierres ? Je n''aurais jamais cru me tourner vers les ogres pour la puissance magique, mais ces anciens rois-sorciers en savaient long sur l''énergie arcanique brute, de quoi occuper les érudits du Kirin Tor pendant des siècles.', 0),
(36009, 'frFR', 'Les « furies » élémentaires semblent propres à Draenor. Cela tient peut-être à la nature primitive de ce monde.', 0),
(36010, 'frFR', 'Avez-vous le Tome du courbe-flamme ? De nombreuses armes légendaires de la Lame ardente doivent leur existence à ce volume !', 0),
(36012, 'frFR', 'L''orbe ! Dites-moi que vous avez trouvé l''orbe... ?', 0),
(36013, 'frFR', 'J''ai pu consacrer un peu de temps à l''étude de la préhistoire de Draenor. Des forces élémentaires primordiales se disputaient pour façonner le monde, en ce que l''on nomme l''âge des Colosses. Leurs descendants se battent encore aujourd''hui, en particulier dans des régions comme Gorgrond.$B$BLes tablettes que vous assemblez révéleront les forces à l''œuvre à cette époque... et surtout, elles nous permettront de contrôler et de canaliser ces forces, exactement comme le font aujourd''hui les Rochenoire !', 0),
(36014, 'frFR', 'Alors, $n ? Êtes-vous $garmé:armée; ?', 0),
(36047, 'frFR', 'Avez-vous rassemblé tout ce dont vous avez besoin ?', 0),
(36048, 'frFR', 'Je ne veux pas rester ici plus longtemps que nécessaire.', 0),
(36054, 'frFR', 'L''or est vraiment un trésor. Et si on échangeait un trésor contre de l''or ? C''est exactement ce que propose mon offre. Le sceau du destin capricieux déforme le temps et augmente votre chance juste quand vous en avez besoin.

Souvenez-vous seulement que vous ne pouvez pas obtenir plus de trois de ces sceaux par semaine. Ce sceau compte pour l''un de ces trois. J''en aurai peut-être de nouveaux la semaine prochaine.', 0),
(36123, 'frFR', 'C''était rapide, m''avez-vous apporté un morceau de leur armure comme preuve ?', 0),
(36131, 'frFR', 'Vous avez attrapé ces anguilles ?', 0),
(36132, 'frFR', 'Nous pouvons nous en servir comme appât ?!', 0),
(36133, 'frFR', 'Ce sont des fragments d''artéfact, que je vois là ?', 0),
(36134, 'frFR', 'Ça n''a pas l''air bon.', 0),
(36137, 'frFR', 'Ce fief ne va pas se construire tout seul, commandant ! Il nous faut du bois !', 0),
(36141, 'frFR', 'Vous avez ces dards pour moi ?', 0),
(36142, 'frFR', 'Avez-vous déjà récolté cet échantillon de bois ?', 0),
(36157, 'frFR', 'Les arakkoa que nous voyons aujourd''hui ne sont plus que l''ombre de leur gloire passée. Ils se terrent au sommet de leurs flèches et dominent du regard les terres en contrebas, suffisants et hautains. La vérité, c''est qu''ils ont été chassés vers ces perchoirs élevés par ces mêmes ennemis qu''ils regardent de haut aujourd''hui.$B$BJe voudrais que les arakkoa soient plus faciles à traiter. Leur maîtrise des rayons du soleil aurait pu nous être précieuse.', 0),
(36158, 'frFR', 'Avez-vous les cristaux ? J''espère que vous avez fait un compte exact. Si vous vous êtes $gtrompé:trompée;, je ne saurais être tenu responsable des conséquences.', 0),
(36160, 'frFR', 'Nous sommes attaqués !', 0),
(36177, 'frFR', 'La sacoche est pleine et prête à être livrée.', 0),
(36182, 'frFR', 'Avez-vous déjà récolté cet échantillon de bois ?', 0),
(36189, 'frFR', 'Ce fief ne va pas se construire tout seul, commandant ! Il nous faut du bois !', 0),
(36194, 'frFR', 'Avez-vous déjà récolté cet échantillon de bois ?', 0),
(36195, 'frFR', 'Avez-vous déjà récolté cet échantillon de bois ?', 0),
(36198, 'frFR', 'Ce sont des fragments d''artéfact, que je vois là ?', 0),
(36199, 'frFR', 'Vous avez ces griffes pour moi ?', 0),
(36201, 'frFR', 'Vous avez attrapé ces esturgeons ?', 0),
(36202, 'frFR', 'Nous pouvons nous en servir comme appât ?!', 0),
(36205, 'frFR', 'Que voulez-vous, $r ?', 0),
(36207, 'frFR', 'Salutations, $R, qu''est-ce qui vous amène à la tombe de ce vieil orc ?', 0),
(36208, 'frFR', 'J''ai appris quelques traditions des Crâne-Ricanant. C''est moins étrange que bien d''autres.', 0),
(36209, 'frFR', 'Ce déguisement de goren sent affreusement mauvais.', 0),
(36210, 'frFR', 'Les gorens semblent prêts à manger tout ce qui se trouve sur leur chemin, vivant ou non.', 0),
(36220, 'frFR', 'Personne n''entre dans les terrains d''épreuve sans que je le dise.', 0),
(36221, 'frFR', 'Ne me faites pas perdre mon temps, $R. Quelle affaire avez-vous avec Mogor ?', 0),
(36223, 'frFR', 'Encore une fois, vous avez bien travaillé, $gmon ami:mon amie;.', 0),
(36228, 'frFR', 'MONTREZ-MOI LES FRAGMENTS D''ARMURE !', 0),
(36230, 'frFR', 'C''est donc fait ?', 0),
(36236, 'frFR', 'Qu''as-tu là, mon enfant ?', 0),
(36238, 'frFR', 'Mon père... mais comment avez-vous....', 0),
(36240, 'frFR', 'Ah, voilà exactement ce que je cherchais !', 0),
(36256, 'frFR', 'Salutations, $genchanteur:enchanteresse;. Je vois que vous connaissez cet art. $B$BBien, bien. Peut-être pouvons-nous nous entraider.', 0),
(36260, 'frFR', 'Vous l''avez ? Donnez-le-moi.', 0),
(36262, 'frFR', 'Bonjour, $gvoyageur:voyageuse; ! Puis-je vous aider en quelque chose ?', 0),
(36266, 'frFR', 'Avez-vous pu vous procurer les robes ?', 0),
(36275, 'frFR', 'Avez-vous récupéré mes affaires manquantes ?', 0),
(36284, 'frFR', 'Avez-vous recueilli les échantillons de spores pour mes recherches ?', 0),
(36285, 'frFR', 'Sans cerveau fongique à examiner, les mystères de l''écosystème de Zangar resteront entiers !', 0),
(36287, 'frFR', 'Ne vous inquiétez pas. On ne fait que les emprunter à la Horde de Fer !', 0),
(36301, 'frFR', 'C''est mon nécessaire de couture ! Je n''aurais jamais cru le revoir un jour.', 0),
(36310, 'frFR', 'Salutations, $genchanteur:enchanteresse;. Je vois que vous connaissez cet art. $B$BBien, bien. Peut-être pouvons-nous nous entraider.', 0),
(36314, 'frFR', 'Tiens, bonjour $n, qu''avons-nous là ?', 0),
(36315, 'frFR', 'Le bâton ! Donnez-le-moi !', 0),
(36376, 'frFR', 'Nous devons tenir la ligne !', 0),
(36378, 'frFR', 'Avez-vous obtenu les matériaux que j''ai demandés ?', 0),
(36385, 'frFR', 'Qu''avez-vous là, $gcommandant:commandante; ?', 0),
(36409, 'frFR', 'La puissance du cristal pulse tandis qu''on le transporte.', 0),
(36412, 'frFR', 'Nous devons tenir la ligne !', 0),
(36417, 'frFR', 'Eh bien, c''est fait ?', 0),
(36435, 'frFR', '<Raleigh lève les yeux des parchemins.>$B$BCommandant $n, qu''est-ce qui vous amène à Wor’gol ?!', 0),
(36441, 'frFR', 'Le sabron ne doit ABSOLUMENT PAS avoir une seule des herbes que vous avez trouvées !', 0),
(36442, 'frFR', 'Avez-vous quelque chose pour moi, petite bête ?', 0),
(36448, 'frFR', 'Avez-vous remis l''... avis de licenciement ?', 0),
(36449, 'frFR', 'Mon frère a-t-il déjà reçu son avis de licenciement ?', 0),
(36475, 'frFR', 'Un recueil de poèmes ? Je vous laisse le garder pour l''instant...', 0),
(36483, 'frFR', 'Ces familiers avaient l''air coriaces. Comment ça s''est passé ?', 0),
(36505, 'frFR', 'Salutations, $R. Avez-vous besoin de réparations ?', 0),
