INSERT INTO `quest_request_items_locale` (`ID`, `Locale`, `CompletionText`, `VerifiedBuild`) VALUES
(37159, 'frFR', 'Vous avez apporté une plume ?', 0),
(37160, 'frFR', 'Quoi ?', 0),
(37161, 'frFR', 'Où est mon couteau ?', 0),
(37162, 'frFR', 'Avez-vous trouvé des preuves de la présence de dragons ?', 0),
(37163, 'frFR', 'Avez-vous trouvé des notes de Ner''zhul ?', 0),
(37164, 'frFR', 'Avez-vous trouvé quelque chose ?', 0),
(37165, 'frFR', 'La chance vous a souri, $gmon ami:mon amie; ?', 0),
(37166, 'frFR', 'Avez-vous trouvé des signes des titans ici ?', 0),
(37167, 'frFR', 'Vous m''avez trouvé des armes ?', 0),
(37179, 'frFR', 'Avez-vous trouvé l''Etoile de Fer ?', 0),
(37180, 'frFR', 'Je veux mon épée plus que je ne saurais le dire, commandant.', 0),
(37181, 'frFR', 'Les éléments ne parlent plus à Leorajh comme avant.', 0),
(37182, 'frFR', 'Éliminer nos ennemis et gagner un grand pouvoir d’un seul geste... mon peuple a un dicton pour cela : tuer deux orcs d’un seul coup de pierre.', 0),
(37209, 'frFR', 'Laissez-moi seul.', 0),
(37227, 'frFR', '<Mylune piaffe d''impatience.>', 0),
(37228, 'frFR', 'LE MARCHAND DE FRUITS N’A AUCUNE CHANCE !', 0),
(37229, 'frFR', '<Olaf sanglote.>', 0),
(37230, 'frFR', 'Le commandant a-t-il réussi ?', 0),
(37231, 'frFR', 'Avez-vous trouvé le compas ?', 0),
(37232, 'frFR', 'Avez-vous trouvé la lame ?', 0),
(37233, 'frFR', 'Avez-vous trouvé quelque chose ?', 0),
(37234, 'frFR', 'Avez-vous trouvé le cristal ?', 0),
(37235, 'frFR', 'Vous avez apporté une plume ?', 0),
(37236, 'frFR', 'Où est mon couteau ?', 0),
(37237, 'frFR', 'Avez-vous trouvé des preuves de la présence de dragons ?', 0),
(37238, 'frFR', 'Avez-vous trouvé des notes de Ner''zhul ?', 0),
(37239, 'frFR', 'Avez-vous trouvé quelque chose ?', 0),
(37240, 'frFR', 'La chance vous a souri, $gmon ami:mon amie; ?', 0),
(37241, 'frFR', 'Avez-vous trouvé des signes des titans ici ?', 0),
(37242, 'frFR', 'Vous m''avez trouvé des armes ?', 0),
(37243, 'frFR', 'Quoi ?', 0),
(37244, 'frFR', 'Vous avez rapporté une autre mouche ?', 0),
(37245, 'frFR', 'Vous savez bien que chaque instant que vous perdez à me parler nous rapproche de notre perte, n''est-ce pas ?', 0),
(37256, 'frFR', '<Le garde de la nuit vous regarde avec espoir.>', 0),
(37257, 'frFR', 'Mon peuple ne m''estime peut-être pas beaucoup, mais cela ne m''empêchera pas de veiller sur lui.', 0),
(37268, 'frFR', 'Nous rassemblerons les troupes dès que vous en donnerez l’ordre, commandant.', 0),
(37284, 'frFR', 'Vous les avez ?', 0),
(37285, 'frFR', 'Pour vous.', 0),
(37293, 'frFR', 'Je me sens pas très bien.', 0),
(37318, 'frFR', '<Le chaudron bouillonne et frémit.>', 0),
(37319, 'frFR', 'Comptez-vous honorer la commande ? Nous pouvons nous permettre de refuser le travail, bien sûr, mais c''est une bonne offre.', 0),
(37320, 'frFR', 'Comptez-vous honorer la commande ? Nous pouvons nous permettre de refuser le travail, bien sûr, mais c''est une bonne offre.', 0),
(37321, 'frFR', 'Comptez-vous honorer la commande ? Nous pouvons nous permettre de refuser le travail, bien sûr, mais c''est une bonne offre.', 0),
(37322, 'frFR', 'L''arcanum vibre dans votre main à mesure que vous approchez du mémorial.', 0),
(37323, 'frFR', 'Comptez-vous honorer la commande ? Nous pouvons nous permettre de refuser le travail, bien sûr, mais c''est une bonne offre.', 0),
(37324, 'frFR', 'Si nous n''obtenons pas davantage de minerai de rochenoire, nous ne pourrons pas honorer les commandes.', 0),
(37325, 'frFR', 'Nous avons de la chance que nos bijoux soient si populaires, mais nous ne pourrons pas en fabriquer d''autres sans véritable fer.', 0),
(37332, 'frFR', 'Qu''avez-vous trouvé, $C ?', 0),
(37440, 'frFR', 'Beaucoup de créatures de l''île étaient autrefois liées à la non-agression et à la placidité par nos talents magiques. Quand le Fléau a détruit le Puits de soleil, notre emprise sur ces créatures s''est brisée. Les éclats arcaniques sont les vestiges du contrôle que nous exercions jadis et pourraient donc servir à fabriquer un nouveau dispositif pour nous aider à le reprendre.$B$BMieux encore, peut-être pourrait-on utiliser les éclats pour voir de quel mal l''île souffre réellement...', 0),
(37443, 'frFR', 'Avez-vous eu l''occasion de retrouver mes affaires ? Quand nous aurons réaffirmé notre domination sur l''Île de Haut-Soleil, j''en aurai besoin pour mon travail. Pour l''instant, cependant, je dois maintenir ma veille sur le Puits de soleil... ou ce qu''il en reste.', 0),
(37444, 'frFR', 'Plus nous dégagerons le Nidebois, plus vite Zhanaa pourra se remettre au travail.', 0),
(37445, 'frFR', 'Quand nous aurons ces pièces détachées, je sais que nous réparerons cet émetteur. Avec un peu de chance, il restera quelqu''un d''autre à qui parler.', 0),
(37446, 'frFR', 'Bon à rien de paresseux...$B$B Hein ? Avez-vous ma matraque ? Avez-vous surpris des péons en train de dormir au travail ?!', 0),
(37447, 'frFR', 'Quand nous aurons assez de sang de démon, vous pourrez commencer le rituel.', 0),
(37450, 'frFR', 'S''il reste encore des dragons bleus, nous devons faire tout notre possible pour gagner leur faveur et obtenir leur soutien.', 0),
(37469, 'frFR', '<Le dernier fragment de la pierre des marées repose devant vous.>', 0),
(37492, 'frFR', 'L''avez-vous vu ?', 0),
(37507, 'frFR', 'Allez. Allez lui parler.', 0),
(37528, 'frFR', 'Dès que j''en aurai l''occasion, j''armerai les gladiateurs de la baie d''Oceania.', 0),
(37540, 'frFR', 'Salutations, $C. Je vois que vous avez remporté un trophée lors de vos récents combats.', 0),
(37541, 'frFR', 'Salutations, $C. Je vois que vous avez remporté un trophée lors de vos récents combats.', 0),
(37543, 'frFR', 'Salutations, $C. Je vois que vous avez remporté un trophée lors de vos récents combats.', 0),
(37547, 'frFR', 'Salutations, $C. Je vois que vous avez remporté un trophée lors de vos récents combats.', 0),
(37548, 'frFR', 'Salutations, $C. Je vois que vous avez remporté un trophée lors de vos récents combats.', 0),
(37549, 'frFR', 'Salutations, $C. Je vois que vous avez remporté un trophée lors de vos récents combats.', 0),
(37550, 'frFR', 'Salutations, $C. Je vois que vous avez remporté un trophée lors de vos récents combats.', 0),
(37551, 'frFR', 'Salutations, $C. Je vois que vous avez remporté un trophée lors de vos récents combats.', 0),
(37552, 'frFR', 'Salutations, $C. Je vois que vous avez remporté un trophée lors de vos récents combats.', 0),
(37553, 'frFR', 'Salutations, $C. Je vois que vous vous êtes $gacquitté:acquittée; de votre tâche de façon admirable.', 0),
(37554, 'frFR', 'Salutations, $C. Je vois que vous vous êtes $gacquitté:acquittée; de votre tâche de façon admirable.', 0),
(37555, 'frFR', 'Salutations, $C. Je vois que vous vous êtes $gacquitté:acquittée; de votre tâche de façon admirable.', 0),
(37557, 'frFR', 'Salutations, $C. Je vois que vous vous êtes $gacquitté:acquittée; de votre tâche de façon admirable.', 0),
(37558, 'frFR', 'Salutations, $C. Je vois que vous vous êtes $gacquitté:acquittée; de votre tâche de façon admirable.', 0),
(37559, 'frFR', 'Salutations, $C. Je vois que vous vous êtes $gacquitté:acquittée; de votre tâche de façon admirable.', 0),
(37560, 'frFR', 'Salutations, $C. Je vois que vous vous êtes $gacquitté:acquittée; de votre tâche de façon admirable.', 0),
(37561, 'frFR', 'Salutations, $C. Je vois que vous vous êtes $gacquitté:acquittée; de votre tâche de façon admirable.', 0),
(37562, 'frFR', 'Salutations, $C. Je vois que vous vous êtes $gacquitté:acquittée; de votre tâche de façon admirable.', 0),
(37568, 'frFR', 'Oui ?', 0),
(37569, 'frFR', 'Oui ?', 0),
(37570, 'frFR', 'Oui ?', 0),
(37571, 'frFR', 'Oui ?', 0),
(37572, 'frFR', 'Oui ?', 0),
(37573, 'frFR', 'Oui ?', 0),
(37574, 'frFR', 'Oui ?', 0),
(37575, 'frFR', 'Oui ?', 0),
(37644, 'frFR', 'Qu’est-ce que ça donne ?', 0),
(37645, 'frFR', 'Qu’est-ce que ça donne ?', 0),
(37653, 'frFR', 'Nous avons besoin de ces âmes de démons, $c.', 0),
(37656, 'frFR', 'Si nous voulons gagner la guerre contre la Légion, nous devons savoir exactement ce que les démons préparent.', 0),
(37657, 'frFR', 'Comment se passe le dépouillement ?', 0),
(37727, 'frFR', 'Nous reparlons-nous parce que vous avez mes œufs ?', 0),
(37728, 'frFR', 'Ouais ? Vous avez des yeux ?', 0),
(37729, 'frFR', 'Pour les affaires, pour les affaires ! Remuez-vous les jambes !', 0),
(37730, 'frFR', 'Avez-vous pu rencontrer la directrice ?', 0),
(37736, 'frFR', 'Tout le monde essaie d''entrer à l''académie, d''après ce que je vois.', 0),
(37773, 'frFR', '$gMonsieur:Madame;, qu''est-ce que vous avez là ?', 0),
(37777, 'frFR', 'Des ordres, $gcommandant:commandante; ?$B$BEt c''est quoi cette horrible odeur ?!', 0),
(37778, 'frFR', 'Oui, commandant ?', 0),
(37811, 'frFR', 'Avez-vous trouvé cette vieille lame que cherchait le Dr Jones ?', 0),
(37813, 'frFR', 'Qu''est-ce qui fait ce boucan d''enfer ? C''est le cristal d''Améthon que vous tenez là ?', 0),
(37817, 'frFR', 'Eh, commandant.$B$BC''est quoi, cette horrible odeur ?', 0),
(37818, 'frFR', 'Eh, chef. Que puis-je faire pour vous aujourd''hui ?', 0),
(37834, 'frFR', '<Les doigts de Khadgar luisent d''impatience.>$B$BL''orbe ! L''avez-vous trouvée ?', 0),
(37852, 'frFR', 'Avez-vous pu reprendre l''amulette à l''arakkoa ?', 0),
(37859, 'frFR', '$gAstucieux:Astucieuse;, $r. Oui, un cristal de ligne tellurique devrait leur faire retrouver leurs esprits.', 0),
(37885, 'frFR', 'Le Dr Jones m''a demandé de prendre ce livre que vous avez, mais je ne suis pas sûr de vouloir le toucher.', 0),
(37919, 'frFR', 'Êtes-vous $grevenu:revenue; avec la relique des Seigneurs-du-tonnerre ?', 0),
(37945, 'frFR', 'Ce doit être le crâne maudit. Êtes-vous $gsûr:sûre; que nous devrions y toucher ?', 0),
(37959, 'frFR', 'Vous les avez ? Dites-moi que vous les avez, $gmon ami:mon amie;.', 0),
(37960, 'frFR', 'À chaque crétin que vous tuez, je gagne en puissance.', 0),
(37961, 'frFR', 'Récupérez un Booster de basses, un Lecteur de disques Laz-Tron, un Amplificateur phonique, un Condensateur S.P.R.K. et une Corde de bois ancien.', 0),
(37979, 'frFR', 'Avez-vous pu restaurer le cristal draenei ?', 0),
(37992, 'frFR', 'C''est la lame que cherchait Jones ?', 0),
(37993, 'frFR', 'Tu as réussi à récupérer l''amulette ?', 0),
(37994, 'frFR', 'Je sens du mauvais vaudou venir de vous, l''ami.$B$BC''est ce livre-là que je sens ?', 0),
(37995, 'frFR', 'Toi apporter la lance des Sire-tonnerre ?', 0),
(37996, 'frFR', 'Ça doit être le crâne maudit que vous avez là.', 0),
(37997, 'frFR', 'Toi avoir remis le cristal en un morceau ?', 0),
(38036, 'frFR', 'Avez-vous trouvé quelque chose ?', 0),
(38053, 'frFR', 'Sans cette batterie, je ne peux pas construire de nouvel émetteur !', 0),
(38147, 'frFR', 'Quelqu''un nous a pris dans un sort sinistre.', 0),
(38175, 'frFR', 'Avez-vous les chutes que j''ai demandées ?', 0),
(38188, 'frFR', 'Avez-vous les chutes que j''ai demandées ?', 0),
(38203, 'frFR', 'Avez-vous trouvé les morceaux de la recette ?', 0),
(38213, 'frFR', 'La reliure est sale, mais les pages sont toujours en bon état. Au bas de la reliure, on peut lire : « Propriété d''Iskar. »', 0),
(38223, 'frFR', 'J''aurais préféré ne pas en arriver là...', 0),
(38232, 'frFR', 'Cette terre est mûre pour la cueillette. Surtout les olives. Elles sont vraiment mûres. Et j''adore les olives mûres.', 0),
(38241, 'frFR', 'Salutations, monsieur. Avez-vous trouvé la pierre ?', 0),
(38242, 'frFR', 'Où qu''elle est, la pierre ?', 0),
(38254, 'frFR', 'Commandant, c''est vous ! Naielle avait promis qu''elle enverrait quelqu''un.', 0),
(38256, 'frFR', 'Je reconstruirai.', 0),
(38259, 'frFR', 'Il me faudra des matériaux de construction, commandant. On ne peut pas construire des quais avec de la boue.', 0),
(38274, 'frFR', 'Qu''avez-vous appris ?', 0),
(38307, 'frFR', 'Si seulement elle ne m''avait pas ordonné de vous amener à elle, $gsain et sauf:saine et sauve;...', 0),
(38308, 'frFR', '<L''espion nain gardait un compte rendu détaillé de l''emplacement des forces réprouvées.>', 0),
(38324, 'frFR', 'Assurez-vous d''avoir assez d''os avant qu''on parte.', 0),
(38331, 'frFR', 'Ça sent bon, n''est-ce pas ?', 0),
(38337, 'frFR', 'Oh, qu''avez-vous là ?', 0),
(38339, 'frFR', 'En avez-vous assez pour un déguisement convenable ?', 0),
(38345, 'frFR', 'Comment se passe la chasse aux pièces ?', 0),
(38346, 'frFR', 'Alors ? Avez-vous les pièces que je vous ai demandé de trouver ?', 0),
(38347, 'frFR', 'Par les dieux, c''est quoi cette puanteur ?! $B$BCe déguisement a intérêt à marcher !', 0),
(38356, 'frFR', 'Récupérez un Booster de basses, un Lecteur de disques Laz-Tron, un Amplificateur phonique, un Condensateur S.P.R.K. et une Corde de bois ancien.', 0),
(38361, 'frFR', 'Les chiffons ne me servent à rien ! Si vous n''avez pas le courage de vous venger de l''ennemi, fichez le camp, et que je ne vous voie plus !', 0),
(38362, 'frFR', 'Avez-vous sa tête ?', 0),
(38376, 'frFR', '<Maxwell peine à garder son regard fixé sur vous.>', 0),
(38394, 'frFR', 'Oui ? Vous avez ces pièces, alors ?', 0),
(38395, 'frFR', 'J''espère vraiment que ces pièces pourront compléter cet ensemble pour que je puisse les ven... euh, pour que je puisse les chérir à jamais.', 0),
(38396, 'frFR', 'Nous sommes au bord d''une découverte majeure.', 0),
(38397, 'frFR', 'Quelqu''un vous a-t-il dit aujourd''hui que vous êtes $gbeau:belle; ? C''est le cas.', 0),
(38402, 'frFR', 'Travail incroyable. Vous allez être $gun héros:une héroïne; à la Ligue des explorateurs, c''est sûr.', 0),
(38404, 'frFR', 'Vous m''avez rendu un service des plus merveilleux. Je ne vous oublierai pas, mon cœur. Du moins pas cette semaine.', 0),
(38405, 'frFR', 'Tout est trouvé ?', 0),
(38413, 'frFR', 'Quelles nouvelles avez-vous de mes frères et sœurs ?', 0),
(38455, 'frFR', 'Est-ce que ça a marché ?', 0),
(38505, 'frFR', 'Vous venez de la boutique d''Alard ? Que veut encore cette tête de muscle ?', 0),
(38506, 'frFR', 'Des Hauts-nés ! D''anciens Hauts-nés ! Quelle découverte extraordinaire !', 0),
(38507, 'frFR', 'Avez-vous trouvé l''atelier d''ingénierie ?', 0),
(38515, 'frFR', 'Comment avancent les recherches de vulpilles ?', 0),
(38519, 'frFR', 'Je n''ai pas de patrons pour les heaumes ou les bottes.$B$BUn tauren incapable de survivre à quelques coups de sabot n''a pas sa place au combat. Les bottes nous sont de peu d''utilité.$B$BUn heaume est l''armure d''un lâche. Je suis désolé si cela vous offense, mais c''est la vérité.$B$BEn revanche, les jambières jouent un rôle vital. Je partagerai volontiers ce patron avec vous, une fois que vous m''aurez rapporté le marteau de mon père.', 0),
(38522, 'frFR', 'Au travail. Je pense que ça va vous plaire.', 0),
(38526, 'frFR', 'Faites attention où vous mettez les pieds ici, en première ligne. Ce n''est pas la paisible forge de votre cité flottante.', 0),
(38527, 'frFR', 'Êtes-vous $gprêt:prête; à apprendre ?', 0),
(38532, 'frFR', 'Avez-vous pu mettre la main sur l''un d''eux ?', 0),
(38558, 'frFR', 'Avez-vous trouvé l''oscillateur ?', 0),
(38570, 'frFR', 'Commandant, c''est vous ! Bien, j''ai besoin de quelqu''un de solide dans mon dos.', 0),
(38574, 'frFR', 'Il me faudra des fournitures de construction, commandant. On ne peut pas construire des quais avec de la glace et de la neige.', 0),
(38614, 'frFR', 'Avez-vous pu vous procurer tout l''équipement dont vous aviez besoin ?', 0),
(38617, 'frFR', 'Ce n''est pas grave !', 0),
(38645, 'frFR', 'Les agresseurs sont bel et bien des elfes de la nuit, mais ce ne sont pas du tout ceux que j''ai connus autrefois.', 0),
(38646, 'frFR', 'Hein ? C''est encore vous ?', 0),
(38647, 'frFR', 'Le maïs ne va pas se ramasser tout seul.', 0),
(38655, 'frFR', 'Avez-vous récolté les échantillons de racines ?', 0),
(38662, 'frFR', 'Avez-vous les Larmes d''Élune ?', 0),
(38671, 'frFR', 'Les avez-vous récupérés ?', 0),
(38672, 'frFR', '<Ce levier semble maintenir la porte fermée.>', 0),
(38684, 'frFR', 'Quelle est la raison de ce retard ?', 0),
(38717, 'frFR', 'Avez-vous les clés ?', 0),
(38728, 'frFR', '$n, êtes-vous $gprêt:prête; ?', 0),
(38759, 'frFR', 'Certains de nos chasseurs de démons ont disparu. Les avez-vous vus sur le Rivage du Magma ?', 0),
(38777, 'frFR', 'Qu''est-ce que tu as là, $gmon garçon:ma fille; ?', 0),
(38778, 'frFR', 'Mes chaînes demeurent...', 0),
(38786, 'frFR', 'Vous n''avez pas cassé ma pioche, j''espère ?', 0),
(38789, 'frFR', 'Salutations, mineur. Qu''avez-vous là ?', 0),
(38790, 'frFR', 'Que tenez-vous là, $gmineur:mineuse; ?', 0),
(38791, 'frFR', 'Qu… qu''est-ce que c''est, $gmineur:mineuse; ?', 0),
(38795, 'frFR', 'Vous m''apportez quelque chose de nouveau ?', 0),
(38796, 'frFR', 'On dirait que vous avez été $goccupé:occupée;, là-dessous, mineur.', 0),
(38799, 'frFR', 'Un signe de ma sœur ?', 0),
(38800, 'frFR', 'Est-ce... est-ce que c''est... ?', 0),
(38801, 'frFR', 'Lyrelle, non...', 0),
(38802, 'frFR', 'Ondri…', 0),
(38806, 'frFR', 'Excusez-moi, je dois avoir… attendez, cette odeur vient de VOUS ?', 0),
(38807, 'frFR', 'Qu''est-ce que tu as là, $gmon garçon:ma fille; ?', 0),
(38808, 'frFR', 'Comment se passe votre chasse, $gétranger:étrangère; ?', 0),
(38810, 'frFR', 'Qu''apportez-vous ?', 0),
(38817, 'frFR', 'Avez-vous pu récupérer sa dépouille ?', 0),
(38819, 'frFR', 'Comment évaluez-vous la situation actuelle, $n ?', 0),
(38862, 'frFR', 'Rassemblez autant d''œufs que vous le pouvez et rapportez-les-moi. Je les garderai en sécurité.', 0),
(38909, 'frFR', 'Avez-vous eu de la chance avec les Crins-de-Rive ?', 0),
(38932, 'frFR', 'On dirait des plans d''équipement !', 0),
(38944, 'frFR', 'Je ne dirais pas non à un peu de cachemire...', 0),
(38947, 'frFR', 'Ce sont des créatures tout à fait remarquables, vraiment. J''en gardais une comme familier et monture... mais c''était il y a une éternité.', 0),
(38948, 'frFR', 'Qu''est-ce que vous tenez dans les mains, là ?', 0),
(38949, 'frFR', 'Vous avez de la chance de m''avoir trouvé.', 0),
(38951, 'frFR', 'Votre ami pense que ces aiguilles feront une différence ?', 0),
(38952, 'frFR', 'Qu''est-ce que c''est, $n ?', 0),
(38953, 'frFR', 'Gardez l''œil sur votre ouvrage. Ne perdez pas votre concentration maintenant.', 0),
(38955, 'frFR', 'Rien ne vaut un sac neuf.', 0),
(38957, 'frFR', 'Je ne demande qu’à en découdre.', 0),
(38958, 'frFR', 'Je suis tout près d''achever ces chaussons.', 0),
(38959, 'frFR', 'Je ne savais pas que je serais téléporté ici par magie, sinon j''aurais rassemblé mes affaires moi-même.', 0),
(38960, 'frFR', 'Ne les prenez pas pour des proies faciles. Ils sont aussi vicieux que rusés.', 0),
(38961, 'frFR', 'Qu''avez-vous pu trouver ?', 0),
(38963, 'frFR', 'Allons, $n. Cousons.', 0),
(38965, 'frFR', 'Avez-vous découvert ce qui est arrivé à Lyndras ?', 0),
(38966, 'frFR', 'Ces motifs sont fascinants. Je ne savais pas qu''on pouvait obtenir un tel résultat avec de simples soies.', 0),
(38969, 'frFR', 'Si vous souhaitez apprendre ce que nous allons vous enseigner, il vous faut des bases solides.', 0),
(38971, 'frFR', 'De toute façon, il vaut sans doute mieux que ce soit vous qui combattiez cette chose. Je suis nul avec une arme.', 0),
(38974, 'frFR', 'Poser les bonnes questions vous mènera loin.', 0),
(39000, 'frFR', 'Et ces livres, $n ?', 0),
(39027, 'frFR', 'C''est une rude journée.', 0),
(39043, 'frFR', 'Haut-Roc tient bon !', 0),
(39050, 'frFR', 'Si nous ne savons pas ce qu''ils préparent, nous sommes désavantagés pour les combattre.', 0),
(39051, 'frFR', 'Une démonstration vraiment impressionnante.', 0),
(39061, 'frFR', 'Qu''avez-vous trouvé ?', 0),
(39067, 'frFR', 'Vous réussissez bien dans ces nouvelles missions navales ?', 0),
(39068, 'frFR', 'Vous avez déjà rassemblé ces ressources ? Je suis prêt à commencer cette amélioration !', 0),
(39107, 'frFR', 'Vous les avez tous, jusqu''au dernier ?', 0),
(39117, 'frFR', 'Papa disait toujours que la seule façon dont il quitterait cet endroit, ce serait les pieds devant.$B$BJ''aurais aimé qu''il se trompe.', 0),
(39178, 'frFR', 'J''ai hâte de pouvoir enfin clouer les cornes de l''esprit ancien au mur du Refuge !', 0),
(39179, 'frFR', 'Avez-vous déjà récupéré ma Pierre de sang ?', 0),
(39245, 'frFR', 'Vous réussissez bien dans ces nouvelles missions navales ?', 0),
(39246, 'frFR', 'Vous avez déjà rassemblé ces ressources ? Je suis prêt à commencer cette amélioration !', 0),
(39262, 'frFR', '$n, nous avons besoin que vous scrutiez la grotte avec votre vision spectrale.

Nous devons savoir si des forces de la Légion s''y cachent par magie.', 0),
(39277, 'frFR', 'Que ce groupe de drogbars se retourne contre nous après tant d''années de paix…', 0),
(39278, 'frFR', 'Qu''est-ce que t''as là ?', 0),
(39316, 'frFR', 'Ils ont massacré beaucoup de mes frères et sœurs, mais certains au moins ont réussi à s''échapper. D''autres, en revanche, nous les avons capturés.', 0),
(39326, 'frFR', 'Dites donc, j''espère que vous avez pu retrouver mes provisions perdues. Comment bâtir la confiance entre nous si vous ne faites pas tout ce que je demande ?', 0),
(39327, 'frFR', 'Je n''ai pas le temps de traduire des grimoires ! Les professions mineures sont faites pour ça.', 0),
(39329, 'frFR', 'C''est une bonne chose que les autres artisans du coin fabriquent de tels objets. Je ne pourrais pas concevoir de perdre mon temps à de telles entreprises.', 0),
(39331, 'frFR', 'Plus vite nous récupérerons mes provisions, plus vite nous pourrons retourner au vrai travail.', 0),
(39332, 'frFR', 'Avez-vous trouvé d''autres potions d''eau-de-feu ? Je parie qu''il est tentant d''en siroter une gorgée !', 0),
(39335, 'frFR', 'Qu’avons-nous là ?', 0),
(39336, 'frFR', 'Espérons que vous trouverez la poudre qu''il nous faut...', 0),
(39339, 'frFR', 'J''espère que vous êtes assez $gfort:forte; pour affronter quelques démons ?', 0),
(39340, 'frFR', 'Restaurer le revêtement du creuset n''est pas une mince affaire, $n.', 0),
(39342, 'frFR', 'Ne traînez pas trop, maintenant. Qui sait qui d''autre pourrait être intéressé par vos précieuses burettes.', 0),
(39346, 'frFR', 'Le seul moyen d''être sûr que les burettes fonctionnent, c''est de s''en servir !', 0),
(39348, 'frFR', 'Quel spectacle doivent offrir les Salles des Valeureux ! Il faudra que vous me les décriviez un de ces jours, à votre retour.', 0),
(39349, 'frFR', 'J''espère que Deucus avait raison à propos de ces ingrédients. Ce sera la première fois que je prépare quelque chose comme ça.', 0),
(39350, 'frFR', 'Avez-vous pu monter à bord du navire ? Avez-vous trouvé la poussière ?', 0),
(39351, 'frFR', 'Je prépare le mélange. Dès que vous reviendrez avec le cœur, je commencerai la construction.', 0),
(39354, 'frFR', 'Qu’est-ce que ça donne ?', 0),
(39355, 'frFR', 'On dirait des plans d''équipement !', 0),
(39356, 'frFR', 'On dirait des plans d''équipement !', 0),
(39358, 'frFR', 'On dirait des plans d''équipement !', 0),
(39359, 'frFR', 'On dirait des plans d''équipement !', 0),
(39360, 'frFR', 'On dirait des plans d''équipement !', 0),
(39363, 'frFR', 'On dirait des plans d''équipement !', 0),
(39364, 'frFR', 'On dirait des plans d''équipement !', 0),
(39365, 'frFR', 'On dirait des plans d''équipement !', 0),
(39366, 'frFR', 'On dirait des plans d''équipement !', 0),
(39368, 'frFR', 'On dirait des plans d''équipement !', 0),
(39373, 'frFR', 'Votre taille cache votre force, $n.', 0),
(39387, 'frFR', 'Avez-vous eu de la chance avec Lasan ?', 0),
(39390, 'frFR', 'Vous avez trouvé quelque chose à Azsuna, $n ? Partagez, je vous en prie. Il est si rare que quelque chose d''intéressant franchisse la porte de ma petite boutique tranquille.', 0),
(39392, 'frFR', 'Si vous rapportez les peaux des ours à crins, je pourrai croire que vous êtes $gun assez bon chasseur:une assez bonne chasseuse;...', 0),
(39405, 'frFR', 'Cela semble être le dernier couplet.', 0),
(39425, 'frFR', 'J''ai du pouvoir sur la terre même sans mon cristal, mais ma puissance est bien plus grande avec lui que sans.', 0),
(39426, 'frFR', 'Le Drogbar n''est pas agressif par nature, malgré son aspect menaçant. Mais la tribu Totem-de-Sang nous a causé trop de chagrin, et elle le paiera de son sang.', 0),
(39430, 'frFR', 'Vous cherchez de l''aide ? J''espère que vous avez quelque chose à offrir à mon peuple en échange, $R.', 0),
(39432, 'frFR', 'Ce n''est que le début de ce que vous devez faire pour sauver ce qui reste des arakkoa.', 0),
(39433, 'frFR', 'Je crains que même votre aide ne suffise pas à conjurer le destin des Arakkoas.', 0),
(39439, 'frFR', 'Ces reliques étaient en notre possession depuis des générations, jusqu''à ce que les murlocs posent leurs nageoires visqueuses dessus.', 0),
(39456, 'frFR', 'Torok a-t-il accepté de se joindre à nous ?', 0),
(39487, 'frFR', 'Autrefois, les drogbars ne maîtrisaient que la magie de la terre, mais on dirait qu''ils ont trouvé un moyen de puiser leur pouvoir à d''autres sources.', 0),
(39488, 'frFR', 'Je crois que les drogbars apprennent une magie plus puissante maintenant qu''ils ont le Marteau de Khaz''goroth.', 0),
(39491, 'frFR', 'Les Crin-de-Rive sont une tribu pacifique. Nous fournissons aux autres nourriture et soins en échange de protection et d''équipement.

Mais si on me pousse à bout, je suis prêt à faire un usage plus violent de ma magie.', 0),
(39499, 'frFR', 'Avez-vous réussi à trouver certains de ces restes d''âme dont je vous ai parlé ?', 0),
(39500, 'frFR', 'Avez-vous réussi à trouver certains de ces restes d''âme dont je vous ai parlé ?', 0),
(39501, 'frFR', 'Avez-vous réussi à trouver certains de ces restes d''âme dont je vous ai parlé ?', 0),
(39502, 'frFR', 'Êtes-vous $gallé:allée; au sommet de la Citadelle pour que je puisse vous envoyer au sommet de la Citadelle ?', 0),
(39504, 'frFR', 'Êtes-vous $gallé:allée; au sommet de la Citadelle pour que je puisse vous envoyer au sommet de la Citadelle ?', 0),
(39505, 'frFR', 'Êtes-vous $gallé:allée; au sommet de la Citadelle pour que je puisse vous envoyer au sommet de la Citadelle ?', 0),
(39509, 'frFR', 'Surveillez vos arrières sur les terres de l''Orbite-Sanglante. Ils se battent de manière déloyale.$B$BÉvidemment, nous nous battons encore plus déloyalement.', 0),
(39510, 'frFR', 'Qu''avez-vous appris pour nous, $gcommandant:commandante; ?', 0),
(39511, 'frFR', 'Vous les avez saignés à blanc, commandant ?', 0),
(39512, 'frFR', 'Vous avez trouvé quelque chose, commandant ?', 0),
(39513, 'frFR', 'Qu''est-ce que t''as trouvé là-haut, $gcommandant:commandante; ?', 0),
(39514, 'frFR', 'Vous en avez cassé un ?', 0),
(39529, 'frFR', 'J''espère que la chasse se passe bien ?', 0),
(39567, 'frFR', 'Avant cette guerre, nous autres draeneï n''avions eu que peu de contacts avec l''Orbite-Sanglante. C''était un clan replié sur lui-même qui vivait dans l''une des régions les plus hostiles de Draenor.', 0),
(39568, 'frFR', 'La Prophétesse disait qu''il était toujours sage de connaître son ennemi avant de l''affronter.', 0),
(39569, 'frFR', 'Avez-vous pu obtenir des échantillons de sang ? Je ne m''enquerrai pas de vos méthodes, commandant.', 0),
(39570, 'frFR', 'Qu''avez-vous appris ?', 0),
(39571, 'frFR', 'Ce temple était autrefois un lieu de paix et de solitude. Je crains qu''il ne soit à jamais corrompu.', 0),
(39573, 'frFR', 'L''Exarque Maladaar rapporte que le champ de bataille est en plein chaos. Avez-vous pu tenir bon ?', 0),
(39582, 'frFR', 'On compare nos notes ?', 0),
(39590, 'frFR', 'Un cadeau ironique que vous m''apportez là, challenger.', 0),
(39593, 'frFR', 'Avez-vous réussi à tous les trouver ?', 0),
(39595, 'frFR', 'Qu''apportez-vous là ?$B$BVous me faites honneur, $gétranger:étrangère;.', 0),
(39656, 'frFR', 'Le Zaytsestrel est chargé et prêt à tirer ! Tirez sur n''importe quelle meute de loups. Une fois que les hurleurs auront fui, il sera plus facile de tuer les chefs.', 0),
(39666, 'frFR', 'Trouver Salty ?', 0),
(39670, 'frFR', 'Avez-vous déjà attrapé les lapins ?', 0),
(39675, 'frFR', 'Trouver Kronk ?', 0),
(39687, 'frFR', 'La source de la justice peut rappeler notre passé.', 0),
(39697, 'frFR', 'J''espère que l''Appel du maître n''a pas envoyé trop de vos navires par le fond...?', 0),
(39726, 'frFR', 'Avez-vous acquis des plastrons ?', 0),
(39729, 'frFR', 'Avez-vous pu le trouver ?', 0),
(39763, 'frFR', 'Avez-vous obtenu ce que j''ai demandé ?', 0),
(39764, 'frFR', 'Avez-vous déjà récupéré les réceptacles d''âme ?', 0),
(39765, 'frFR', 'Quel blasphème…', 0),
(39772, 'frFR', 'Avez-vous trouvé mon crâne ?', 0),
(39774, 'frFR', 'Vous devez affaiblir les démons pour que je puisse les piéger.', 0),
(39776, 'frFR', 'Des vers. Pourquoi a-t-il fallu que ce soit des vers ? Je déteste les vers.', 0),
(39781, 'frFR', 'La guerre continue.', 0),
(39786, 'frFR', 'Vous l''avez éliminé ?', 0),
(39787, 'frFR', 'Vous avez mon trophée ?', 0),
(39788, 'frFR', 'La corruption a-t-elle été éliminée ?', 0),
(39792, 'frFR', 'Y a rien de tel que de bonnes vieilles côtes de musquard bien charnues, hein, mon vieux ?', 0),
(39793, 'frFR', 'Veillez à prendre de la bonne marchandise !', 0),
(39830, 'frFR', 'N''y allez pas $gseul:seule;, $gmon garçon:ma fille;. Cet endroit grouille de démons.', 0),
(39842, 'frFR', 'Ne vous laissez pas voir par ces gardes. Ils sont peut-être corrompus, mais ils sont vigilants.', 0),
(39843, 'frFR', 'Quand on vit dans un égout, il faut être prêt à improviser.', 0),
(39847, 'frFR', 'Avez-vous pensé à mettre les points sur les i et les barres sur les t ?', 0),
(39848, 'frFR', '<À votre approche, un silence de mort plane dans l''air.>', 0),
(39849, 'frFR', 'Avez-vous pu vous emparer de la lanterne ?', 0),
(39859, 'frFR', 'J''attends depuis ce matin qu''Addie termine son premier jet.$b$bQu''est-ce que ça peut être dur d''écrire quelques mots sur le plus grand chasseur qui ait jamais vécu ?', 0),
(39863, 'frFR', 'Inutile de dépenser de l''argent pour des cuirasses ou des robes coûteuses. De simples brassards suffiront.', 0),
(39867, 'frFR', 'C''est moi qui rirai le dernier quand Hemet verra la preuve que ce lion magique existe !', 0),
(39875, 'frFR', 'Vous avez bientôt fini d''enchanter ces vélins ?', 0),
(39879, 'frFR', 'Les cristaux ne sont pas la seule chose à laquelle les esprits répondent. Il y en a d''autres, mais c''est une histoire pour un autre jour.', 0),
(39880, 'frFR', 'En jetant ce qui nous a été donné, nous insultons les esprits qui nous ont fait ce présent.', 0),
(39882, 'frFR', 'Si vous êtes vraiment $gun ami:une amie; dans cette guerre, alors soyez mon épée et abattez Glaidalis.', 0),
(39883, 'frFR', 'Content de vous revoir, $n. Avez-vous pris contact avec les taurens ?', 0),
(39884, 'frFR', 'Leur comportement a été si étrange et si soudain. On ne comprend pas pourquoi ils nous ont tourné le dos. Mais c''est inexcusable malgré tout.', 0),
(39904, 'frFR', 'Le bâton est un prolongement de moi-même, et moi du sien. Ce serait agréable de le tenir à nouveau.', 0),
(39906, 'frFR', 'Une fois que j''aurai la puissance dont j''ai besoin, nous mettrons nos forces à l''épreuve.', 0),
(39910, 'frFR', 'Les avez-vous trouvés ? Sont-ils encore intacts ?', 0),
(39916, 'frFR', 'Les cris de mort de la Légion m''apportent un semblant de joie.', 0),
(39921, 'frFR', 'Comment se passe la recherche des composants du bâtonnet ?', 0),
(39923, 'frFR', 'Pensez à amener des amis, ces assemblages sont incroyablement puissants.', 0),
(39931, 'frFR', 'Alors ? Avez-vous les pigments, ou êtes-vous juste en train de me faire perdre mon temps ?', 0),
(39932, 'frFR', 'Mon pigment ?', 0),
(39933, 'frFR', 'Les cartes ne sont là que pour référence, pour la plupart...', 0),
(39937, 'frFR', 'Bien qu''ils soient opposés, l''un ne peut exister sans l''autre.', 0),
(39945, 'frFR', 'Il nous faut ces tablettes si nous voulons progresser dans le déchiffrement de leur langue.', 0),
(39946, 'frFR', 'Le couteau est la dernière clé de mes recherches. Vous avez eu de la chance pour en trouver un ?', 0),
(39949, 'frFR', 'Vous a-t-il causé beaucoup d''ennuis ?', 0),
(39950, 'frFR', 'Qu''avez-vous là ?', 0),
(39953, 'frFR', 'Avez-vous vu des dieux, pendant que vous étiez là-bas ?', 0),
(39954, 'frFR', 'Essayez de ne pas faire trop de dégâts.', 0),
(39957, 'frFR', 'Si vous ne savez pas où trouver du sang de démon, allez à Suramar et regardez autour de vous. Vous finirez bien par trébucher sur un démon tôt ou tard.', 0),
(39958, 'frFR', 'J''espère que vous avez accordé aux créatures une mort clémente ?', 0),
(39990, 'frFR', 'Ça ne devrait pas durer longtemps. Veillez à ce qu''on ne m''interrompe pas pendant mon sort.', 0),
(40000, 'frFR', 'En discutant avec moi, vous n''obtiendrez pas de faucon, au mieux.', 0),
(40002, 'frFR', 'Le geôlier a... la clé...', 0),
(40004, 'frFR', 'Les seigneurs de guerre ennemis sont détruits ?', 0),
(40009, 'frFR', '<Les yeux de Thalyssra se sont ternis et son corps tremble de manière incontrôlable.>', 0),
(40014, 'frFR', 'La guerre continue.', 0),
(40016, 'frFR', 'Je suis heureux que vous continuiez à fréquenter ma boutique, $n. Je suis nul avec une arme. Nous avons besoin d''aventuriers comme vous pour résoudre des affaires comme celle-ci.', 0),
(40024, 'frFR', '<Le tauren renifle l''air.>', 0),
(40026, 'frFR', 'Avez-vous découvert ce qui dévorait la vulpille ? Était-ce une chèvre ? Un castor ? Un sabre-de-nuit ?', 0),
(40029, 'frFR', 'Qu''avez-vous là, herboriste ?', 0),
(40037, 'frFR', 'Comment avancent les recherches ?', 0),
(40039, 'frFR', 'Que la Terre-mère marche à vos côtés, $n.', 0),
(40041, 'frFR', 'Merci d''avoir accepté de faire le voyage, $n.', 0),
(40042, 'frFR', 'J''espère que vous amènerez des amis dans ce voyage, car ce pourrait être votre plus grande leçon.', 0),
(40045, 'frFR', 'Pour le succès de notre affaire, il est très important d''obtenir le soutien des têtards.', 0),
(40046, 'frFR', 'Avez-vous trouvé des réponses, ou davantage de questions ?', 0),
(40047, 'frFR', 'Les poissons-globes explosent si merveilleusement. Pour ronronner, ils peuvent être bien utiles !', 0),
(40048, 'frFR', 'Avez-vous déjà trouvé des runes ?', 0),
(40059, 'frFR', 'Bien qu''ils soient opposés, l''un ne peut exister sans l''autre.', 0),
(40069, 'frFR', 'Pourquoi j''ai besoin de leurs tripes ? Je vous le dirai plus tard. Je ne sais pas si ça vous plaira ou non, mais vous le découvrirez en temps voulu.', 0),
(40070, 'frFR', 'Si nous ne rapportons pas les œufs volés, les aigles sont au bord de l''extinction.', 0),
(40071, 'frFR', 'Éliminez le dompteur Korgrul, pour que nous puissions aussi mettre fin au dressage des vers de siège.', 0),
(40131, 'frFR', 'Comment puis-je vous aider ?', 0),
(40132, 'frFR', '<Kondal vous regarde d''un air sévère.>', 0),
(40134, 'frFR', '<Hemet contemple l''horizon avec convoitise.>', 0),
(40135, 'frFR', 'Quand t''auras fini, je te montrerai un tour ou deux.', 0),
(40138, 'frFR', 'Vous avez trouvé ces peaux ?', 0),
(40139, 'frFR', 'C''est fait ? Montrez-le-moi !', 0),
(40142, 'frFR', 'Avez-vous vu les étincelles ?', 0),
(40145, 'frFR', 'N''oubliez pas d''examiner la bête tout entière, pas seulement ce qui est visible en surface.', 0),
(40147, 'frFR', 'Mère voulait toujours vivre assez longtemps pour me voir mourir. Pourquoi a-t-il fallu que ça arrive !?', 0),
(40149, 'frFR', 'Même si j''AVAIS pu tuer Drakol’nir, je n''aurais jamais pu le traîner jusqu''ici.', 0),
(40153, 'frFR', 'Toi parti longtemps. Toi avoir les écailles ?', 0),
(40154, 'frFR', 'Toi y arriver, peau-fine.', 0),
(40158, 'frFR', 'Vous avez réussi à avoir cette peau ?', 0),
(40159, 'frFR', 'Alors, ce dragon ?', 0),
(40170, 'frFR', 'Ces chasseurs amateurs se sont-ils dispersés ? N''ayez pas peur d''utiliser vos poings si les mots ne suffisent pas.', 0),
(40176, 'frFR', 'J''ai hâte de voir ce que cela donnera.', 0),
(40178, 'frFR', 'Comment avance votre recherche ?', 0),
(40179, 'frFR', 'Les vrykuls vous causent-ils beaucoup d''ennuis ?', 0),
(40181, 'frFR', 'Faites en sorte de pas vous faire capturer, mon gars.', 0),
(40182, 'frFR', 'L''armure de torse est la meilleure armure, je l''ai toujours dit !', 0),
(40183, 'frFR', 'Je commence à penser que nous formons une assez bonne équipe.', 0),
(40185, 'frFR', 'L''armure de mon frère... l''avez-vous retrouvée ?', 0),
(40189, 'frFR', 'Ils sont peut-être ignobles, mais ils savent tout de même fabriquer aussi bien que n''importe quel maître.', 0),
(40192, 'frFR', 'Leurs griffes sont parmi les plus solides que j''aie jamais vues.', 0),
(40194, 'frFR', 'Avez-vous pu récupérer une partie des cargaisons ?', 0),
(40197, 'frFR', 'C''est sans doute le plus grand projet auquel j''aie jamais participé. C''est vraiment passionnant !', 0),
(40198, 'frFR', 'J''espère qu''ils ne sont pas trop abîmés.', 0),
(40199, 'frFR', 'J''aurai beau me creuser la tête, j''sais plus où j''ai laissé cette maudite chose !', 0),
(40201, 'frFR', 'Veillez à ce que ce soit bien douillet !', 0),
(40203, 'frFR', 'La vraie force ne se mesure pas à ce que l''on peut endurer, mais au fait de continuer à endurer quand la force vous manque.', 0),
(40204, 'frFR', 'Ne craignez pas le changement, car c''est la seule façon d''avancer.', 0),
(40207, 'frFR', 'Travailler de nouveau les écailles de dragon serait un grand honneur.', 0),
(40208, 'frFR', 'Il ne va pas simplement le céder, $n. Vous allez devoir livrer un rude combat.', 0),
(40209, 'frFR', 'Vous devrez peut-être vous frayer un chemin à travers une partie de sa progéniture pour l''atteindre.', 0),
(40213, 'frFR', 'Nous nous sommes rencontrés sur le lac. C''était le printemps, et elle portait des lys telluriques...', 0),
(40214, 'frFR', 'Vous êtes vraiment là, n''est-ce pas ?$B$B<Stalriss tend la main et vous pince.>', 0),
(40216, 'frFR', 'Gardez un œil sur la gnome pendant que vous chassez. Elle n''a jamais tenu un fusil de sa vie.', 0),
(40222, 'frFR', 'Vous l''avez ?', 0),
(40228, 'frFR', 'Ne restez pas $gplanté:plantée; là, allez dans le bassin et trouvez cet oiseau !', 0),
(40230, 'frFR', 'La Griffe est impitoyable et en colère. Murchal doit l''arrêter.', 0),
(40235, 'frFR', 'Je sens le pouvoir des cristaux ! Donnez-les-moi !', 0),
(40237, 'frFR', 'C''est une bonne chose que vous vous soyez $goccupé:occupée; de Mar’gok, sinon personne ne serait disponible à l''embauche. La sécurité ogre est toujours efficace, n''est-ce pas ?', 0),
(40265, 'frFR', 'La seule présence $gd''un enchanteur aussi plein:d''une enchanteresse aussi pleine; de vie donne à ma demeure l''étincelle de la vie !', 0),
(40266, 'frFR', '<Taedris contemple fixement Suramar ; il est complètement absorbé par ses pensées.>', 0),
(40300, 'frFR', 'Avez-vous trouvé quelque chose ?', 0),
(40306, 'frFR', 'Avez-vous le grimoire, $r ?', 0),
(40307, 'frFR', 'Avez-vous apporté mes lames,|3-6($r) ?', 0),
(40308, 'frFR', 'Et qu''avons-nous là ?', 0),
(40319, 'frFR', 'Qu''est-ce que c''était ? J''ai entendu une voix familière… ce n''est pas possible.', 0),
(40324, 'frFR', 'Nourrissez Theryn autant qu''il en voudra.', 0),
(40331, 'frFR', 'On va les tuer tous, jusqu’au dernier !', 0),
(40332, 'frFR', 'Throndyr méritait une mort plus honorable.', 0),
(40334, 'frFR', 'Je vous aiderai à rassembler ce dont nous avons besoin.', 0),
(40339, 'frFR', 'Qu''est-ce que tu regardes, tête puante ?', 0),
(40345, 'frFR', 'Toi arriver quand travail être fini.', 0),
(40364, 'frFR', 'Faites vite, $c ! Ces géants des mers ont un appétit insatiable !', 0),
(40368, 'frFR', 'Gardez à l''esprit que les flocons doivent être en parfait état.', 0),
(40424, 'frFR', 'Je m''inquiétais qu''il vous soit arrivé quelque chose dans la forêt. Je suis content de m''être trompé.', 0),
(40469, 'frFR', 'Avez-vous trouvé le contrebandier ? Qu''a-t-il dit ?', 0),
(40517, 'frFR', 'Bienvenue, $n. Je suis ravi que vous ayez survécu à la bataille. Avez-vous quelque chose pour moi ?', 0),
(40520, 'frFR', 'La terre, l''air et l''eau sont des magies que nous avons appris à bien connaître dans notre montagne.', 0),
(40522, 'frFR', 'Des jours sombres nous attendent.', 0),
(40525, 'frFR', 'Comment se passe la recherche de l''anneau ?', 0),
(40526, 'frFR', 'Comment vous en êtes-vous sorti$g:e; ?', 0),
(40527, 'frFR', 'Comment vous en êtes-vous sorti$g:e; ?', 0),
(40528, 'frFR', 'Comment vous en êtes-vous sorti$g:e; ?', 0),
(40529, 'frFR', 'Essayez de ne pas les tacher de sang pendant que vous partez Â« Ã  l''aventure Â».', 0),
(40531, 'frFR', 'Vous l''avez trouvé ? Avez-vous pu récupérer les bijoux ?', 0),
(40532, 'frFR', 'Veillez à ne pas briser la gemme brute. Nous n''avons pas un stock de ces gemmes qui traîne.', 0),
(40533, 'frFR', 'Veillez à ne pas briser la gemme brute. Nous n''avons pas un stock de ces gemmes qui traîne.', 0),
(40534, 'frFR', 'Veillez à ne pas briser la gemme brute. Nous n''avons pas un stock de ces gemmes qui traîne.', 0),
(40539, 'frFR', 'Essayez de ne pas trop attirer l''attention, d''accord ?', 0),
(40542, 'frFR', 'Jabrouf a hâte de regarder ces roches de près.', 0),
(40543, 'frFR', 'Jabrouf a hâte de regarder ces roches de près.', 0),
(40544, 'frFR', 'Jabrouf a hâte de regarder ces roches de près.', 0),
(40546, 'frFR', 'Avez-vous une pierre ?', 0),
(40547, 'frFR', 'Jabrouf est si inquiet !', 0),
(40558, 'frFR', 'Vous allez devoir parcourir le monde entier pour les trouver, j''espère que vous êtes à la hauteur du défi.', 0),
(40559, 'frFR', 'Un livre, vous verrez, est un plan pour l''esprit !', 0),
(40560, 'frFR', 'Il est peu probable que la déesse qui règne sur ce monde vous laisse partir sans combattre. Soyez $gprudent:prudente;, $n.', 0),
(40561, 'frFR', 'Ce sera sans conteste la plus belle pièce de ma collection.', 0),
(40562, 'frFR', 'Oh, comment je savais pour les gemmes sacrenuits ? Eh bien, c''est un secret professionnel.$B$B<Sminx vous adresse un rapide clin d''œil.>', 0),
(40567, 'frFR', 'Est-il en vie ? Mon mari me reviendra-t-il ?', 0),
(40606, 'frFR', 'C''est celui-là ?', 0),
(40613, 'frFR', 'Avez-vous arraché la Garde de Svalna aux griffes de Helya ?', 0),
(40614, 'frFR', 'Les bêtes que vous chassez ont pris la vie de nombreuses personnes.', 0),
(40617, 'frFR', 'Vous devez trouver l''Œil de la nuit !', 0),
(40625, 'frFR', 'Avez-vous trouvé quelque chose ? Je n''ai pas vraiment eu l''occasion de faire mes bagages avant d''être exilé.', 0),
(40634, 'frFR', 'Avez-vous trouvé quelque chose, $n ?', 0),
(40642, 'frFR', 'Avez-vous l''essence ? Il me la faut !', 0),
(40645, 'frFR', 'Tout l''honneur est pour moi de vous rencontrer, druide.', 0),
(40647, 'frFR', 'Avez-vous récupéré les Griffes d’Ursoc ?', 0),
(40657, 'frFR', 'Je sens presque les bâtiments vibrer de puissance.', 0),
(40668, 'frFR', 'Avez-vous récupéré le Cœur ?', 0),
(40672, 'frFR', 'N''osez pas servir un festin à Odyn dans un plat inapproprié. Un tel geste ne ferait que lui attirer son courroux.', 0),
(40673, 'frFR', 'Les Souffrenuit sont devenus… méfiants… depuis la trahison des Sacrenuit. Vous devrez gagner leur respect avant qu''ils ne vous laissent approcher du parchemin.', 0),
(40675, 'frFR', 'Avez-vous accompli les rites comme demandé ?', 0),
(40678, 'frFR', 'Avez-vous les liens ?', 0),
(40683, 'frFR', 'J''espère que vous en avez apporté assez. J''aurai besoin de plus d''énergie avant d''achever mes études.', 0),
(40713, 'frFR', 'Le tome ! Vous l''avez ?', 0),
(40730, 'frFR', 'Vous en avez trouvé assez ?', 0),
(40744, 'frFR', 'Avez-vous ce qu''il me faut, $r ? Nous n''avons pas beaucoup de temps.', 0),
(40747, 'frFR', 'Récupérer l''équipement ici est nécessaire si je veux mettre au point un réseau de téléporteurs pour Thalyssra.', 0),
(40755, 'frFR', 'Avez-vous quelque chose pour moi ?', 0),
(40796, 'frFR', 'Pouvez-vous m''aider ? N''y a-t-il vraiment rien que vous puissiez faire ?', 0),
(40798, 'frFR', '<Noressa vous regarde avec méfiance.>', 0),
(40823, 'frFR', 'Je ne prendrai nul repos tant que le conseil n’aura pas été reformé.', 0),
(40824, 'frFR', 'Rejoignez-moi au bassin de divination, et nous planifierons notre action à partir de là.', 0),
(40830, 'frFR', 'Où est Oculus ?', 0),
(40839, 'frFR', 'C''est à vous de jouer, $n.', 0),
(40854, 'frFR', 'Avez-vous quelque chose à faire réparer ?', 0),
(40866, 'frFR', 'Laissez-moi juste finir ici et je suis à vous.', 0),
(40867, 'frFR', 'Alors ?$B$BVous avez essayé de leur tirer dessus ?', 0),
(40873, 'frFR', 'Et attention, ne trempez pas la poudre, sinon vous ne pourrez plus la faire sécher.', 0),
(40877, 'frFR', 'Je suis content que ce soit vous qui affrontiez un dieu et pas moi.', 0),
(40878, 'frFR', 'Vous pouvez trouver une charge dans n''importe quelle cellule de prison. Il est certain qu''aucun prisonnier n''y a été laissé en vie.', 0),
(40882, 'frFR', 'Ces elfes n''avaient sûrement aucune idée des applications de mécanique quantique de ce mécanisme !', 0),
(40898, 'frFR', 'Avez-vous la chair gangrenée fraîche dont j''ai besoin ?', 0),
(40901, 'frFR', 'Quelles nouvelles d''Aile-Sinistre le Dévoreur ?', 0),
(40904, 'frFR', 'J''ai entendu parler de vos exploits par-delà le portail rouge, $n. Deux mondes vous sont redevables, à vous et à vos compagnons. Qu''est-ce qui vous amène à Reflet-de-Lune ?', 0),
(40919, 'frFR', 'Avez-vous obtenu les peaux ?', 0),
(40929, 'frFR', 'Avez-vous les emblèmes de la Légion ?', 0),
(40947, 'frFR', 'Avez-vous réussi ?', 0);
