INSERT INTO `quest_request_items_locale` (`ID`, `Locale`, `CompletionText`, `VerifiedBuild`) VALUES
(40950, 'frFR', 'C''est tuer ou être tué.', 0),
(40965, 'frFR', 'Comment avance l''éducation ?', 0),
(40967, 'frFR', 'Les avez-vous localisés ?', 0),
(40970, 'frFR', 'C''est fait ?', 0),
(40982, 'frFR', 'Le temps est précieux.', 0),
(40991, 'frFR', 'Le maquereau n''a rien d''extravagant, mais il vous remplira le ventre.', 0),
(40995, 'frFR', 'Comme disait ma maman : si t''as la monnaie, on a un marché.', 0),
(41030, 'frFR', 'Qu’est-ce que c’est ?', 0),
(41036, 'frFR', 'Nous devons nous hâter !', 0),
(41039, 'frFR', 'Avez-vous la recette ?', 0),
(41059, 'frFR', 'Avez-vous réussi les épreuves ?', 0),
(41064, 'frFR', 'Vos lames... elles brillent d''une telle puissance...', 0),
(41097, 'frFR', '<L''Éclat de Vorgos pulse dans votre main.>', 0),
(41098, 'frFR', '<L''éclat de Kozzak bouge, comme si quelque chose l''attirait vers l''emplacement qui lui est réservé.>', 0),
(41107, 'frFR', 'Je m''abstiendrais de manger quoi que ce soit avant de vous être lavé les mains.', 0),
(41123, 'frFR', 'Vous l''avez ?', 0),
(41139, 'frFR', 'Vous avez trouvé la clé ?', 0),
(41140, 'frFR', 'Avez-vous déjà trouvé la clé ?', 0),
(41148, 'frFR', 'Avez-vous servi ceux qui souffrent ?', 0),
(41157, 'frFR', 'Avec tous ces artefacts démoniaques enfouis ici, c''est un miracle que cet endroit soit aussi plein de vie.', 0),
(41160, 'frFR', 'Il y a aussi ceux qui utilisent de tels noyaux pour bien plus que la simple forge. Méfiez-vous de ces êtres.', 0),
(41162, 'frFR', 'D''après ce que je peux déchiffrer, je crois qu''il n''y a que sept ou huit pièces qu''il nous faut...', 0),
(41165, 'frFR', 'Comment avance la recherche ?', 0),
(41166, 'frFR', 'J''adore les bonnes aventures !', 0),
(41168, 'frFR', 'J''ai hâte de lire la suite de cette histoire.', 0),
(41169, 'frFR', 'Un monde de cauchemars, c''est nulle part où quiconque devrait aller.', 0),
(41173, 'frFR', 'Nous pourrons peut-être utiliser cet artefact pour renverser le cours de cette guerre en notre faveur.', 0),
(41176, 'frFR', 'Où en sont les recherches des joyaux ?', 0),
(41178, 'frFR', 'D''après notre hypothèse de travail, vu la quantité de poudre utilisée, cela ne devrait produire qu''un petit choc sur ce dans quoi l''artefact est enfermé.', 0),
(41181, 'frFR', 'Nous devons trouver cet artefact à tout prix !', 0),
(41184, 'frFR', 'Avez-vous déjà récupéré les autres pièces ?', 0),
(41185, 'frFR', 'La clé est manifestement liée à quelque chose ici, à Azsuna.', 0),
(41188, 'frFR', 'Si mes informations sont exactes, je peux trouver l''arme de Haln.', 0),
(41191, 'frFR', 'Si seulement les drogbar étaient plus raisonnables.', 0),
(41193, 'frFR', 'Nous devons veiller à ce que sa dépouille reçoive le respect qu''elle mérite.', 0),
(41207, 'frFR', 'Avez-vous apporté les provisions que nous avons demandées ?', 0),
(41230, 'frFR', 'Avez-vous les collets, $r ?', 0),
(41237, 'frFR', 'Nos tanneurs ont presque épuisé toutes nos réserves de peaux brutes. Pourriez-vous en collecter davantage ?', 0),
(41240, 'frFR', 'Avez-vous apporté les stocks que nous avons demandés ?', 0),
(41256, 'frFR', 'Daglir est jeune et insensé !', 0),
(41277, 'frFR', 'Oui ?', 0),
(41298, 'frFR', 'Oui ?', 0),
(41303, 'frFR', 'Ouais, $gétranger:étrangère;.', 0),
(41307, 'frFR', 'Imaginez un peu, un Lespin original caché sous un tas de feuilles ? Quel gâchis.', 0),
(41314, 'frFR', 'Ouais, $gétranger:étrangère;.', 0),
(41316, 'frFR', 'Oui ?', 0),
(41317, 'frFR', 'Oui ?', 0),
(41318, 'frFR', 'Oui, $gétranger:étrangère; ?', 0),
(41320, 'frFR', 'Avez-vous mes colliers ? Ils ne me servent à rien au cou de ces... créatures.', 0),
(41344, 'frFR', 'Oui ?', 0),
(41345, 'frFR', 'Oui ?', 0),
(41350, 'frFR', 'Ouais, $gétranger:étrangère;.', 0),
(41351, 'frFR', 'Ouais, $gétranger:étrangère;.', 0),
(41367, 'frFR', 'Halte, manant. Quelle affaire avez-vous avec l''illustre Johnny La Classe ?', 0),
(41368, 'frFR', 'Qu''est-ce que c''est ? Vous n''êtes pas mon coursier habituel…', 0),
(41394, 'frFR', 'Ne tardez pas, $C. Plus vous prendrez de temps, plus vous attendrez avant de pouvoir me vénérer comme $gl''un de mes nombreux admirateurs:l''une de mes nombreuses admiratrices;.', 0),
(41410, 'frFR', 'Faites vite, $n.', 0),
(41411, 'frFR', 'Qu''est-ce que c''est ? Vous n''êtes pas mon coursier habituel…', 0),
(41422, 'frFR', 'Êtes-vous prêts ?', 0),
(41465, 'frFR', 'À cause de ce binoclard, de longues années de dur labeur risquent de partir en fumée. On peut perdre sa réputation en un instant, mais la gagner prend du temps.', 0),
(41466, 'frFR', 'Il était si passionné, si déterminé. J''ai vu sa vision, je l''ai créée selon ses spécifications exactes. De magnifiques filigranes et de l''émail au service d''une arme redoutable...', 0),
(41575, 'frFR', '<Le phare reste froid et sombre.>', 0),
(41642, 'frFR', 'Oui ?', 0),
(41643, 'frFR', 'Ouais, $gétranger:étrangère;.', 0),
(41648, 'frFR', 'Oui ?', 0),
(41654, 'frFR', 'Oui ?', 0),
(41655, 'frFR', 'Oui, $gétranger:étrangère; ?', 0),
(41657, 'frFR', 'Vous venez livrer des provisions ?', 0),
(41660, 'frFR', 'Oui ?', 0),
(41661, 'frFR', 'Oui, $gétranger:étrangère; ?', 0),
(41666, 'frFR', 'Oui ?', 0),
(41672, 'frFR', 'Oui ?', 0),
(41673, 'frFR', 'Ouais, $gétranger:étrangère;.', 0),
(41678, 'frFR', 'Oui ?', 0),
(41702, 'frFR', '<Ce desséché semble être en transe, causée par une pierre d''enchantement. Il ne montre aucune agressivité.>', 0),
(41709, 'frFR', 'La maîtresse des marées est une ennemie dangereuse. Il nous faut être tout aussi rusés pour la vaincre.', 0),
(41749, 'frFR', 'C''est fait, alors ?', 0),
(41771, 'frFR', 'Avez-vous récupéré le Cœur de Mur-Céleste ?', 0),
(41773, 'frFR', 'Je dévorerai le cœur de Pyroth avec grand plaisir !', 0),
(41778, 'frFR', 'Alors, quels sont les résultats, $n ?', 0),
(41780, 'frFR', 'Avez-vous déjà trouvé ces ingrédients ? Le temps n''est vraiment pas de votre côté, vous savez.', 0),
(41782, 'frFR', 'Avez-vous récupéré l''eau du puits de lune ? Elle est essentielle à notre tâche !', 0),
(41783, 'frFR', 'Avez-vous récupéré les offrandes ?', 0),
(41802, 'frFR', 'Vous revoilà en un seul morceau. Quelles nouvelles ?', 0),
(41804, 'frFR', 'Toujours heureux d''aider $gun ami:une amie;.', 0),
(41834, 'frFR', 'Enchanté de faire votre connaissance.', 0),
(41840, 'frFR', 'Avez-vous trouvé d''autres éclats ?', 0),
(41851, 'frFR', '<Sylara vous salue d''un signe de tête.>', 0),
(41889, 'frFR', 'J''ai hâte de voir ce que ça donnera.', 0),
(41891, 'frFR', 'J''espère que vous ne ralentissez pas mes recherches volontairement, $r.', 0),
(41897, 'frFR', 'Quelle bassesse le Marteau du crépuscule complote-t-il cette fois ?', 0),
(41915, 'frFR', 'Où est le maître ?', 0),
(41920, 'frFR', 'On dit que les Crocs du Dévoreur n''ont pas d''égal ; si c''est vrai, ils valent n''importe quel prix.', 0),
(41921, 'frFR', 'Je n''arrive pas à y croire...', 0),
(41934, 'frFR', 'La marque de la Malédiction sera mienne !', 0),
(42001, 'frFR', 'Cette salle abrite de nombreux vestiges puissants d''un ordre de mages comme le monde moderne n''en a jamais connu.

Ces parchemins ne sont qu''un début.', 0),
(42036, 'frFR', 'Avez-vous retrouvé l''Idole de la Nature ?', 0),
(42049, 'frFR', 'Combien d''éclats avons-nous collectés ?', 0),
(42079, 'frFR', 'Ne vous inquiétez pas, ça ne lui fera pas mal.', 0),
(42098, 'frFR', 'Avez-vous déjà récupéré l''âme ?', 0),
(42100, 'frFR', 'Avec assez de fragments d''âme, nous devrions disposer du pouvoir nécessaire pour créer l''ancre.', 0),
(42103, 'frFR', 'Nous devrons nourrir la pierre de sang avant qu''elle soit assez puissante pour contrôler les sœurs érédars.', 0),
(42126, 'frFR', 'Comment se passe la mission ?', 0),
(42128, 'frFR', 'Avez-vous tout obtenu, $gmon ami:mon amie; ?', 0),
(42129, 'frFR', 'Y a-t-il eu beaucoup de morts ?', 0),
(42147, 'frFR', 'Avez-vous pris contact avec nos sympathisants ?', 0),
(42149, 'frFR', 'J''espère que nous avons trouvé tous les livres.', 0),
(42158, 'frFR', 'N''oubliez pas : tout est de la science si on le note par écrit !', 0),
(42171, 'frFR', 'Je me suis dit que j''allais fouiner un peu avant de vous retrouver à la rotonde. Malheureusement, mon sort d''invisibilité s''est dissipé au mauvais moment. Je suis content que vous m''ayez trouvé ! Qu''est-ce que vous avez là, $n ?', 0),
(42184, 'frFR', 'Nos défenseurs sont-ils revenus du Paradis avec de bonnes nouvelles ?', 0),
(42194, 'frFR', 'Rapportez-vous les héritages de ma famille, $R ?', 0),
(42204, 'frFR', 'Gyallarhorn, $n. Est-il enfin avec vous ?', 0),
(42206, 'frFR', 'Pensez-vous que nous ayons assez éclairci leurs rangs ?', 0),
(42271, 'frFR', 'Oh non…', 0),
(42365, 'frFR', 'Avez-vous pu trouver le Sang de Sargeras ?', 0),
(42371, 'frFR', 'Je dois admettre que la recherche scientifique sérieuse est une affaire extrêmement fatigante.', 0),
(42375, 'frFR', 'Ne me demandez pas où j''ai trouvé l''œil. Au pire, je vous le dis et ça devient gênant entre nous.', 0),
(42391, 'frFR', 'Je n''irai nulle part sans Cora.', 0),
(42406, 'frFR', 'Faites attention à ne pas tuer le molosse corrompu en le piégeant. Il me faut le sujet vivant pour effectuer mes tests.', 0),
(42408, 'frFR', 'L''enchantement ne peut être achevé sans les composants appropriés.', 0),
(42421, 'frFR', 'Aidez-nous et nous vous récompenserons.', 0),
(42423, 'frFR', 'Qu''avez-vous découvert, $n ?', 0),
(42424, 'frFR', 'Vos champions ont-ils découvert quelque chose de notable sur l''archimage Vargoth ?', 0),
(42425, 'frFR', 'Je n''ai jamais particulièrement aimé les hauteurs.', 0),
(42432, 'frFR', 'Jamais le Cauchemar ne s''est répandu dans notre monde. Notre devoir est de trouver la racine de ce mal et de la détruire.', 0),
(42435, 'frFR', 'Avez-vous trouvé la Perle et les parchemins ?', 0),
(42438, 'frFR', 'Avez-vous les graines de Tel''andu ?', 0),
(42445, 'frFR', 'Croa-croa ?', 0),
(42452, 'frFR', 'Avons-nous déjà trouvé ce qu''il nous faut ?', 0),
(42455, 'frFR', 'Vous avez trouvé tout ce qu''il y avait dans mon coffre-fort ? J''espère que les défenses ne vous ont pas trop gêné$g:e;.', 0),
(42476, 'frFR', 'J''espère que vous avez réussi ?', 0),
(42477, 'frFR', 'Eh bien, qu''a dit Daio ?', 0),
(42483, 'frFR', 'Hum…', 0),
(42488, 'frFR', 'Vous l''avez trouvé ?', 0),
(42489, 'frFR', 'Qu''avez-vous trouvé ?', 0),
(42491, 'frFR', 'Vous l''avez trouvé ?', 0),
(42501, 'frFR', '<Toute information pourrait être inestimable pour traquer les cultistes.>', 0),
(42502, 'frFR', '<Si Whitley est aussi important dans le culte que le disent vos sources, il doit forcément avoir sur lui quelque chose d''utile.>', 0),
(42521, 'frFR', 'Avez-vous pu localiser Milhouse ?', 0),
(42534, 'frFR', 'Avez-vous les têtes de mes ennemis ? Je veux contempler chacun de leurs visages...', 0),
(42536, 'frFR', 'Il nous faut l''épée Trol''kalar pour ouvrir ce tombeau. L''avez-vous trouvée ?', 0),
(42539, 'frFR', '<En privant la Main des réactifs de son rituel, vous avez réussi à gagner un temps précieux.>', 0),
(42584, 'frFR', 'Ne tardez pas. Le message doit être envoyé.', 0),
(42590, 'frFR', 'Merci pour votre gentillesse. Sincèrement.', 0),
(42622, 'frFR', 'Vous sentez le rythme ?', 0),
(42635, 'frFR', 'Comment se passe la quête du savoir ?', 0),
(42639, 'frFR', 'Il nous faudra la protection de l''amulette pour continuer.', 0),
(42640, 'frFR', 'Qu’est-ce que c’est que ça ?', 0),
(42654, 'frFR', 'Avez-vous déjà récupéré le chêne ?', 0),
(42655, 'frFR', 'Avez-vous déjà extrait le minerai ?', 0),
(42656, 'frFR', 'Il nous faudra des armes spéciales si nous voulons abattre Hakkar et ses molosses.', 0),
(42660, 'frFR', 'La pierre de sang gagnera en puissance après avoir consumé le cœur de Cordana.', 0),
(42678, 'frFR', '$n, avez-vous réussi ? Avez-vous l''Œil du corbeau ?', 0),
(42691, 'frFR', 'L''intérieur du ver de puissance contient une substance magique à laquelle le chiot gangrechien ne peut résister.', 0),
(42693, 'frFR', 'J''aurais apporté mes propres focalisateurs de sorts si QUELQU''UN ne m''avait pas pressé...', 0),
(42694, 'frFR', 'Merci pour votre aide, $c.', 0),
(42707, 'frFR', 'Avez-vous déjà obtenu une fiole d''eau arcanique ?', 0),
(42730, 'frFR', 'Après tous les sacrifices que nous faisons, aller ensuite rejoindre la Légion me semble tout simplement impensable.', 0),
(42732, 'frFR', 'Avez-vous obtenu l''Obliterum ?', 0),
(42733, 'frFR', '$n, avez-vous ce qu''Allari vous a demandé de récolter pour le carburant ?', 0),
(42737, 'frFR', '<De l''énergie gangrenée bouillonne dans une pierre runique. Désactivez-la avec la rune appropriée.>', 0),
(42738, 'frFR', '<Cette pierre runique retient Malassa l''Ombre captive. Désactivez-la à l''aide de la rune de Ragnar.>', 0),
(42739, 'frFR', '<Qui sait combien de temps encore Malassa l''Ombre tiendra entre les mains de vrykul gangrenés ? Mieux vaut s''occuper de la pierre runique au plus vite.>', 0),
(42752, 'frFR', 'Est-ce que ça a marché, $n ? Avez-vous réussi à obtenir la Clé en sargérite ?', 0),
(42753, 'frFR', 'Avez-vous réussi, $n ? Avez-vous récupéré la clé cruciale sargerite ?', 0),
(42754, 'frFR', 'Quelle façon cruelle de mettre un chariot en mouvement. Ils utilisent des âmes pour ça... Je ne veux même pas savoir ce qui leur arrive là-bas.', 0),
(42758, 'frFR', 'J''ai besoin de trente-trois dents de requin tranchantes comme des rasoirs. N''essayez pas de me rouler, mon garçon.', 0),
(42766, 'frFR', 'Ah, il revient. Le lokdu a-t-il apporté ce que je cherche ?', 0),
(42767, 'frFR', 'Ah, il revient. Le lokdu a-t-il apporté ce que je cherche ?', 0),
